INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('6', 'CSA17', 'I. INTRODUCTION', '<h3>I. INTRODUCTION</h3>\r\n\r\n<h4>1. What is AI? <small>(Difficulty: easy)</small></h4>\r\n<ul>\r\n  <li><strong>Thinking Humanly:</strong> Cognitive modeling approach, focuses on making machines think like humans do.</li>\r\n  <li><strong>Thinking Rationally:</strong> \"Laws of thought\" approach, where AI systems are designed to reason logically.</li>\r\n  <li><strong>Acting Humanly:</strong> Turing test approach, assessing a machine\'s ability to exhibit human-like intelligent behavior.</li>\r\n  <li><strong>Acting Rationally:</strong> Rational agent approach, where AI systems act to achieve the best possible outcome.</li>\r\n</ul>\r\n\r\n<h4>2. AI Problems & Foundations <small>(Difficulty: easy)</small></h4>\r\n<p><strong>AI Problems:</strong></p>\r\n<ul>\r\n  <li>Knowledge Representation – how to store and organize information.</li>\r\n  <li>Natural Language Processing (NLP) – enabling computers to understand and generate human language.</li>\r\n  <li>Planning – devising sequences of actions to achieve goals.</li>\r\n  <li>Robotics – design, construction, and operation of robots.</li>\r\n  <li>Speech Processing – enabling understanding and response to spoken language.</li>\r\n</ul>\r\n<p><strong>Foundations of AI:</strong></p>\r\n<ul>\r\n  <li>Philosophy, Mathematics, Economics</li>\r\n  <li>Neuroscience, Psychology</li>\r\n  <li>Computer Engineering, Control Theory & Cybernetics</li>\r\n  <li>Linguistics</li>\r\n</ul>\r\n\r\n<h4>3. History of AI (Key Periods) <small>(Difficulty: easy)</small></h4>\r\n<ul>\r\n  <li>1943–1955: Gestation of AI</li>\r\n  <li>1956: Birth of AI (Dartmouth Workshop)</li>\r\n  <li>1952–1969: Early enthusiasm</li>\r\n  <li>1966–1973: Dose of reality</li>\r\n  <li>1969–1979: Knowledge-based systems</li>\r\n  <li>1980–Present: Practical AI applications</li>\r\n  <li>1986–Present: Neural networks resurgence</li>\r\n  <li>1987–Present: Scientific method in AI</li>\r\n  <li>1995–Present: Intelligent agents</li>\r\n  <li>2001–Present: Big data revolution</li>\r\n</ul>\r\n\r\n<h4>4. Intelligent Agents <small>(Difficulty: medium)</small></h4>\r\n<ul>\r\n  <li><strong>Definition:</strong> An agent perceives environment via sensors, acts using actuators.</li>\r\n  <li><strong>Agent Function:</strong> Maps percept sequence → action.</li>\r\n  <li><strong>Agent Program:</strong> Implementation of agent function (code/hardware).</li>\r\n  <li><strong>Rationality:</strong> Acts to achieve the best expected outcome.</li>\r\n</ul>\r\n\r\n<h4>5. Environments (PEAS Framework) <small>(Difficulty: medium)</small></h4>\r\n<p><strong>PEAS:</strong></p>\r\n<ul>\r\n  <li>Performance Measure</li>\r\n  <li>Environment</li>\r\n  <li>Actuators</li>\r\n  <li>Sensors</li>\r\n</ul>\r\n<p><strong>Task Environment Properties:</strong></p>\r\n<ul>\r\n  <li>Fully vs. Partially Observable</li>\r\n  <li>Single-agent vs. Multi-agent</li>\r\n  <li>Deterministic vs. Stochastic</li>\r\n  <li>Episodic vs. Sequential</li>\r\n  <li>Static vs. Dynamic</li>\r\n  <li>Discrete vs. Continuous</li>\r\n  <li>Known vs. Unknown</li>\r\n</ul>\r\n\r\n<h4>6. Structure of Agents <small>(Difficulty: medium)</small></h4>\r\n<ul>\r\n  <li><strong>Simple Reflex Agents:</strong> Act only on current percept (Condition–Action rules).</li>\r\n  <li><strong>Model-Based Reflex Agents:</strong> Maintain internal state + update with sensors.</li>\r\n  <li><strong>Goal-Based Agents:</strong> Choose actions to achieve explicit goals.</li>\r\n  <li><strong>Utility-Based Agents:</strong> Maximize happiness/utility when goals conflict.</li>\r\n</ul>', 'easy');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('7', 'CSA17', 'II. SEARCHING TECHNIQUES', '<h3>II. SEARCHING TECHNIQUES</h3>\r\n\r\n<h4>1. Problem-Solving Agents <small>(Difficulty: medium)</small></h4>\r\n<p><strong>Definition:</strong> Goal-based agents that employ search algorithms to discover a sequence of actions from initial state to goal state.</p>\r\n<p><strong>Steps:</strong></p>\r\n<ol>\r\n  <li>Goal Formulation – Defining the desired end state.</li>\r\n  <li>Problem Formulation – Translating goal into a search problem.</li>\r\n  <li>Search for a solution – Exploring state space to find a path.</li>\r\n  <li>Execute the solution – Carrying out the sequence of actions found.</li>\r\n</ol>\r\n<p><strong>Toy Problems:</strong> 8-Puzzle, 8-Queens, Water Jug, Cryptarithmetic.</p>\r\n<p><strong>Real-World Problems:</strong> TSP, VLSI Layout, Robot Navigation, Assembly Sequencing.</p>\r\n\r\n<h4>2. Searching for a Solution <small>(Difficulty: medium)</small></h4>\r\n<p><strong>Process:</strong> Exploring state space as a search tree.</p>\r\n<p><strong>Components:</strong></p>\r\n<ul>\r\n  <li><strong>State:</strong> Configuration of the problem.</li>\r\n  <li><strong>Parent Node:</strong> Node expanded to generate current node.</li>\r\n  <li><strong>Action:</strong> Operation applied to parent node.</li>\r\n  <li><strong>Path Cost g(n):</strong> Total cost to reach node n.</li>\r\n  <li><strong>Depth:</strong> Steps from root to node.</li>\r\n</ul>\r\n<p><strong>Performance Criteria:</strong></p>\r\n<ul>\r\n  <li>Completeness – Finds solution if one exists.</li>\r\n  <li>Optimality – Finds least-cost solution.</li>\r\n  <li>Time Complexity – Computation time.</li>\r\n  <li>Space Complexity – Memory usage.</li>\r\n</ul>\r\n\r\n<h4>3. Uninformed Search Strategies <small>(Difficulty: medium)</small></h4>\r\n<p><strong>Definition:</strong> Use only problem definition, no extra knowledge.</p>\r\n<p><strong>Breadth-First Search (BFS):</strong></p>\r\n<ul>\r\n  <li>Expands shallowest node first.</li>\r\n  <li>Complete: Yes.</li>\r\n  <li>Optimal: Yes (equal step costs).</li>\r\n  <li>Time/Space: O(b^d).</li>\r\n</ul>\r\n<p><strong>Uniform-Cost Search (UCS):</strong></p>\r\n<ul>\r\n  <li>Expands node with lowest path cost g(n).</li>\r\n  <li>Uses priority queue.</li>\r\n</ul>\r\n<p><strong>Depth-First Search (DFS):</strong></p>\r\n<ul>\r\n  <li>Expands deepest node first.</li>\r\n  <li>Backtracks on dead end.</li>\r\n  <li>Complete: No (can loop).</li>\r\n  <li>Optimal: No.</li>\r\n  <li>Time: O(b^m).</li>\r\n  <li>Space: O(bm).</li>\r\n</ul>\r\n\r\n<h4>4. Informed (Heuristic) Search Strategies <small>(Difficulty: hard)</small></h4>\r\n<p><strong>Definition:</strong> Use heuristics (problem-specific knowledge) to guide search.</p>\r\n<p><strong>Heuristic Function h(n):</strong> Estimate of cost from node n to goal.</p>\r\n<p><strong>Greedy Best-First Search:</strong></p>\r\n<ul>\r\n  <li>Expands node minimizing h(n).</li>\r\n  <li>Complete: No.</li>\r\n  <li>Optimal: No.</li>\r\n</ul>\r\n<p><strong>A* Search:</strong></p>\r\n<ul>\r\n  <li>Uses f(n) = g(n) + h(n).</li>\r\n  <li>g(n): Actual cost from start.</li>\r\n  <li>h(n): Estimated cost to goal.</li>\r\n  <li>If h(n) is admissible → A* is optimal.</li>\r\n</ul>\r\n\r\n<h4>5. Local Search and Optimization <small>(Difficulty: hard)</small></h4>\r\n<p><strong>Definition:</strong> Operate on single current state, memory-efficient.</p>\r\n<p><strong>Hill-Climbing:</strong></p>\r\n<ul>\r\n  <li>Moves to neighbor with highest value.</li>\r\n  <li>Limitation: Gets stuck at local maxima.</li>\r\n</ul>\r\n<p><strong>Simulated Annealing:</strong></p>\r\n<ul>\r\n  <li>Like hill-climbing but accepts some bad moves.</li>\r\n  <li>Probability decreases over time (cooling).</li>\r\n</ul>\r\n<p><strong>Genetic Algorithms:</strong></p>\r\n<ul>\r\n  <li>Population-based, inspired by evolution.</li>\r\n  <li>Uses selection, crossover, mutation.</li>\r\n</ul>\r\n\r\n<h4>6. Constraint Satisfaction Problems (CSPs) <small>(Difficulty: medium)</small></h4>\r\n<p><strong>Definition:</strong> Assign values to variables under constraints.</p>\r\n<p><strong>Examples:</strong></p>\r\n<ul>\r\n  <li><strong>Map Coloring:</strong> No two adjacent regions share same color.</li>\r\n  <li><strong>Cryptarithmetic:</strong> Assign digits to letters (SEND+MORE=MONEY).</li>\r\n  <li><strong>4-Queens:</strong> Place queens so none attack each other.</li>\r\n</ul>\r\n\r\n<h4>7. Adversarial Search (Game Playing) <small>(Difficulty: hard)</small></h4>\r\n<p><strong>Definition:</strong> Search with competing opponent (e.g., games).</p>\r\n<p><strong>Minimax Algorithm:</strong></p>\r\n<ul>\r\n  <li>Recursive, explores game tree.</li>\r\n  <li>Chooses move maximizing own score, assuming opponent optimal.</li>\r\n</ul>\r\n<p><strong>Alpha-Beta Pruning:</strong></p>\r\n<ul>\r\n  <li>Optimization of minimax.</li>\r\n  <li>Prunes branches that don\'t affect decision.</li>\r\n</ul>', 'medium');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('8', 'CSA17', 'III. KNOWLEDGE AND REASONING', '<h2>1. Logical Agents (Difficulty level: medium)</h2>\n    <ul>\n        <li><b>Definition:</b> These are agents specifically designed with the capability to represent knowledge about their environment and to reason about it logically.</li>\n        <li><b>Knowledge Base (KB):</b> A central component, comprising a set of formal sentences that represent known facts and beliefs about the world.</li>\n        <li><b>Inference Engine:</b> The mechanism responsible for deriving new sentences (conclusions) from the Knowledge Base through logical rules.</li>\n        <li><b>Key Functions:</b>\n            <ul>\n                <li>TELL: Add new facts to the Knowledge Base.</li>\n                <li>ASK: Query the Knowledge Base to check if a statement is true or false.</li>\n            </ul>\n        </li>\n    </ul>\n\n    <h2>2. Propositional Logic (Difficulty level: medium)</h2>\n    <ul>\n        <li><b>Definition:</b> A simple form of logic based on propositions that are either true or false.</li>\n        <li><b>Atomic Sentences:</b> Single proposition symbols (e.g., P, Q).</li>\n        <li><b>Complex Sentences:</b> Built using connectives: ¬ (not), ∧ (and), ∨ (or), ⇒ (if...then), ⇔ (if and only if).</li>\n        <li><b>Key Concepts:</b> Entailment, Soundness, Completeness.</li>\n    </ul>\n\n    <h2>3. First-Order Logic (Difficulty level: hard)</h2>\n    <ul>\n        <li><b>Definition:</b> More expressive logic that includes objects, relations, and quantifiers.</li>\n        <li><b>Basic Elements:</b> Constants, Predicates, Functions.</li>\n        <li><b>Quantifiers:</b> ∀ (for all), ∃ (there exists).</li>\n    </ul>\n\n    <h2>4. Inference in First-Order Logic (Difficulty level: hard)</h2>\n    <ul>\n        <li><b>Unification:</b> Process of finding substitutions for variables to make two expressions identical.</li>\n        <li><b>Forward Chaining:</b> Data-driven reasoning from known facts.</li>\n        <li><b>Backward Chaining:</b> Goal-driven reasoning starting from the query.</li>\n        <li><b>Resolution:</b> Rule used for theorem proving by refutation.</li>\n    </ul>', 'medium');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('9', 'CSA17', 'IV. LEARNING', '<h2>1. Learning from Observation (Difficulty level: medium)</h2>\n    <p>An agent improves performance through experience and feedback.</p>\n    <h3>Learning Agent</h3>\n    <p>Components of a learning agent:</p>\n    <ul>\n        <li><b>Performance Element</b> – Chooses actions.</li>\n        <li><b>Critic</b> – Provides feedback on performance.</li>\n        <li><b>Learning Element</b> – Improves the agent.</li>\n        <li><b>Problem Generator</b> – Suggests exploratory actions.</li>\n    </ul>\n    <h3>Types of Learning</h3>\n    <ul>\n        <li><b>Supervised Learning</b> – Learns from labeled data.</li>\n        <li><b>Unsupervised Learning</b> – Discovers patterns from unlabeled data.</li>\n        <li><b>Reinforcement Learning</b> – Learns by trial and error with rewards/penalties.</li>\n    </ul>\n\n    <h2>2. Inductive Learning and Decision Trees (Difficulty level: medium)</h2>\n    <p>Generalizing from examples to rules and models.</p>\n    <ul>\n        <li><b>Inductive Learning</b> – Infers rules from observations.</li>\n        <li><b>Decision Trees</b> – Tree model for classification and regression.</li>\n    </ul>\n\n    <h2>3. Statistical Learning (Difficulty level: hard)</h2>\n    <ul>\n        <li><b>Bayes Rule</b> – Updates probability with new evidence.</li>\n        <li><b>Complete Data</b> – Uses maximum likelihood estimation.</li>\n        <li><b>Incomplete Data</b> – Uses EM (Expectation–Maximization) algorithm.</li>\n    </ul>\n\n    <h2>4. Neural Networks (Difficulty level: hard)</h2>\n    <ul>\n        <li><b>Structure</b> – Input layer, hidden layers, output layer.</li>\n        <li><b>Activation Functions</b> – Step, sigmoid, ReLU, etc.</li>\n        <li><b>Types</b> – Perceptrons, Multi-layer, Recurrent (RNNs).</li>\n    </ul>\n\n    <h2>5. Kernel Machines (SVMs) (Difficulty level: hard)</h2>\n    <ul>\n        <li><b>Goal</b> – Find optimal hyperplane for classification.</li>\n        <li><b>Kernel Trick</b> – Map data into higher dimensions.</li>\n    </ul>\n\n    <h2>6. Reinforcement Learning (Difficulty level: hard)</h2>\n    <ul>\n        <li><b>Agent & Environment</b> – Learns through interaction.</li>\n        <li><b>Rewards</b> – Positive or negative feedback signals.</li>\n        <li><b>Policy</b> – Strategy used by the agent.</li>\n        <li><b>Exploration vs Exploitation</b> – Balance between trying new actions and using known strategies.</li>\n    </ul>', 'easy');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('10', 'CSA17', 'V. SEARCH ENGINE OPTIMIZATION (SEO)', '<h2>V. SEARCH ENGINE OPTIMIZATION (SEO)</h2>\n    <ul>\n        <li><b>1. Introduction to Search Engines (Difficulty level: easy)</b>\n            <ul>\n                <li>Definition: A search engine is a web-based tool designed to enable users to efficiently locate information and resources on the vast World Wide Web.</li>\n                <li>Examples: Google, Yahoo!, Bing.</li>\n                <li>Types:\n                    <ul>\n                        <li>Crawler-based engines</li>\n                        <li>Human-powered directories</li>\n                        <li>Hybrid engines</li>\n                    </ul>\n                </li>\n            </ul>\n        </li>\n        <li><b>2. Search Techniques (Difficulty level: easy)</b>\n            <ul>\n                <li>Boolean Searching</li>\n                <li>Phrase Searching</li>\n                <li>Wildcard/Truncation Searching</li>\n            </ul>\n        </li>\n        <li><b>3. Website and Keyword Optimization (Difficulty level: medium)</b>\n            <ul>\n                <li>Website Domain & Layout</li>\n                <li>Keyword Optimization\n                    <ul>\n                        <li>Keyword Prominence</li>\n                        <li>Keyword Frequency/Density</li>\n                    </ul>\n                </li>\n                <li>Meta Tag Optimization</li>\n                <li>Title Tag Optimization</li>\n                <li>Anchor Tag Optimization</li>\n                <li>XHTML Validation</li>\n            </ul>\n        </li>\n    </ul>', 'medium');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('11', 'CSA57', 'Unit 1: Introduction to Computers', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Unit 1: Introduction to Computers</title>\n</head>\n<body>\n\n    <div>\n        <h1>Unit 1: Introduction to Computers</h1>\n        \n        <div>\n            <h2>Overview of Computers</h2>\n            <p>\n                Think of a computer as a super-smart machine that takes in information, processes it, and gives you something useful back. It\'s a tool that helps us do work, communicate, and have fun.\n            </p>\n            \n            <div>\n                <div>\n                    <h3>The Journey of Computing</h3>\n                    <p>Computers didn\'t just appear overnight. They evolved from simple tools like the <b>Abacus</b> for basic math to the giant, room-sized <b>ENIAC</b>. Each invention, like <b>Babbage\'s engines</b> and <b>Hollerith\'s punch cards</b>, built on the last to make computers faster and more powerful.</p>\n                </div>\n                <div>\n                    <h3>What Makes a Computer Great?</h3>\n                    <p>Computers have amazing qualities that we rely on every day. They are incredibly <b>fast</b>, performing millions of calculations in a fraction of a second. They have a huge <b>storage capacity</b> to remember everything from photos to videos. They are highly <b>accurate</b>, giving you the right answer every time. And they are <b>versatile</b>, meaning they can be used for a wide variety of tasks, from writing a report to playing a game.</p>\n                </div>\n            </div>\n        </div>\n\n        <div>\n            <h2>Classification of Computers</h2>\n            <p>\n                Computers come in many different types, each designed for a specific purpose. We can group them based on how they work, what they\'re used for, and how big they are.\n            </p>\n            <div>\n                <div>\n                    <h3>How They Work (Operating Principles)</h3>\n                    <ul>\n                        <li><b>Analog Computers:</b> These work with continuous, changing information, like the temperature on a thermometer.</li>\n                        <li><b>Digital Computers:</b> These work with clear, distinct numbers, like your phone or laptop.</li>\n                        <li><b>Hybrid Computers:</b> These are a mix of both analog and digital computers.</li>\n                    </ul>\n                </div>\n                <div>\n                    <h3>What They\'re Used For (Applications)</h3>\n                    <ul>\n                        <li><b>General Purpose:</b> These are computers for everyday tasks, like a PC used for work and games.</li>\n                        <li><b>Special Purpose:</b> These are built for one specific job, like the computer that controls a spacecraft.</li>\n                    </ul>\n                </div>\n                <div>\n                    <h3>Size and Power (Capability)</h3>\n                    <ul>\n                        <li><b>Microcomputers:</b> Your desktop or laptop at home is a microcomputer.</li>\n                        <li><b>Minicomputers:</b> These are more powerful than microcomputers, often used by small companies.</li>\n                        <li><b>Mainframe Computers:</b> Huge and super-fast, these are used by big companies and banks to handle massive amounts of data.</li>\n                        <li><b>Supercomputers:</b> The most powerful of all, these are used for complex tasks like weather forecasting and scientific research.</li>\n                    </ul>\n                </div>\n            </div>\n        </div>\n    </div>\n\n</body>\n</html>\n\n', 'easy');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('12', 'CSA17', 'I. INTRODUCTION', '<!-- Section 1: What is AI? -->\r\n<div style=\"background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 15px; border-radius: 8px; margin: 20px 0 15px 0; font-size: 1.2em; font-weight: bold;\">\r\n    1. What is Artificial Intelligence?\r\n</div>\r\n\r\n<img src=\"https://media.geeksforgeeks.org/wp-content/uploads/20241106171024318092/Artificial-Neural-Networks.webp\" alt=\"AI Neural Network Concept\" style=\"width: 100%; max-width: 400px; height: auto; border-radius: 8px; margin: 10px 0; box-shadow: 0 2px 8px rgba(0,0,0,0.1);\">\r\n\r\n<p style=\"font-family: Arial, sans-serif; line-height: 1.6;\"><strong>Artificial Intelligence (AI)</strong> is the simulation of human intelligence in machines programmed to think and learn like humans. AI encompasses various approaches to creating intelligent systems:</p>\r\n\r\n<div style=\"background: #f8f9fa; border-left: 4px solid #007bff; padding: 15px; margin: 15px 0; border-radius: 0 8px 8px 0;\">\r\n    <h4 style=\"margin-top: 0;\">Four Approaches to AI:</h4>\r\n    <ul style=\"font-family: Arial, sans-serif; line-height: 1.6;\">\r\n        <li><strong>Thinking Humanly</strong> – Cognitive Modeling Approach: Systems that model human reasoning processes and cognitive functions.</li>\r\n        <li><strong>Thinking Rationally</strong> – Laws of Thought: Systems that focus on logical reasoning, formal logic, and mathematical deduction.</li>\r\n        <li><strong>Acting Humanly</strong> – Turing Test Approach: Systems whose behavior is indistinguishable from human behavior.</li>\r\n        <li><strong>Acting Rationally</strong> – Rational Agent Approach: Systems that act to achieve the best possible outcomes under uncertainty.</li>\r\n    </ul>\r\n</div>\r\n\r\n<div style=\"background: #e8f5e8; border: 1px solid #28a745; padding: 12px; border-radius: 6px; margin: 10px 0; font-style: italic; font-family: Arial, sans-serif;\">\r\n    <strong>Real-World Examples:</strong><br>\r\n    • <strong>Acting Humanly:</strong> Siri and Alexa understand natural speech and respond conversationally<br>\r\n    • <strong>Acting Rationally:</strong> Google Maps calculates optimal routes considering traffic, distance, and time<br>\r\n    • <strong>Thinking Rationally:</strong> Expert systems in medical diagnosis use logical rules<br>\r\n    • <strong>Thinking Humanly:</strong> ChatGPT mimics human conversation patterns and reasoning\r\n</div>\r\n\r\n<!-- Section 2: AI Problems & Foundations -->\r\n<div style=\"background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 15px; border-radius: 8px; margin: 20px 0 15px 0; font-size: 1.2em; font-weight: bold;\">\r\n    2. AI Problems & Foundational Disciplines\r\n</div>\r\n\r\n<img src=\"https://www.researchgate.net/publication/391677108/figure/fig2/AS:11431281489674000@1749442799860/Concept-set-diagram-of-artificial-intelligence-machine-learning-neural-networks-and.jpg\" alt=\"AI Concept Diagram\" style=\"width: 100%; max-width: 400px; height: auto; border-radius: 8px; margin: 10px 0; box-shadow: 0 2px 8px rgba(0,0,0,0.1);\">\r\n\r\n<div style=\"background: #f8f9fa; border-left: 4px solid #007bff; padding: 15px; margin: 15px 0; border-radius: 0 8px 8px 0;\">\r\n    <h4 style=\"margin-top: 0;\">Core AI Problem Areas:</h4>\r\n    <ul style=\"font-family: Arial, sans-serif; line-height: 1.6;\">\r\n        <li><strong>Knowledge Representation:</strong> How to store and organize information</li>\r\n        <li><strong>Natural Language Processing (NLP):</strong> Understanding and generating human language</li>\r\n        <li><strong>Planning & Decision Making:</strong> Determining sequences of actions to achieve goals</li>\r\n        <li><strong>Robotics:</strong> Physical embodiment and manipulation of the environment</li>\r\n        <li><strong>Speech Processing:</strong> Converting speech to text and text to speech</li>\r\n        <li><strong>Computer Vision:</strong> Interpreting and understanding visual information</li>\r\n        <li><strong>Machine Learning:</strong> Learning patterns from data and improving performance</li>\r\n    </ul>\r\n</div>\r\n\r\n<div style=\"background: #f8f9fa; border-left: 4px solid #007bff; padding: 15px; margin: 15px 0; border-radius: 0 8px 8px 0;\">\r\n    <h4 style=\"margin-top: 0;\">Foundational Disciplines:</h4>\r\n    <div style=\"background: #d1ecf1; border: 1px solid #bee5eb; padding: 10px; margin: 8px 0; border-radius: 5px; font-family: Arial, sans-serif;\">\r\n        <strong> Philosophy:</strong> Logic, reasoning, ethics, and the nature of knowledge and mind\r\n    </div>\r\n    <div style=\"background: #d1ecf1; border: 1px solid #bee5eb; padding: 10px; margin: 8px 0; border-radius: 5px; font-family: Arial, sans-serif;\">\r\n        <strong> Mathematics:</strong> Probability theory, statistics, optimization, and formal logic\r\n    </div>\r\n    <div style=\"background: #d1ecf1; border: 1px solid #bee5eb; padding: 10px; margin: 8px 0; border-radius: 5px; font-family: Arial, sans-serif;\">\r\n        <strong> Neuroscience:</strong> Understanding brain structure and neural networks\r\n    </div>\r\n    <div style=\"background: #d1ecf1; border: 1px solid #bee5eb; padding: 10px; margin: 8px 0; border-radius: 5px; font-family: Arial, sans-serif;\">\r\n        <strong> Economics:</strong> Game theory, decision theory, and rational choice\r\n    </div>\r\n    <div style=\"background: #d1ecf1; border: 1px solid #bee5eb; padding: 10px; margin: 8px 0; border-radius: 5px; font-family: Arial, sans-serif;\">\r\n        <strong> Psychology:</strong> Human cognition, perception, and behavioral models\r\n    </div>\r\n    <div style=\"background: #d1ecf1; border: 1px solid #bee5eb; padding: 10px; margin: 8px 0; border-radius: 5px; font-family: Arial, sans-serif;\">\r\n        <strong> Engineering:</strong> Hardware design, software engineering, and system implementation\r\n    </div>\r\n</div>\r\n\r\n<!-- Section 3: History of AI -->\r\n<div style=\"background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 15px; border-radius: 8px; margin: 20px 0 15px 0; font-size: 1.2em; font-weight: bold;\">\r\n     3. Evolution of Artificial Intelligence\r\n</div>\r\n\r\n<img src=\"https://cdn.infodiagram.com/c/b52487/ai-timeline.png\" alt=\"AI History Timeline\" style=\"width: 100%; max-width: 400px; height: auto; border-radius: 8px; margin: 10px 0; box-shadow: 0 2px 8px rgba(0,0,0,0.1);\">\r\n\r\n<div style=\"border-left: 3px solid #007bff; padding-left: 15px; margin: 10px 0; position: relative; font-family: Arial, sans-serif; line-height: 1.6;\">\r\n    <div style=\"content: \'\'; width: 10px; height: 10px; background: #007bff; border-radius: 50%; position: absolute; left: -7px; top: 8px;\"></div>\r\n    <strong>1943–1955: Gestation Period</strong><br>\r\n    McCulloch & Pitts create the first mathematical model of neural networks. Alan Turing proposes the Turing Test.\r\n</div>\r\n\r\n<div style=\"border-left: 3px solid #007bff; padding-left: 15px; margin: 10px 0; position: relative; font-family: Arial, sans-serif; line-height: 1.6;\">\r\n    <div style=\"content: \'\'; width: 10px; height: 10px; background: #007bff; border-radius: 50%; position: absolute; left: -7px; top: 8px;\"></div>\r\n    <strong>1956: Birth of AI</strong><br>\r\n    Dartmouth Conference coins the term \"Artificial Intelligence.\" John McCarthy, Marvin Minsky, and others establish AI as a field.\r\n</div>\r\n\r\n<div style=\"border-left: 3px solid #007bff; padding-left: 15px; margin: 10px 0; position: relative; font-family: Arial, sans-serif; line-height: 1.6;\">\r\n    <div style=\"content: \'\'; width: 10px; height: 10px; background: #007bff; border-radius: 50%; position: absolute; left: -7px; top: 8px;\"></div>\r\n    <strong>1960s: Early Optimism</strong><br>\r\n    Success in chess programs, theorem proving, and early language processing. ELIZA chatbot demonstrates conversation.\r\n</div>\r\n\r\n<div style=\"border-left: 3px solid #007bff; padding-left: 15px; margin: 10px 0; position: relative; font-family: Arial, sans-serif; line-height: 1.6;\">\r\n    <div style=\"content: \'\'; width: 10px; health: 10px; background: #007bff; border-radius: 50%; position: absolute; left: -7px; top: 8px;\"></div>\r\n    <strong>1970s: First AI Winter</strong><br>\r\n    Funding cuts due to unrealistic expectations and computational limitations. Focus shifts to more practical applications.\r\n</div>\r\n\r\n<div style=\"border-left: 3px solid #007bff; padding-left: 15px; margin: 10px 0; position: relative; font-family: Arial, sans-serif; line-height: 1.6;\">\r\n    <div style=\"content: \'\'; width: 10px; height: 10px; background: #007bff; border-radius: 50%; position: absolute; left: -7px; top: 8px;\"></div>\r\n    <strong>1980s: Expert Systems Boom</strong><br>\r\n    Knowledge-based systems like MYCIN (medical diagnosis) and XCON (computer configuration) achieve commercial success.\r\n</div>\r\n\r\n<div style=\"border-left: 3px solid #007bff; padding-left: 15px; margin: 10px 0; position: relative; font-family: Arial, sans-serif; line-height: 1.6;\">\r\n    <div style=\"content: \'\'; width: 10px; height: 10px; background: #007bff; border-radius: 50%; position: absolute; left: -7px; top: 8px;\"></div>\r\n    <strong>1990s: Intelligent Agents Era</strong><br>\r\n    Rise of probabilistic models, machine learning, and internet-based applications. IBM\'s Deep Blue defeats world chess champion.\r\n</div>\r\n\r\n<div style=\"border-left: 3px solid #007bff; padding-left: 15px; margin: 10px 0; position: relative; font-family: Arial, sans-serif; line-height: 1.6;\">\r\n    <div style=\"content: \'\'; width: 10px; height: 10px; background: #007bff; border-radius: 50%; position: absolute; left: -7px; top: 8px;\"></div>\r\n    <strong>2000s: Big Data & Robotics</strong><br>\r\n    Google\'s search algorithms, autonomous vehicles research, and practical robotics applications emerge.\r\n</div>\r\n\r\n<div style=\"border-left: 3px solid #007bff; padding-left: 15px; margin: 10px 0; position: relative; font-family: Arial, sans-serif; line-height: 1.6;\">\r\n    <div style=\"content: \'\'; width: 10px; height: 10px; background: #007bff; border-radius: 50%; position: absolute; left: -7px; top: 8px;\"></div>\r\n    <strong>2010s: Deep Learning Revolution</strong><br>\r\n    Breakthrough in neural networks, image recognition, and natural language processing. AlphaGo defeats Go world champion.\r\n</div>\r\n\r\n<div style=\"border-left: 3px solid #007bff; padding-left: 15px; margin: 10px 0; position: relative; font-family: Arial, sans-serif; line-height: 1.6;\">\r\n    <div style=\"content: \'\'; width: 10px; height: 10px; background: #007bff; border-radius: 50%; position: absolute; left: -7px; top: 8px;\"></div>\r\n    <strong>2020s: Generative AI Era</strong><br>\r\n    ChatGPT, DALL·E, and other generative models transform how we interact with AI. Large Language Models (LLMs) emerge.\r\n</div>\r\n\r\n<img src=\"https://qbi.uq.edu.au/files/40697/The-Brain-Intelligent-Machines-AI-timeline.jpg\" alt=\"AI Evolution Timeline\" style=\"width: 100%; max-width: 400px; height: auto; border-radius: 8px; margin: 10px 0; box-shadow: 0 2px 8px rgba(0,0,0,0.1);\">\r\n\r\n<!-- Section 4: Intelligent Agents -->\r\n<div style=\"background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 15px; border-radius: 8px; margin: 20px 0 15px 0; font-size: 1.2em; font-weight: bold;\">\r\n     4. Intelligent Agents Architecture\r\n</div>\r\n\r\n<img src=\"https://media.geeksforgeeks.org/wp-content/uploads/20240423151336/Intelligent-Agent-Structure.webp\" alt=\"Intelligent Agent Structure\" style=\"width: 100%; max-width: 400px; height: auto; border-radius: 8px; margin: 10px 0; box-shadow: 0 2px 8px rgba(0,0,0,0.1);\">\r\n\r\n<p style=\"font-family: Arial, sans-serif; line-height: 1.6;\">An <strong>intelligent agent</strong> is anything that can perceive its environment through sensors and act upon that environment through actuators to achieve its goals.</p>\r\n\r\n<div style=\"background: #f8f9fa; border-left: 4px solid #007bff; padding: 15px; margin: 15px 0; border-radius: 0 8px 8px 0;\">\r\n    <h4 style=\"margin-top: 0;\">Key Components:</h4>\r\n    <div style=\"background: #fff3cd; border: 1px solid #ffeaa7; padding: 10px; margin: 8px 0; border-radius: 5px; font-family: Arial, sans-serif;\">\r\n        <strong> Sensors:</strong> Input devices that allow the agent to perceive its environment (cameras, microphones, keyboards, APIs)\r\n    </div>\r\n    <div style=\"background: #fff3cd; border: 1px solid #ffeaa7; padding: 10px; margin: 8px 0; border-radius: 5px; font-family: Arial, sans-serif;\">\r\n        <strong> Actuators:</strong> Output devices that allow the agent to act upon its environment (motors, speakers, displays, network connections)\r\n    </div>\r\n    <div style=\"background: #fff3cd; border: 1px solid #ffeaa7; padding: 10px; margin: 8px 0; border-radius: 5px; font-family: Arial, sans-serif;\">\r\n        <strong> Agent Function:</strong> Mathematical mapping from percept history to actions (f: P* → A)\r\n    </div>\r\n    <div style=\"background: #fff3cd; border: 1px solid #ffeaa7; padding: 10px; margin: 8px 0; border-radius: 5px; font-family: Arial, sans-serif;\">\r\n        <strong> Agent Program:</strong> Concrete implementation of the agent function in code\r\n    </div>\r\n</div>\r\n\r\n<div style=\"background: #f8f9fa; border-left: 4px solid #007bff; padding: 15px; margin: 15px 0; border-radius: 0 8px 8px 0;\">\r\n    <h4 style=\"margin-top: 0;\">Agent Properties:</h4>\r\n    <ul style=\"font-family: Arial, sans-serif; line-height: 1.6;\">\r\n        <li><strong>Rationality:</strong> Selecting actions that maximize expected performance based on available information</li>\r\n        <li><strong>Autonomy:</strong> Ability to function and adapt without constant human intervention</li>\r\n        <li><strong>Learning:</strong> Improving performance through experience and feedback</li>\r\n        <li><strong>Reactivity:</strong> Responding appropriately to environmental changes</li>\r\n    </ul>\r\n</div>\r\n\r\n<!-- Section 5: PEAS Framework -->\r\n<div style=\"background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 15px; border-radius: 8px; margin: 20px 0 15px 0; font-size: 1.2em; font-weight: bold;\">\r\n     5. PEAS Framework for Agent Design\r\n</div>\r\n\r\n<img src=\"https://www.scaler.com/topics/images/peas-representation.webp\" alt=\"PEAS Framework Diagram\" style=\"width: 100%; max-width: 400px; height: auto; border-radius: 8px; margin: 10px 0; box-shadow: 0 2px 8px rgba(0,0,0,0.1);\">\r\n\r\n<p style=\"font-family: Arial, sans-serif; line-height: 1.6;\">PEAS provides a systematic way to analyze and design intelligent agents by defining four key aspects:</p>\r\n\r\n<div style=\"background: #d1ecf1; border: 1px solid #bee5eb; padding: 10px; margin: 8px 0; border-radius: 5px; font-family: Arial, sans-serif;\">\r\n    <strong> Performance Measure:</strong><br>\r\n    Criteria for measuring agent success (accuracy, speed, cost-effectiveness, user satisfaction)\r\n    <br><em>Example:</em> For a chess program: win rate, move quality, thinking time\r\n</div>\r\n\r\n<div style=\"background: #d1ecf1; border: 1px solid #bee5eb; padding: 10px; margin: 8px 0; border-radius: 5px; font-family: Arial, sans-serif;\">\r\n    <strong> Environment:</strong><br>\r\n    The external world in which the agent operates (physical space, digital network, game board)\r\n    <br><em>Example:</em> For an autonomous car: roads, traffic, weather conditions, other vehicles\r\n</div>\r\n\r\n<div style=\"background: #d1ecf1; border: 1px solid #bee5eb; padding: 10px; margin: 8px 0; border-radius: 5px; font-family: Arial, sans-serif;\">\r\n    <strong> Actuators:</strong><br>\r\n    Mechanisms through which the agent affects its environment\r\n    <br><em>Example:</em> For a robot: wheels, robotic arms, LED displays, speakers\r\n</div>\r\n\r\n<div style=\"background: #d1ecf1; border: 1px solid #bee5eb; padding: 10px; margin: 8px 0; border-radius: 5px; font-family: Arial, sans-serif;\">\r\n    <strong> Sensors:</strong><br>\r\n    Input devices that provide information about the environment\r\n    <br><em>Example:</em> For a smart home system: temperature sensors, motion detectors, cameras, microphones\r\n</div>\r\n\r\n<img src=\"https://intellipaat.com/blog/wp-content/uploads/2023/12/image2-4.jpg\" alt=\"PEAS Components\" style=\"width: 100%; max-width: 400px; height: auto; border-radius: 8px; margin: 10px 0; box-shadow: 0 2px 8px rgba(0,0,0,0.1);\">\r\n\r\n<div style=\"background: #f8f9fa; border-left: 4px solid #007bff; padding: 15px; margin: 15px 0; border-radius: 0 8px 8px 0;\">\r\n    <h4 style=\"margin-top: 0;\">Environment Types & Characteristics:</h4>\r\n    <ul style=\"font-family: Arial, sans-serif; line-height: 1.6;\">\r\n        <li><strong>Observable:</strong> Fully vs. Partially (Can agent see complete state?)</li>\r\n        <li><strong>Agents:</strong> Single vs. Multi-agent (Competitive or cooperative?)</li>\r\n        <li><strong>Deterministic:</strong> Predictable vs. Stochastic (Same action = same result?)</li>\r\n        <li><strong>Episodes:</strong> Episodic vs. Sequential (Actions affect future?)</li>\r\n        <li><strong>Dynamic:</strong> Static vs. Dynamic (Environment changes while deciding?)</li>\r\n        <li><strong>Discrete:</strong> Limited vs. Continuous (Finite number of states/actions?)</li>\r\n        <li><strong>Known:</strong> Rules known vs. Unknown (Agent knows environment laws?)</li>\r\n    </ul>\r\n</div>\r\n\r\n<!-- Section 6: Types of AI Agents -->\r\n<div style=\"background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 15px; border-radius: 8px; margin: 20px 0 15px 0; font-size: 1.2em; font-weight: bold;\">\r\n     6. Structure and Types of AI Agents\r\n</div>\r\n\r\n<img src=\"https://www.labellerr.com/blog/content/images/2025/02/type-of-ai-agent-1.webp\" alt=\"Types of AI Agents\" style=\"width: 100%; max-width: 400px; height: auto; border-radius: 8px; margin: 10px 0; box-shadow: 0 2px 8px rgba(0,0,0,0.1);\">\r\n\r\n<div style=\"background: #fff3cd; border: 1px solid #ffeaa7; padding: 10px; margin: 8px 0; border-radius: 5px; font-family: Arial, sans-serif;\">\r\n    <strong>1.  Simple Reflex Agents</strong><br>\r\n    React based only on current percept, using condition-action rules (if-then statements).\r\n    <br><em>Example:</em> Thermostat, automatic door sensors, spam filters\r\n    <br><em>Limitation:</em> No memory of past events, can get stuck in loops\r\n</div>\r\n\r\n<div style=\"background: #fff3cd; border: 1px solid #ffeaa7; padding: 10px; margin: 8px 0; border-radius: 5px; font-family: Arial, sans-serif;\">\r\n    <strong>2.  Model-Based Reflex Agents</strong><br>\r\n    Maintain internal state to track world aspects not visible in current percept.\r\n    <br><em>Example:</em> Self-driving cars tracking other vehicles, game AI remembering player actions\r\n    <br><em>Advantage:</em> Can handle partially observable environments\r\n</div>\r\n\r\n<div style=\"background: #fff3cd; border: 1px solid #ffeaa7; padding: 10px; margin: 8px 0; border-radius: 5px; font-family: Arial, sans-serif;\">\r\n    <strong>3.  Goal-Based Agents</strong><br>\r\n    Choose actions that help achieve specified goals, considering future consequences.\r\n    <br><em>Example:</em> GPS navigation systems, automated planning systems, game AI with objectives\r\n    <br><em>Capability:</em> Can plan sequences of actions to reach goals\r\n</div>\r\n\r\n<div style=\"background: #fff3cd; border: 1px solid #ffeaa7; padding: 10px; margin: 8px 0; border-radius: 5px; font-family: Arial, sans-serif;\">\r\n    <strong>4.  Utility-Based Agents</strong><br>\r\n    Optimize performance by choosing actions that maximize utility (happiness/satisfaction measure).\r\n    <br><em>Example:</em> Trading algorithms, resource allocation systems, recommendation engines\r\n    <br><em>Advantage:</em> Can handle conflicting goals and trade-offs\r\n</div>\r\n\r\n<div style=\"background: #fff3cd; border: 1px solid #ffeaa7; padding: 10px; margin: 8px 0; border-radius: 5px; font-family: Arial, sans-serif;\">\r\n    <strong>5.  Learning Agents</strong><br>\r\n    Improve performance through experience using feedback and adaptation mechanisms.\r\n    <br><em>Example:</em> Machine learning systems, adaptive game difficulty, personalized recommendations\r\n    <br><em>Components:</em> Learning element, performance element, critic, problem generator\r\n</div>\r\n\r\n<img src=\"https://media.geeksforgeeks.org/wp-content/uploads/20250813100413696556/model-based-reflex-agent.webp\" alt=\"Model-Based Reflex Agent\" style=\"width: 100%; max-width: 400px; height: auto; border-radius: 8px; margin: 10px 0; box-shadow: 0 2px 8px rgba(0,0,0,0.1);\">\r\n\r\n<!-- Section 7: Advanced AI Concepts -->\r\n<div style=\"background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 15px; border-radius: 8px; margin: 20px 0 15px 0; font-size: 1.2em; font-weight: bold;\">\r\n     7. Advanced AI Concepts & Applications\r\n</div>\r\n\r\n<div style=\"background: #f8f9fa; border-left: 4px solid #007bff; padding: 15px; margin: 15px 0; border-radius: 0 8px 8px 0;\">\r\n    <h4 style=\"margin-top: 0;\">Machine Learning Paradigms:</h4>\r\n    <ul style=\"font-family: Arial, sans-serif; line-height: 1.6;\">\r\n        <li><strong>Supervised Learning:</strong> Learning from labeled examples (classification, regression)</li>\r\n        <li><strong>Unsupervised Learning:</strong> Finding patterns in unlabeled data (clustering, dimensionality reduction)</li>\r\n        <li><strong>Reinforcement Learning:</strong> Learning through interaction and rewards (game playing, robotics)</li>\r\n        <li><strong>Semi-supervised Learning:</strong> Combining labeled and unlabeled data</li>\r\n        <li><strong>Transfer Learning:</strong> Applying knowledge from one domain to another</li>\r\n    </ul>\r\n</div>\r\n\r\n<div style=\"background: #f8f9fa; border-left: 4px solid #007bff; padding: 15px; margin: 15px 0; border-radius: 0 8px 8px 0;\">\r\n    <h4 style=\"margin-top: 0;\">Neural Network Types:</h4>\r\n    <ul style=\"font-family: Arial, sans-serif; line-height: 1.6;\">\r\n        <li><strong>Feedforward Networks:</strong> Information flows in one direction</li>\r\n        <li><strong>Convolutional Neural Networks (CNNs):</strong> Specialized for image processing</li>\r\n        <li><strong>Recurrent Neural Networks (RNNs):</strong> Handle sequential data</li>\r\n        <li><strong>Transformer Networks:</strong> Attention-based models for language tasks</li>\r\n        <li><strong>Generative Adversarial Networks (GANs):</strong> Generate new data samples</li>\r\n    </ul>\r\n</div>\r\n\r\n<!-- Section 8: Current AI Applications -->\r\n<div style=\"background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 15px; border-radius: 8px; margin: 20px 0 15px 0; font-size: 1.2em; font-weight: bold;\">\r\n     8. Real-World AI Applications\r\n</div>\r\n\r\n<div style=\"background: #e8f5e8; border: 1px solid #28a745; padding: 12px; border-radius: 6px; margin: 10px 0; font-style: italic; font-family: Arial, sans-serif;\">\r\n    <strong> Healthcare:</strong> Medical imaging, drug discovery, personalized treatment, surgical robots<br>\r\n    <strong> Transportation:</strong> Autonomous vehicles, traffic optimization, predictive maintenance<br>\r\n    <strong> Finance:</strong> Fraud detection, algorithmic trading, credit scoring, robo-advisors<br>\r\n    <strong> E-commerce:</strong> Recommendation systems, chatbots, inventory management, price optimization<br>\r\n    <strong> Manufacturing:</strong> Quality control, predictive maintenance, supply chain optimization<br>\r\n    <strong> Entertainment:</strong> Game AI, content recommendation, virtual assistants, content generation<br>\r\n    <strong> Security:</strong> Cybersecurity, biometric authentication, surveillance systems<br>\r\n    <strong> Agriculture:</strong> Precision farming, crop monitoring, yield prediction, pest control\r\n</div>\r\n\r\n<!-- Section 9: Ethical Considerations -->\r\n<div style=\"background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 15px; border-radius: 8px; margin: 20px 0 15px 0; font-size: 1.2em; font-weight: bold;\">\r\n     9. AI Ethics & Future Challenges\r\n</div>\r\n\r\n<div style=\"background: #f8f9fa; border-left: 4px solid #007bff; padding: 15px; margin: 15px 0; border-radius: 0 8px 8px 0;\">\r\n    <h4 style=\"margin-top: 0;\">Key Ethical Issues:</h4>\r\n    <ul style=\"font-family: Arial, sans-serif; line-height: 1.6;\">\r\n        <li><strong>Bias & Fairness:</strong> Ensuring AI systems don\'t discriminate</li>\r\n        <li><strong>Privacy:</strong> Protecting personal data and maintaining user privacy</li>\r\n        <li><strong>Transparency:</strong> Making AI decisions explainable and accountable</li>\r\n        <li><strong>Job Displacement:</strong> Managing economic impact of automation</li>\r\n        <li><strong>Safety & Security:</strong> Preventing misuse and ensuring robust systems</li>\r\n        <li><strong>Human Agency:</strong> Maintaining human control and decision-making authority</li>\r\n    </ul>\r\n</div>\r\n\r\n<div style=\"background: #f8f9fa; border-left: 4px solid #007bff; padding: 15px; margin: 15px 0; border-radius: 0 8px 8px 0;\">\r\n    <h4 style=\"margin-top: 0;\">Future Directions:</h4>\r\n    <ul style=\"font-family: Arial, sans-serif; line-height: 1.6;\">\r\n        <li><strong>Artificial General Intelligence (AGI):</strong> Human-level intelligence across all domains</li>\r\n        <li><strong>Quantum AI:</strong> Leveraging quantum computing for AI algorithms</li>\r\n        <li><strong>Neuromorphic Computing:</strong> Brain-inspired hardware architectures</li>\r\n        <li><strong>Explainable AI:</strong> Making AI decisions more interpretable</li>\r\n        <li><strong>Edge AI:</strong> Running AI models on local devices</li>\r\n        <li><strong>Multimodal AI:</strong> Systems that process multiple types of data simultaneously</li>\r\n    </ul>\r\n</div>\r\n\r\n<!-- Conclusion -->\r\n<div style=\"background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 15px; border-radius: 8px; margin: 20px 0 15px 0; font-size: 1.2em; font-weight: bold;\">\r\n     Summary & Key Takeaways\r\n</div>\r\n\r\n<div style=\"background: #f8f9fa; border-left: 4px solid #007bff; padding: 15px; margin: 15px 0; border-radius: 0 8px 8px 0;\">\r\n    <p style=\"font-family: Arial, sans-serif; line-height: 1.6;\"><strong>Artificial Intelligence</strong> has evolved from theoretical concepts to practical applications that impact our daily lives. Understanding AI requires grasping:</p>\r\n    <ul style=\"font-family: Arial, sans-serif; line-height: 1.6;\">\r\n        <li>The different approaches to creating intelligent systems</li>\r\n        <li>How agents perceive and act in their environments</li>\r\n        <li>The systematic design process using frameworks like PEAS</li>\r\n        <li>Various agent architectures and their capabilities</li>\r\n        <li>The importance of ethical considerations in AI development</li>\r\n    </ul>\r\n    <p style=\"font-family: Arial, sans-serif; line-height: 1.6;\">As AI continues to advance, the principles covered in this guide will remain fundamental to understanding and developing intelligent systems.</p>\r\n</div>\r\n', 'hard');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('13', 'CSA13', 'I. INTRODUCTION', '<body>     <div style=\"font-family: sans-serif; line-height: 1.6; margin: 0; padding: 10px; color: #333; background-color: #f4f4f4;\">         <div style=\"background: #fff; padding: 15px; margin-bottom: 15px; border-radius: 8px; box-shadow: 0 2px 5px rgba(0,0,0,0.1);\">             <h1 style=\"color: #2c3e50; border-bottom: 2px solid #2c3e50; padding-bottom: 10px;\">Introduction to Theory of Computation</h1>             <div style=\"font-size: 0.9em; color: #777; margin-bottom: 15px;\">Last Updated : 25 Aug, 2025</div>             <p>                 Automata theory, also known as the Theory of Computation, is a field within computer science and mathematics that focuses on studying abstract machines to understand the capabilities and limitations of computation by analyzing mathematical models of how machines can perform calculations.             </p>         </div>          <div style=\"background: #fff; padding: 15px; margin-bottom: 15px; border-radius: 8px; box-shadow: 0 2px 5px rgba(0,0,0,0.1);\">             <h2 style=\"color: #2c3e50;\">Basic Terminologies</h2>                          <h3 style=\"color: #2c3e50;\">1. Symbol</h3>             <p>A symbol (often also called a <b style=\"color: #e74c3c;\">character</b>) is the smallest building block, which can be any alphabet, letter, or picture.</p>             <img src=\"https://media.geeksforgeeks.org/wp-content/uploads/strng.png\" alt=\"Diagram illustrating a string of symbols\" style=\"max-width: 100%; height: auto; display: block; margin: 10px 0; border-radius: 5px;\">                          <h3 style=\"color: #2c3e50;\">2. Alphabets (Σ)</h3>             <p>A finite, non-empty set of symbols used to construct strings and languages. For example, Σ = {a, b}.</p>             <img src=\"https://media.geeksforgeeks.org/wp-content/uploads/alpha1.png\" alt=\"Diagram illustrating an alphabet set\" style=\"max-width: 100%; height: auto; display: block; margin: 10px 0; border-radius: 5px;\">                          <h3 style=\"color: #2c3e50;\">3. String</h3>             <p>                 A string is a <i><b><b style=\"color: #e74c3c;\">finite</b></b></i> sequence of symbols from some alphabet. A string is generally denoted as <i><b><b style=\"color: #e74c3c;\">w</b></b></i> and the length of a string is denoted as <i><b><b style=\"color: #e74c3c;\">|w|</b></b></i>. Empty string is the string with zero occurrence of symbols, represented as ε.             </p>             <blockquote style=\"background: #ecf0f1; border-left: 5px solid #3498db; margin: 10px 0; padding: 10px 15px;\">                 <b>Number of Strings (of length 2) that can be generated over the alphabet {a, b}:</b><br>                 - -<br>                 a a<br>                 a b<br>                 b a<br>                 b b<br><br>                 Length of String |w| = 2<br>                 Number of Strings = 4<br><br>                 <b>Conclusion:</b><br>                 For alphabet {a, b} with length <b>n</b>, number of strings can be generated = <b>2<sup>n</sup></b>.             </blockquote>         </div>          <div style=\"background: #fff; padding: 15px; margin-bottom: 15px; border-radius: 8px; box-shadow: 0 2px 5px rgba(0,0,0,0.1);\">             <h2 style=\"color: #2c3e50;\">Closure Representation in TOC</h2>                          <p><b>1. L<sup>+</sup></b>: It is a <i><b><b style=\"color: #e74c3c;\">Positive Closure</b></b></i> that represents a set of all strings except Null or ε-strings.</p>             <p><b>2. L<sup>*</sup></b>: It is \"<b>Kleene Closure</b>\", that represents the occurrence of certain alphabets for given language alphabets from zero to the infinite number of times. In which ε-string is also included.</p>             <blockquote style=\"background: #ecf0f1; border-left: 5px solid #3498db; margin: 10px 0; padding: 10px 15px;\">                 <b>L* = εL<sup>+</sup></b>             </blockquote>             <p><b>Example:</b></p>             <blockquote style=\"background: #ecf0f1; border-left: 5px solid #3498db; margin: 10px 0; padding: 10px 15px;\">                 <b>(a) Regular expression for language accepting all combination of g\'s over Σ={g}:</b><br>                 <b>R = g<sup>*</sup></b><br>                 R={ε,g,gg,ggg,gggg,ggggg,...}<br><br>                 <b>(b) Regular Expression for language accepting all combination of g\'s over Σ={g} :</b><br>                 <b>R = g<sup>+</sup></b><br>                 R={g,gg,ggg,gggg,ggggg,gggggg,...}             </blockquote>             <p style=\"font-style: italic; color: #555; margin-top: 10px;\"><b>Note:</b> Σ* is a set of all possible strings. So this implies that <i><b>language</b></i> <i>is a subset of</i> Σ*. This is also called a <i><b>\"Kleene Star\"</b></i>. Kleene Star is also called a <i><b>\"Kleene Operator\"</b></i> or <i><b>\"Kleene Closure\"</b></i>.</p>         </div>          <div style=\"background: #fff; padding: 15px; margin-bottom: 15px; border-radius: 8px; box-shadow: 0 2px 5px rgba(0,0,0,0.1);\">             <h2 style=\"color: #2c3e50;\">Language</h2>             <ul>                 <li style=\"margin-bottom: 5px;\">A <b>language</b> is a set of strings formed using the symbols of a given alphabet Σ.</li>                 <li style=\"margin-bottom: 5px;\">Formally, a language is a subset of Σ*, where Σ* is the set of all possible strings (including ε) over the alphabet Σ.</li>             </ul>             <p><b>Examples of Languages:</b></p>             <blockquote style=\"background: #ecf0f1; border-left: 5px solid #3498db; margin: 10px 0; padding: 10px 15px;\">                 Finite Language:<br>                 L1 = { set of string of 2 }<br>                 L1 = { xy, yx, xx, yy }<br><br>                 Infinite Language:<br>                 L1 = { set of all strings starts with \'b\' }<br>                 L1 = { babb, baa, ba, bbb, baab, ....... }             </blockquote>                          <h3 style=\"color: #2c3e50;\">Types of Languages in TOC</h3>             <p>Languages are classified based on the computational model or grammar generating them:</p>             <ol style=\"padding-left: 20px;\">                 <li style=\"margin-bottom: 5px;\"><b>Regular Languages:</b> Defined using regular expressions or finite automata. Example: L=a<sup>n</sup>∣n≥0.</li>                 <li style=\"margin-bottom: 5px;\"><b>Context-Free Languages:</b> Defined using context-free grammars or pushdown automata. Example: L=a<sup>n</sup>b<sup>n</sup>∣n≥0.</li>                 <li style=\"margin-bottom: 5px;\"><b>Context-Sensitive Languages:</b> Defined using context-sensitive grammars or linear-bounded automata.</li>                 <li style=\"margin-bottom: 5px;\"><b>Recursive and Recursively Enumerable Languages:</b> Defined using Turing machines.</li>             </ol>         </div>          <div style=\"background: #fff; padding: 15px; margin-bottom: 15px; border-radius: 8px; box-shadow: 0 2px 5px rgba(0,0,0,0.1);\">             <h2 style=\"color: #2c3e50;\">Core Areas of the Theory of Computation</h2>             <p>The field of computation theory can be broadly divided into three major areas:</p>                          <h3 style=\"color: #2c3e50;\">1. Automata Theory</h3>             <p>Automata theory studies abstract computational models and their applications. It forms the basis for understanding how machines process inputs and produce outputs. Key components include:</p>             <ul>                 <li style=\"margin-bottom: 5px;\"><b>Finite Automata</b>: Used to model simple systems like lexical analyzers in compilers.</li>                 <li style=\"margin-bottom: 5px;\"><b>Pushdown Automata</b>: A more powerful model capable of recognizing context-free languages, essential for parsing programming languages.</li>                 <li style=\"margin-bottom: 5px;\"><b>Turing Machines</b>: The most powerful automata, used as a standard for defining what is computable.</li>             </ul>                          <h3 style=\"color: #2c3e50;\">2. Formal Languages and Grammars</h3>             <p>This area examines the syntax and structure of languages used in computation. It involves:</p>             <ul>                 <li style=\"margin-bottom: 5px;\"><b>Regular Languages</b>: Described by regular expressions and finite automata, representing simple patterns.</li>                 <li style=\"margin-bottom: 5px;\"><b>Context-Free Languages</b>: Defined by context-free grammars, crucial for designing compilers.</li>                 <li style=\"margin-bottom: 5px;\"><b>Chomsky Hierarchy</b>: A classification of languages into regular, context-free, context-sensitive, and recursively enumerable languages.</li>             </ul>                          <h3 style=\"color: #2c3e50;\">3. Computability and Decidability</h3>             <p>Computability theory addresses the question: What problems can a computer solve? It studies concepts like:</p>             <ul>                 <li style=\"margin-bottom: 5px;\"><b>Decidable Problems</b>: Problems with an algorithmic solution.</li>                 <li style=\"margin-bottom: 5px;\"><b>Undecidable Problems</b>: Problems, such as the Halting Problem, for which no algorithm can determine a solution for all inputs.</li>             </ul>                          <h3 style=\"color: #2c3e50;\">4. Complexity Theory</h3>             <p>Complexity theory focuses on the efficiency of algorithms by analyzing the time and space resources they require. It categorizes problems into classes such as:</p>             <ul>                 <li style=\"margin-bottom: 5px;\"><b>P (Polynomial Time)</b>: Problems solvable in polynomial time.</li>                 <li style=\"margin-bottom: 5px;\"><b>NP (Nondeterministic Polynomial Time)</b>: Problems whose solutions can be verified in polynomial time.</li>                 <li style=\"margin-bottom: 5px;\"><b>NP-Complete and NP-Hard</b>: The most challenging problems in NP, with applications in cryptography, optimization, and artificial intelligence.</li>             </ul>         </div>     </div> </body>', 'easy');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('14', 'CSA17', 'II. SEARCHING TECHNIQUES', '<body>\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n    <style>\n        body {\n            font-family: \'Inter\', sans-serif;\n            background-color: #fdfcf9;\n            color: #4a4a4a;\n            line-height: 1.6;\n            margin: 1.5rem;\n        }\n        h1, h2, h3 {\n            color: #2d3748;\n            font-weight: 600;\n        }\n        h1 {\n            font-size: 2.25rem;\n            text-align: center;\n        }\n        h2 {\n            font-size: 1.5rem;\n            margin-top: 2.5rem;\n            margin-bottom: 1rem;\n        }\n        h3 {\n            font-size: 1.25rem;\n            margin-top: 1.5rem;\n            margin-bottom: 0.5rem;\n        }\n        p, ul, ol {\n            font-size: 1rem;\n            margin-bottom: 1rem;\n        }\n        ul, ol {\n            padding-left: 1.5rem;\n        }\n        .section-separator {\n            margin: 2.5rem 0;\n            border-top: 1px solid #e2e8f0;\n        }\n    </style>\n\n    <h1>AI Searching Techniques</h1>\n\n    <h2>Problem-Solving Agents</h2>\n    <p>Problem-solving agents are a type of goal-based agent that finds a sequence of actions to reach a desired end state. A GPS is a perfect example: its goal is your destination, and its problem is finding the best route to get you there. These agents operate in a four-step cycle:</p>\n    <ol>\n        <li><strong>Goal Formulation:</strong> The first step is to precisely define the desired final state.</li>\n        <li><strong>Problem Formulation:</strong> Next, the agent translates the goal into a formal search problem, defining the possible states and actions.</li>\n        <li><strong>Search for a Solution:</strong> The agent explores the state space to find a valid path of actions.</li>\n        <li><strong>Execute the Solution:</strong> Finally, the agent carries out the sequence of actions to reach the goal.</li>\n    </ol>\n    <p>This framework is applied to both simplified \"toy problems\" like the 8-Puzzle and complex \"real-world\" problems such as robot navigation and optimizing the layout of a microchip.</p>\n\n    <div class=\"section-separator\"></div>\n\n    <h2>Searching for a Solution</h2>\n    <p>The core of problem-solving is the search process itself. We can imagine all possible states and the actions that link them as a giant map, called the **state space**. The search algorithm explores this map, building a **search tree** of explored paths, trying to find a route from the initial state to the goal. How well an algorithm performs is measured by four key criteria:</p>\n    <ul>\n        <li><strong>Completeness:</strong> Does the algorithm always find a solution if one exists?</li>\n        <li><strong>Optimality:</strong> Is it guaranteed to find the best, or least-cost, solution?</li>\n        <li><strong>Time Complexity:</strong> How much computation time is required?</li>\n        <li><strong>Space Complexity:</strong> How much memory is needed to store the search tree?</li>\n    </ul>\n    <p>Key terms include: a <strong>State</strong> (a specific configuration of the problem), an <strong>Action</strong> (what moves you from one state to another), and the <strong>Path Cost</strong> $g(n)$, which is the total cost from the initial state to the current node $n$.</p>\n\n    <div class=\"section-separator\"></div>\n\n    <h2>Uninformed (Blind) Search Strategies</h2>\n    <p>These strategies explore the search space systematically without any extra information about the problem. They do not know if one state is better than another. It\'s like navigating a maze without a map. There are three main types:</p>\n\n    <h3>Breadth-First Search (BFS)</h3>\n    <p><strong>Analogy:</strong> Like searching for a person in a building by checking every room on the first floor, then every room on the second, and so on.</p>\n    <p>BFS explores the search tree level by level, expanding the shallowest unexpanded node first. It is **complete** (guaranteed to find a solution if one exists) and **optimal** if all path costs are equal. Its main drawback is its high memory usage, as it stores all nodes at the current depth.</p>\n    <p><strong>Time/Space Complexity:</strong> $O(b^d)$, where $b$ is the branching factor and $d$ is the depth of the solution.</p>\n\n    <h3>Depth-First Search (DFS)</h3>\n    <p><strong>Analogy:</strong> Like navigating a maze by taking a path until you hit a dead end, then backtracking and trying a different path.</p>\n    <p>DFS explores the search tree by expanding the deepest unexpanded node first. It is very memory efficient, only needing to store the current path. However, it is **not complete** (can get stuck in infinite loops) and **not optimal** (may find a non-optimal solution first).</p>\n    <p><strong>Time/Space Complexity:</strong> Time is $O(b^m)$ and space is $O(bm)$, where $m$ is the maximum depth of the search tree.</p>\n\n    <h3>Uniform-Cost Search (UCS)</h3>\n    <p><strong>Analogy:</strong> A delivery driver who always chooses the next closest destination, regardless of the direction from the start.</p>\n    <p>UCS expands the node with the lowest **path cost** $g(n)$ first. This ensures it finds the **least-cost path**, making it **optimal** and **complete**. However, it can be very slow if there is no guidance towards the goal.</p>\n\n    <div class=\"section-separator\"></div>\n\n    <h2>Informed (Heuristic) Search Strategies</h2>\n    <p>These strategies use problem-specific knowledge, or a **heuristic**, to find solutions more efficiently. A **heuristic function**, $h(n)$, estimates the cost from node $n$ to the goal. It\'s like having a compass that points you in the right direction.</p>\n\n    <h3>Greedy Best-First Search</h3>\n    <p><strong>Analogy:</strong> A hiker who always walks in the direction that looks closest to the mountain peak, without considering the terrain.</p>\n    <p>Greedy Best-First Search expands the node that appears to be closest to the goal, as estimated by the heuristic function $h(n)$. It can be very fast, but it is **not complete** and **not optimal**, as a poor heuristic can easily mislead the search.</p>\n\n    <h3>A* Search</h3>\n    <p><strong>Analogy:</strong> A smarter hiker who considers both the distance they\'ve already traveled ($g(n)$) and the estimated distance to the peak ($h(n)$) to choose their next step.</p>\n    <p>A* Search is the most widely used informed search algorithm. It expands the node with the lowest evaluation function value, $f(n) = g(n) + h(n)$. A* is **complete** and **optimal**, provided its heuristic is **admissible** (never overestimates the true cost to the goal).</p>\n\n    <div class=\"section-separator\"></div>\n\n    <h2>Local Search and Optimization</h2>\n    <p>Local search algorithms operate on a single current state and try to improve it. They are very memory-efficient and are great for optimization problems where the final solution is more important than the path to get there.</p>\n\n    <h3>Hill-Climbing</h3>\n    <p><strong>Analogy:</strong> A climber in thick fog who can only see their immediate surroundings and always takes a step in the steepest upward direction.</p>\n    <p>Hill-climbing moves in the direction of increasing value to find a peak. It is fast and uses minimal memory, but it is neither **complete** nor **optimal** because it can easily get stuck at **local maxima**, plateaus, and ridges, failing to find the true global optimum.</p>\n    <p></p>\n\n    <h3>Simulated Annealing</h3>\n    <p><strong>Analogy:</strong> A slightly drunk climber who might stumble downhill occasionally, potentially getting out of a small valley to find a much higher peak.</p>\n    <p>Simulated annealing is an improvement over hill-climbing. It allows for occasional \"bad\" moves (downhill) to escape local optima. The probability of making a bad move decreases over time according to a \"cooling schedule.\" If the cooling is slow enough, this algorithm can be shown to find the global optimum.</p>\n\n    <div class=\"section-separator\"></div>\n\n    <h2>Constraint Satisfaction Problems (CSPs)</h2>\n    <p>CSPs are a special class of search problems where the goal is to find a state that satisfies a set of constraints. The path to the solution is irrelevant. The problem is defined by a set of <strong>variables</strong>, their possible <strong>values</strong> (domains), and the <strong>constraints</strong> that restrict these values.</p>\n    <ul>\n        <li><strong>Map Coloring:</strong> Assign a color to each region on a map such that no two adjacent regions share the same color.</li>\n        <li><strong>4-Queens Problem:</strong> Place 4 queens on a 4x4 chessboard so that none can attack another.</li>\n        <li><strong>Cryptarithmetic:</strong> Assign digits (0-9) to letters to solve an equation like SEND + MORE = MONEY.</li>\n    </ul>\n\n    <div class=\"section-separator\"></div>\n\n    <h2>Adversarial Search (Game Playing)</h2>\n    <p>Adversarial search applies to competitive environments where multiple agents have conflicting goals, such as games like Chess or Go. The key challenge is to make the best move while assuming your opponent will also make their best move to thwart you. The goal is to maximize your own outcome while minimizing your opponent\'s.</p>\n\n    <h3>Minimax Algorithm</h3>\n    <p>This algorithm explores the game tree to find the optimal move. It works by assigning values to terminal states and then recursively propagating those values up the tree. It assumes two players, <strong>MAX</strong> (you) and <strong>MIN</strong> (opponent). MAX always chooses the move that leads to the highest possible score, while MIN chooses the move that leads to the lowest score. This allows you to find the best move you can make assuming your opponent plays perfectly.</p>\n    <p></p>\n\n    <h3>Alpha-Beta Pruning</h3>\n    <p>A powerful optimization for Minimax. It avoids exploring branches of the game tree that won\'t influence the final decision. By keeping track of the best scores found so far for MAX (alpha) and MIN (beta), it can \"prune\" (cut off) subtrees that are guaranteed to be worse than a move already found, significantly speeding up the search process.</p>\n    <p></p>\n</body>\n', 'hard');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('15', 'CSA17', 'III. KNOWLEDGE AND REASONING', '<body>\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\r\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\r\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\r\n    <style>\r\n        body {\r\n            font-family: \'Inter\', sans-serif;\r\n            background-color: #fdfcf9;\r\n            color: #4a4a4a;\r\n            line-height: 1.6;\r\n            margin: 1.5rem;\r\n        }\r\n        h1, h2, h3 {\r\n            color: #2d3748;\r\n            font-weight: 600;\r\n        }\r\n        h1 {\r\n            font-size: 2.25rem;\r\n            text-align: center;\r\n        }\r\n        h2 {\r\n            font-size: 1.5rem;\r\n            margin-top: 2.5rem;\r\n            margin-bottom: 1rem;\r\n        }\r\n        h3 {\r\n            font-size: 1.25rem;\r\n            margin-top: 1.5rem;\r\n            margin-bottom: 0.5rem;\r\n        }\r\n        p, ul, ol {\r\n            font-size: 1rem;\r\n            margin-bottom: 1rem;\r\n        }\r\n        ul, ol {\r\n            padding-left: 1.5rem;\r\n        }\r\n        .section-separator {\r\n            margin: 2.5rem 0;\r\n            border-top: 1px solid #e2e8f0;\r\n        }\r\n    </style>\r\n\r\n    <h1>Logical Agents</h1>\r\n    <p>A Comprehensive Study Guide</p>\r\n\r\n    <h2>1. The World of Logical Agents</h2>\r\n    <p>A logical agent is a knowledge-based agent that uses explicit knowledge about its world to make rational decisions. Unlike simple agents that act based on predefined rules or reactions, a logical agent can reason and infer new knowledge from its existing knowledge base. Its fundamental purpose is to derive conclusions that are guaranteed to be true, given its initial premises.</p>\r\n    <p>Think of a detective. A detective doesn\'t just react to clues; they use a body of knowledge about crime, human behavior, and the current case to logically deduce who the culprit is. A logical agent operates on this same principle, using logic to figure out the best course of action. They are particularly useful in environments that are partially observable, discrete, and deterministic.</p>\r\n\r\n    <div class=\"section-separator\"></div>\r\n\r\n    <h2>2. Key Components of a Logical Agent</h2>\r\n    <p>Logical agents are composed of two core components that enable their reasoning capabilities:</p>\r\n    <ul>\r\n        <li><strong>Knowledge Base (KB):</strong> This is a collection of sentences, expressed in a formal language, that represent the agent\'s beliefs about the world. Each sentence in the KB is a statement that the agent believes to be true. The process of adding a new sentence to the KB is called <strong>telling</strong> the agent.</li>\r\n        <li><strong>Inference Engine:</strong> This is a reasoning system that derives new sentences from the existing ones in the KB. The process of using the inference engine to determine if a new sentence is entailed by the KB is called <strong>asking</strong> the agent. The inference engine\'s role is to ensure that any conclusions it draws logically follow from the knowledge it has.</li>\r\n    </ul>\r\n\r\n    <div class=\"section-separator\"></div>\r\n\r\n    <h2>3. The Knowledge Representation Process</h2>\r\n    <p>Building a logical agent involves a structured process to ensure its knowledge is sound and its reasoning is valid. This process can be broken down into three main steps:</p>\r\n    <ol>\r\n        <li>\r\n            <h3>Representation</h3>\r\n            <p>This involves translating information about the real world into a formal language that the agent can understand and manipulate. This formal language is often based on <strong>Propositional Logic</strong> or <strong>First-Order Logic</strong>. For example, the statement \"It is raining\" could be represented as a symbol `Raining`. This step is crucial because it gives the agent a precise and unambiguous way to store information.</p>\r\n        </li>\r\n        <li>\r\n            <h3>Reasoning</h3>\r\n            <p>This is the central part of a logical agent\'s operation, performed by the inference engine. Reasoning is the process of using logical rules to infer new facts from the KB. A key concept here is <strong>Entailment</strong>, which means that a sentence is a logical consequence of the KB. If the KB entails a sentence, it means that the sentence must be true in all possible worlds where the KB is true.</p>\r\n        </li>\r\n        <li>\r\n            <h3>Action</h3>\r\n            <p>Once the inference engine has derived a conclusion, the agent must decide how to act based on that new knowledge. For a logical agent, the action is often a direct result of a reasoned conclusion. For instance, if the agent infers \"It is raining,\" its action might be \"Take an umbrella.\"</p>\r\n        </li>\r\n    </ol>\r\n\r\n    <div class=\"section-separator\"></div>\r\n\r\n    <h2>4. Formal Languages for Logic</h2>\r\n    <p>To perform reasoning, a logical agent needs a formal language. The two most common are:</p>\r\n    <h3>Propositional Logic</h3>\r\n    <p>In propositional logic, the world is described as a collection of facts. Each fact is a simple **proposition** that is either true or false. These propositions are combined using logical connectives like AND ($\\land$), OR ($\\lor$), NOT ($\\neg$), and IMPLIES ($\\implies$). This logic is simple and can be used for many problems, but it has a major limitation: it can\'t handle objects or relationships. It can say \"It is raining,\" but it cannot say \"It is raining in Chennai.\"</p>\r\n\r\n    <h3>First-Order Logic (FOL)</h3>\r\n    <p>To overcome the limitations of propositional logic, First-Order Logic introduces **objects** and **relations**. It allows us to express more complex sentences about the world. FOL includes:</p>\r\n    <ul>\r\n        <li><strong>Constants:</strong> Symbols for objects (e.g., `Chennai`, `Pramod`).</li>\r\n        <li><strong>Predicates:</strong> Symbols for relations (e.g., `Raining(Chennai)`).</li>\r\n        <li><strong>Functions:</strong> A way to refer to an object using another (e.g., `FatherOf(Pramod)`).</li>\r\n        <li><strong>Quantifiers:</strong> Symbols to express properties of collections of objects.\r\n            <ul>\r\n                <li><strong>Universal Quantifier ($\\forall$):</strong> \"For all objects...\" (e.g., $\\forall x \\text{ Raining}(x)$).</li>\r\n                <li><strong>Existential Quantifier ($\\exists$):</strong> \"There exists an object...\" (e.g., $\\exists x \\text{ Raining}(x)$).</li>\r\n            </ul>\r\n        </li>\r\n    </ul>\r\n\r\n    <div class=\"section-separator\"></div>\r\n\r\n    <h2>5. The Wumpus World Example</h2>\r\n    <p>The Wumpus World is a classic example used in AI to illustrate logical agents.  Imagine a cave with a grid of rooms. Some rooms contain a deadly Wumpus, and others contain a bottomless pit. The agent\'s goal is to find a pile of gold and get out without being killed. The agent can\'t see the hazards directly but can sense nearby clues:</p>\r\n    <ul>\r\n        <li>If there\'s a pit in an adjacent room, the agent feels a **breeze**.</li>\r\n        <li>If there\'s a Wumpus in an adjacent room, the agent smells a **stench**.</li>\r\n    </ul>\r\n    <p>Using logical rules, the agent can build its knowledge base as it explores. For example, if the agent enters a room and feels a breeze but no stench, it can logically infer that an adjacent room has a pit, but the Wumpus is elsewhere. The agent can use this derived knowledge to safely navigate the cave and find the gold.</p>\r\n</body>\r\n', 'hard');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('16', 'CSA17', 'IV. LEARNING', '<body>\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\r\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\r\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\r\n    <style>\r\n        body {\r\n            font-family: \'Inter\', sans-serif;\r\n            background-color: #fdfcf9;\r\n            color: #4a4a4a;\r\n            line-height: 1.6;\r\n            margin: 1.5rem;\r\n        }\r\n        h1, h2, h3 {\r\n            color: #2d3748;\r\n            font-weight: 600;\r\n        }\r\n        h1 {\r\n            font-size: 2.25rem;\r\n            text-align: center;\r\n        }\r\n        h2 {\r\n            font-size: 1.5rem;\r\n            margin-top: 2.5rem;\r\n            margin-bottom: 1rem;\r\n        }\r\n        h3 {\r\n            font-size: 1.25rem;\r\n            margin-top: 1.5rem;\r\n            margin-bottom: 0.5rem;\r\n        }\r\n        p, ul, ol {\r\n            font-size: 1rem;\r\n            margin-bottom: 1rem;\r\n        }\r\n        ul, ol {\r\n            padding-left: 1.5rem;\r\n        }\r\n        .section-separator {\r\n            margin: 2.5rem 0;\r\n            border-top: 1px solid #e2e8f0;\r\n        }\r\n    </style>\r\n\r\n    <h1>AI Learning from Observation</h1>\r\n    <p>A Comprehensive Study Guide</p>\r\n\r\n    <h2>1. Learning from Observation</h2>\r\n    <p>The ability to learn is a cornerstone of intelligence. A learning agent is designed to improve its performance by analyzing its own experiences and the feedback it receives. This allows the agent to become more effective over time, adapting to its environment without explicit reprogramming.</p>\r\n    <p>A learning agent can be broken down into four key components that work together to drive improvement:</p>\r\n    <ul>\r\n        <li><strong>Performance Element:</strong> This is the agent\'s core function—it is responsible for selecting and executing actions in the environment. It\'s the part that \"does\" the work.</li>\r\n        <li><strong>Critic:</strong> The critic observes the agent\'s performance and provides valuable feedback, often in the form of a success or failure signal. It essentially tells the agent how well it\'s doing.</li>\r\n        <li><strong>Learning Element:</strong> This is the brain of the operation. It takes the feedback from the critic and uses it to modify the agent\'s internal components, such as its knowledge base or its action selection rules, to improve future performance.</li>\r\n        <li><strong>Problem Generator:</strong> To prevent the agent from getting stuck in a routine, the problem generator suggests new and experimental actions that the agent might not have tried before. This encourages exploration and the discovery of better solutions.</li>\r\n    </ul>\r\n\r\n    <div class=\"section-separator\"></div>\r\n\r\n    <h2>2. Key Types of Learning</h2>\r\n    <p>There are three primary paradigms for machine learning, each suited to different types of problems and data:</p>\r\n    <ul>\r\n        <li>\r\n            <h3>Supervised Learning</h3>\r\n            <p>This is the most common type of learning. The agent is provided with a dataset of **labeled examples**, where each input is paired with its correct output. The goal is to learn a mapping from inputs to outputs so that the agent can make accurate predictions on new, unseen data. It\'s like a student learning with a teacher who provides the correct answers.</p>\r\n            <p><strong>Example:</strong> Training a model to identify spam emails by feeding it a large set of emails already labeled as \"spam\" or \"not spam.\"</p>\r\n        </li>\r\n        <li>\r\n            <h3>Unsupervised Learning</h3>\r\n            <p>In this approach, the agent is given **unlabeled data** and is tasked with finding hidden patterns or structures on its own. It\'s like a curious child sorting a basket of mixed toys without being told what they are—it must discover the categories (e.g., blocks, dolls, cars) for itself. The two main tasks in unsupervised learning are clustering and dimensionality reduction.</p>\r\n            <p><strong>Example:</strong> A program analyzing customer purchasing data to automatically group customers with similar buying habits into different market segments.</p>\r\n        </li>\r\n        <li>\r\n            <h3>Reinforcement Learning (RL)</h3>\r\n            <p>RL is a form of learning where an agent learns through trial and error in an environment. The agent performs actions and receives a **reward** (positive feedback) or a **penalty** (negative feedback). The goal is to learn a **policy**—a strategy that maximizes the total reward over time. The agent must balance **exploration** (trying new actions to discover better rewards) with **exploitation** (using the best strategy found so far).</p>\r\n            <p><strong>Example:</strong> Training a chess-playing AI by rewarding it for winning and penalizing it for losing, allowing it to discover optimal strategies on its own.</p>\r\n        </li>\r\n    </ul>\r\n\r\n    <div class=\"section-separator\"></div>\r\n\r\n    <h2>3. Inductive Learning and Decision Trees</h2>\r\n    <p><strong>Inductive Learning</strong> is the process of generalizing from specific examples to infer a general rule or model. The goal is to create a hypothesis that best explains the observed data. A classic model for this is the **Decision Tree**.</p>\r\n    <p>A Decision Tree is a tree-like model that maps observations about an item to conclusions about its target value. It uses a series of simple questions to make a classification or a prediction. Each internal node represents a test on an attribute, each branch represents an outcome of the test, and each leaf node represents a final decision.</p>\r\n\r\n    <div class=\"section-separator\"></div>\r\n\r\n    <h2>4. Statistical Learning</h2>\r\n    <p>Statistical learning focuses on creating models that are based on probability theory. The core idea is to find a model that is most likely to have generated the observed data.</p>\r\n    <ul>\r\n        <li>\r\n            <h3>Bayes\' Rule</h3>\r\n            <p>At the heart of statistical learning is **Bayes\' Rule**, a fundamental theorem that describes how to update the probability of a hypothesis when new evidence is obtained. It\'s often written as: \r\n\r\n[Image of Bayes\' Rule formula]\r\n.</p>\r\n            <p>This rule is the foundation for Bayesian networks and many other probabilistic models, allowing agents to make rational decisions under uncertainty.</p>\r\n        </li>\r\n        <li>\r\n            <h3>Complete vs. Incomplete Data</h3>\r\n            <p>When all data points are present and labeled, a model can be trained using **Maximum Likelihood Estimation (MLE)**, which finds the parameters that maximize the probability of the observed data. When some data is missing, a more complex method like the **Expectation-Maximization (EM) algorithm** is used to iteratively estimate the missing data and refine the model parameters.</p>\r\n        </li>\r\n    </ul>\r\n\r\n    <div class=\"section-separator\"></div>\r\n\r\n    <h2>5. Neural Networks</h2>\r\n    <p>Inspired by the human brain, Neural Networks are powerful models for learning complex patterns. They are composed of a network of interconnected nodes, or \"neurons,\" organized in layers.</p>\r\n    <ul>\r\n        <li><strong>Structure:</strong> A typical neural network consists of an **input layer** to receive data, one or more **hidden layers** to perform computations, and an **output layer** that produces the final result.</li>\r\n        <li><strong>Activation Functions:</strong> Each neuron processes its input and passes its output through an **activation function** (e.g., ReLU, Sigmoid). These functions introduce non-linearity, allowing the network to learn complex relationships.</li>\r\n        <li><strong>Types of Networks:</strong> From simple **Perceptrons** and multi-layer networks to more advanced **Recurrent Neural Networks (RNNs)** for sequential data and **Convolutional Neural Networks (CNNs)** for images, neural networks are a versatile tool for a wide range of tasks.</li>\r\n    </ul>\r\n\r\n    <div class=\"section-separator\"></div>\r\n\r\n    <h2>6. Kernel Machines (SVMs)</h2>\r\n    <p>Support Vector Machines (SVMs) are a type of kernel machine that are highly effective for classification and regression tasks. Their primary goal is to find the **optimal hyperplane**—a decision boundary that best separates different classes in the data with the largest possible margin.</p>\r\n    <p>The **Kernel Trick** is what makes SVMs so powerful. It allows them to transform data into a higher-dimensional space without explicitly computing the coordinates in that new space. This lets SVMs find a linear decision boundary in the higher dimension, which corresponds to a complex, non-linear boundary in the original dimension.</p>\r\n</body>\r\n', 'hard');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('20', 'CSA13', 'I : Introduction to Theory of Computation', '<body>     <div style=\"font-family: sans-serif; line-height: 1.6; margin: 0; padding: 10px; color: #333; background-color: #f4f4f4;\">         <div style=\"background: #fff; padding: 15px; margin-bottom: 15px; border-radius: 8px; box-shadow: 0 2px 5px rgba(0,0,0,0.1);\">             <h1 style=\"color: #2c3e50; border-bottom: 2px solid #2c3e50; padding-bottom: 10px;\">Introduction to Theory of Computation</h1>             <div style=\"font-size: 0.9em; color: #777; margin-bottom: 15px;\">Last Updated : 25 Aug, 2025</div>             <p>                 Automata theory, also known as the Theory of Computation, is a field within computer science and mathematics that focuses on studying abstract machines to understand the capabilities and limitations of computation by analyzing mathematical models of how machines can perform calculations.             </p>         </div>          <div style=\"background: #fff; padding: 15px; margin-bottom: 15px; border-radius: 8px; box-shadow: 0 2px 5px rgba(0,0,0,0.1);\">             <h2 style=\"color: #2c3e50;\">Basic Terminologies</h2>                          <h3 style=\"color: #2c3e50;\">1. Symbol</h3>             <p>A symbol (often also called a <b style=\"color: #e74c3c;\">character</b>) is the smallest building block, which can be any alphabet, letter, or picture.</p>             <img src=\"https://media.geeksforgeeks.org/wp-content/uploads/strng.png\" alt=\"Diagram illustrating a string of symbols\" style=\"max-width: 100%; height: auto; display: block; margin: 10px 0; border-radius: 5px;\">                          <h3 style=\"color: #2c3e50;\">2. Alphabets (Σ)</h3>             <p>A finite, non-empty set of symbols used to construct strings and languages. For example, Σ = {a, b}.</p>             <img src=\"https://media.geeksforgeeks.org/wp-content/uploads/alpha1.png\" alt=\"Diagram illustrating an alphabet set\" style=\"max-width: 100%; height: auto; display: block; margin: 10px 0; border-radius: 5px;\">                          <h3 style=\"color: #2c3e50;\">3. String</h3>             <p>                 A string is a <i><b><b style=\"color: #e74c3c;\">finite</b></b></i> sequence of symbols from some alphabet. A string is generally denoted as <i><b><b style=\"color: #e74c3c;\">w</b></b></i> and the length of a string is denoted as <i><b><b style=\"color: #e74c3c;\">|w|</b></b></i>. Empty string is the string with zero occurrence of symbols, represented as ε.             </p>             <blockquote style=\"background: #ecf0f1; border-left: 5px solid #3498db; margin: 10px 0; padding: 10px 15px;\">                 <b>Number of Strings (of length 2) that can be generated over the alphabet {a, b}:</b><br>                 - -<br>                 a a<br>                 a b<br>                 b a<br>                 b b<br><br>                 Length of String |w| = 2<br>                 Number of Strings = 4<br><br>                 <b>Conclusion:</b><br>                 For alphabet {a, b} with length <b>n</b>, number of strings can be generated = <b>2<sup>n</sup></b>.             </blockquote>         </div>          <div style=\"background: #fff; padding: 15px; margin-bottom: 15px; border-radius: 8px; box-shadow: 0 2px 5px rgba(0,0,0,0.1);\">             <h2 style=\"color: #2c3e50;\">Closure Representation in TOC</h2>                          <p><b>1. L<sup>+</sup></b>: It is a <i><b><b style=\"color: #e74c3c;\">Positive Closure</b></b></i> that represents a set of all strings except Null or ε-strings.</p>             <p><b>2. L<sup>*</sup></b>: It is \"<b>Kleene Closure</b>\", that represents the occurrence of certain alphabets for given language alphabets from zero to the infinite number of times. In which ε-string is also included.</p>             <blockquote style=\"background: #ecf0f1; border-left: 5px solid #3498db; margin: 10px 0; padding: 10px 15px;\">                 <b>L* = εL<sup>+</sup></b>             </blockquote>             <p><b>Example:</b></p>             <blockquote style=\"background: #ecf0f1; border-left: 5px solid #3498db; margin: 10px 0; padding: 10px 15px;\">                 <b>(a) Regular expression for language accepting all combination of g\'s over Σ={g}:</b><br>                 <b>R = g<sup>*</sup></b><br>                 R={ε,g,gg,ggg,gggg,ggggg,...}<br><br>                 <b>(b) Regular Expression for language accepting all combination of g\'s over Σ={g} :</b><br>                 <b>R = g<sup>+</sup></b><br>                 R={g,gg,ggg,gggg,ggggg,gggggg,...}             </blockquote>             <p style=\"font-style: italic; color: #555; margin-top: 10px;\"><b>Note:</b> Σ* is a set of all possible strings. So this implies that <i><b>language</b></i> <i>is a subset of</i> Σ*. This is also called a <i><b>\"Kleene Star\"</b></i>. Kleene Star is also called a <i><b>\"Kleene Operator\"</b></i> or <i><b>\"Kleene Closure\"</b></i>.</p>         </div>          <div style=\"background: #fff; padding: 15px; margin-bottom: 15px; border-radius: 8px; box-shadow: 0 2px 5px rgba(0,0,0,0.1);\">             <h2 style=\"color: #2c3e50;\">Language</h2>             <ul>                 <li style=\"margin-bottom: 5px;\">A <b>language</b> is a set of strings formed using the symbols of a given alphabet Σ.</li>                 <li style=\"margin-bottom: 5px;\">Formally, a language is a subset of Σ*, where Σ* is the set of all possible strings (including ε) over the alphabet Σ.</li>             </ul>             <p><b>Examples of Languages:</b></p>             <blockquote style=\"background: #ecf0f1; border-left: 5px solid #3498db; margin: 10px 0; padding: 10px 15px;\">                 Finite Language:<br>                 L1 = { set of string of 2 }<br>                 L1 = { xy, yx, xx, yy }<br><br>                 Infinite Language:<br>                 L1 = { set of all strings starts with \'b\' }<br>                 L1 = { babb, baa, ba, bbb, baab, ....... }             </blockquote>                          <h3 style=\"color: #2c3e50;\">Types of Languages in TOC</h3>             <p>Languages are classified based on the computational model or grammar generating them:</p>             <ol style=\"padding-left: 20px;\">                 <li style=\"margin-bottom: 5px;\"><b>Regular Languages:</b> Defined using regular expressions or finite automata. Example: L=a<sup>n</sup>∣n≥0.</li>                 <li style=\"margin-bottom: 5px;\"><b>Context-Free Languages:</b> Defined using context-free grammars or pushdown automata. Example: L=a<sup>n</sup>b<sup>n</sup>∣n≥0.</li>                 <li style=\"margin-bottom: 5px;\"><b>Context-Sensitive Languages:</b> Defined using context-sensitive grammars or linear-bounded automata.</li>                 <li style=\"margin-bottom: 5px;\"><b>Recursive and Recursively Enumerable Languages:</b> Defined using Turing machines.</li>             </ol>         </div>          <div style=\"background: #fff; padding: 15px; margin-bottom: 15px; border-radius: 8px; box-shadow: 0 2px 5px rgba(0,0,0,0.1);\">             <h2 style=\"color: #2c3e50;\">Core Areas of the Theory of Computation</h2>             <p>The field of computation theory can be broadly divided into three major areas:</p>                          <h3 style=\"color: #2c3e50;\">1. Automata Theory</h3>             <p>Automata theory studies abstract computational models and their applications. It forms the basis for understanding how machines process inputs and produce outputs. Key components include:</p>             <ul>                 <li style=\"margin-bottom: 5px;\"><b>Finite Automata</b>: Used to model simple systems like lexical analyzers in compilers.</li>                 <li style=\"margin-bottom: 5px;\"><b>Pushdown Automata</b>: A more powerful model capable of recognizing context-free languages, essential for parsing programming languages.</li>                 <li style=\"margin-bottom: 5px;\"><b>Turing Machines</b>: The most powerful automata, used as a standard for defining what is computable.</li>             </ul>                          <h3 style=\"color: #2c3e50;\">2. Formal Languages and Grammars</h3>             <p>This area examines the syntax and structure of languages used in computation. It involves:</p>             <ul>                 <li style=\"margin-bottom: 5px;\"><b>Regular Languages</b>: Described by regular expressions and finite automata, representing simple patterns.</li>                 <li style=\"margin-bottom: 5px;\"><b>Context-Free Languages</b>: Defined by context-free grammars, crucial for designing compilers.</li>                 <li style=\"margin-bottom: 5px;\"><b>Chomsky Hierarchy</b>: A classification of languages into regular, context-free, context-sensitive, and recursively enumerable languages.</li>             </ul>                          <h3 style=\"color: #2c3e50;\">3. Computability and Decidability</h3>             <p>Computability theory addresses the question: What problems can a computer solve? It studies concepts like:</p>             <ul>                 <li style=\"margin-bottom: 5px;\"><b>Decidable Problems</b>: Problems with an algorithmic solution.</li>                 <li style=\"margin-bottom: 5px;\"><b>Undecidable Problems</b>: Problems, such as the Halting Problem, for which no algorithm can determine a solution for all inputs.</li>             </ul>                          <h3 style=\"color: #2c3e50;\">4. Complexity Theory</h3>             <p>Complexity theory focuses on the efficiency of algorithms by analyzing the time and space resources they require. It categorizes problems into classes such as:</p>             <ul>                 <li style=\"margin-bottom: 5px;\"><b>P (Polynomial Time)</b>: Problems solvable in polynomial time.</li>                 <li style=\"margin-bottom: 5px;\"><b>NP (Nondeterministic Polynomial Time)</b>: Problems whose solutions can be verified in polynomial time.</li>                 <li style=\"margin-bottom: 5px;\"><b>NP-Complete and NP-Hard</b>: The most challenging problems in NP, with applications in cryptography, optimization, and artificial intelligence.</li>             </ul>         </div>     </div> </body>', 'hard');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('21', 'CSA13', 'II : Regular Languages and Grammars', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Unit 2: Regular Languages and Grammars</title>\r\n</head>\r\n<body>\r\n\r\n<h1>Unit 2: Regular Languages and Grammars</h1>\r\n    \r\n<ol>\r\n    <li>\r\n        <h2>Regular Expressions</h2>\r\n        <p>A <strong>regular language</strong> can be formally described using a <strong>Regular Expression (RegEx)</strong>. This provides a concise way to represent patterns of strings that belong to the language. Regular expressions are a fundamental concept in computer science, used for pattern matching and text manipulation. For example, the expression <code>(a|b)*ab</code> describes a language where strings can contain any combination of \'a\'s and \'b\'s, but must end with the substring \'ab\'.</p>\r\n    </li>\r\n    \r\n    <li>\r\n        <h2>Equivalence of Automata</h2>\r\n        <p>A key aspect of this unit is understanding the equivalence of <strong>Deterministic Finite Automata (DFA)</strong> and <strong>Non-Deterministic Finite Automata (NFA)</strong>. While NFAs can have multiple transitions from a single state for the same input symbol, and can even have transitions on an empty string ($\\epsilon$-transitions), we learn that for every NFA, an equivalent DFA can be constructed. This demonstrates that NFAs and DFAs recognize the exact same class of languages—the regular languages.</p>\r\n    </li>\r\n    \r\n    <li>\r\n        <h2>Regular Expressions and NFAs</h2>\r\n        <p>This unit details the methods for converting a <strong>regular expression into an NFA</strong> and, conversely, converting an <strong>NFA back into a regular expression</strong>. This highlights the close interrelation between these descriptive formalisms. The process of converting a RegEx to an NFA is a constructive algorithm, often demonstrated by Thompson\'s Construction, which systematically builds an NFA for any given expression.</p>\r\n    </li>\r\n    \r\n    <li>\r\n        <h2>Pumping Lemma for Regular Sets</h2>\r\n        <p>The <strong>Pumping Lemma for Regular Sets</strong> is a crucial tool used for proving that a language is <strong>not regular</strong>. It works by contradiction. The lemma states that if a language is regular, then any sufficiently long string within that language can be \"pumped.\" This means a specific part of the string can be repeated any number of times (including zero), and the resulting string will still be in the language. If a language fails to satisfy this condition, it cannot be regular. For example, the language <code>aⁿbⁿ</code> (where the number of \'a\'s equals the number of \'b\'s) is not regular, and this can be proven using the Pumping Lemma.</p>\r\n    </li>\r\n    \r\n    <li>\r\n        <h2>Closure Properties</h2>\r\n        <p>The unit outlines the <strong>closure properties</strong> of regular languages. This is a very powerful concept. It means that if you perform certain operations on one or more regular languages, the resulting language will also be regular. These operations include:</p>\r\n        <p><strong>Union:</strong> If $L_1$ and $L_2$ are regular, then $L_1 \\cup L_2$ is also regular.</p>\r\n        <p><strong>Concatenation:</strong> If $L_1$ and $L_2$ are regular, then $L_1 L_2$ is also regular.</p>\r\n        <p><strong>Kleene Star (Closure):</strong> If $L$ is regular, then $L^*$ (zero or more concatenations of strings in L) is also regular.</p>\r\n        <p>These properties are important because they allow us to build new regular languages from existing ones, knowing the new language will also be regular.</p>\r\n    </li>\r\n</ol>\r\n\r\n</body>\r\n</html>\r\n', 'easy');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('22', 'CSA13', 'II : Regular Languages and Grammars', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Unit 2: Regular Languages and Grammars</title>\r\n</head>\r\n<body>\r\n\r\n<h1>Unit 2: Regular Languages and Grammars</h1>\r\n    \r\n<ol>\r\n    <li>\r\n        <h2>Regular Expressions</h2>\r\n        <p>A <strong>regular language</strong> can be formally described using a <strong>Regular Expression (RegEx)</strong>. This provides a concise way to represent patterns of strings that belong to the language. Regular expressions are a fundamental concept in computer science, used for pattern matching and text manipulation. For example, the expression <code>(a|b)*ab</code> describes a language where strings can contain any combination of \'a\'s and \'b\'s, but must end with the substring \'ab\'.</p>\r\n    </li>\r\n    \r\n    <li>\r\n        <h2>Equivalence of Automata</h2>\r\n        <p>A key aspect of this unit is understanding the equivalence of <strong>Deterministic Finite Automata (DFA)</strong> and <strong>Non-Deterministic Finite Automata (NFA)</strong>. While NFAs can have multiple transitions from a single state for the same input symbol, and can even have transitions on an empty string ($\\epsilon$-transitions), we learn that for every NFA, an equivalent DFA can be constructed. This demonstrates that NFAs and DFAs recognize the exact same class of languages—the regular languages.</p>\r\n    </li>\r\n    \r\n    <li>\r\n        <h2>Regular Expressions and NFAs</h2>\r\n        <p>This unit details the methods for converting a <strong>regular expression into an NFA</strong> and, conversely, converting an <strong>NFA back into a regular expression</strong>. This highlights the close interrelation between these descriptive formalisms. The process of converting a RegEx to an NFA is a constructive algorithm, often demonstrated by Thompson\'s Construction, which systematically builds an NFA for any given expression.</p>\r\n    </li>\r\n    \r\n    <li>\r\n        <h2>Pumping Lemma for Regular Sets</h2>\r\n        <p>The <strong>Pumping Lemma for Regular Sets</strong> is a crucial tool used for proving that a language is <strong>not regular</strong>. It works by contradiction. The lemma states that if a language is regular, then any sufficiently long string within that language can be \"pumped.\" This means a specific part of the string can be repeated any number of times (including zero), and the resulting string will still be in the language. If a language fails to satisfy this condition, it cannot be regular. For example, the language <code>aⁿbⁿ</code> (where the number of \'a\'s equals the number of \'b\'s) is not regular, and this can be proven using the Pumping Lemma.</p>\r\n    </li>\r\n    \r\n    <li>\r\n        <h2>Closure Properties</h2>\r\n        <p>The unit outlines the <strong>closure properties</strong> of regular languages. This is a very powerful concept. It means that if you perform certain operations on one or more regular languages, the resulting language will also be regular. These operations include:</p>\r\n        <p><strong>Union:</strong> If $L_1$ and $L_2$ are regular, then $L_1 \\cup L_2$ is also regular.</p>\r\n        <p><strong>Concatenation:</strong> If $L_1$ and $L_2$ are regular, then $L_1 L_2$ is also regular.</p>\r\n        <p><strong>Kleene Star (Closure):</strong> If $L$ is regular, then $L^*$ (zero or more concatenations of strings in L) is also regular.</p>\r\n        <p>These properties are important because they allow us to build new regular languages from existing ones, knowing the new language will also be regular.</p>\r\n    </li>\r\n</ol>\r\n\r\n</body>\r\n</html>\r\n', 'hard');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('23', 'CSA13', 'Unit 3: Grammars and Applications', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Grammars and Applications</title>\r\n    <style>\r\n        body {\r\n            font-family: sans-serif;\r\n            line-height: 1.6;\r\n            padding: 20px;\r\n            color: #333;\r\n        }\r\n        .heading {\r\n            font-size: 2em;\r\n            font-weight: bold;\r\n            color: #1a237e;\r\n            margin-top: 1em;\r\n            margin-bottom: 0.5em;\r\n        }\r\n        .subheading {\r\n            font-size: 1.5em;\r\n            font-weight: bold;\r\n            color: #283593;\r\n            margin-top: 1.5em;\r\n            margin-bottom: 0.5em;\r\n        }\r\n        .section-content {\r\n            margin-bottom: 2em;\r\n        }\r\n        .list-item {\r\n            margin-bottom: 1em;\r\n        }\r\n        .code-block {\r\n            background-color: #f4f4f4;\r\n            padding: 10px;\r\n            border-radius: 5px;\r\n            overflow-x: auto;\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n\r\n<div class=\"heading\">Unit 3: Grammars and Applications</div>\r\n\r\n<p class=\"section-content\">\r\n    This guide provides a comprehensive overview of the key topics in the study of formal grammars, focusing on the Chomsky Hierarchy, Context-Free Grammar (CFG) simplification, normal forms, and the Pumping Lemma for Context-Free Languages.\r\n</p>\r\n\r\n<div class=\"heading\">The Chomsky Hierarchy</div>\r\n<p class=\"section-content\">\r\n    The Chomsky Hierarchy is a system for classifying formal grammars. The hierarchy categorizes grammars into four main types based on the restrictions placed on their production rules. As we move down the hierarchy, the grammars become more restrictive and less powerful in the types of languages they can describe.\r\n</p>\r\n<ul class=\"section-content\">\r\n    <li class=\"list-item\">\r\n        <strong>Type 0 (Unrestricted Grammars):</strong>\r\n        <ul>\r\n            <li><strong>Generates:</strong> Recursively enumerable languages.</li>\r\n            <li><strong>Production Rule Form:</strong> $\\\\alpha \\\\rightarrow \\\\beta$</li>\r\n            <li><strong>Description:</strong> The most powerful type of grammar. There are no restrictions on the production rules, where $\\\\alpha$ and $\\\\beta$ can be any string of terminals and non-terminals, with $\\\\alpha$ being non-empty.</li>\r\n        </ul>\r\n    </li>\r\n    <li class=\"list-item\">\r\n        <strong>Type 1 (Context-Sensitive Grammars):</strong>\r\n        <ul>\r\n            <li><strong>Generates:</strong> Context-sensitive languages.</li>\r\n            <li><strong>Production Rule Form:</strong> $\\\\alpha A \\\\beta \\\\rightarrow \\\\alpha \\\\gamma \\\\beta$</li>\r\n            <li><strong>Description:</strong> The production of a non-terminal $A$ is dependent on its surrounding context $\\\\alpha$ and $\\\\beta$. The length of the right-hand side must be greater than or equal to the length of the left-hand side.</li>\r\n        </ul>\r\n    </li>\r\n    <li class=\"list-item\">\r\n        <strong>Type 2 (Context-Free Grammars):</strong>\r\n        <ul>\r\n            <li><strong>Generates:</strong> Context-free languages.</li>\r\n            <li><strong>Production Rule Form:</strong> $A \\\\rightarrow \\\\alpha$</li>\r\n            <li><strong>Description:</strong> This is the core focus of the unit. The production for a non-terminal $A$ does not depend on its context. $A$ must be a single non-terminal.</li>\r\n        </ul>\r\n    </li>\r\n    <li class=\"list-item\">\r\n        <strong>Type 3 (Regular Grammars):</strong>\r\n        <ul>\r\n            <li><strong>Generates:</strong> Regular languages.</li>\r\n            <li><strong>Production Rule Form:</strong> $A \\\\rightarrow aB$ or $A \\\\rightarrow a$</li>\r\n            <li><strong>Description:</strong> The most restrictive and least powerful grammar type.</li>\r\n        </ul>\r\n    </li>\r\n</ul>\r\n\r\n<div class=\"heading\">CFG Simplification</div>\r\n<p class=\"section-content\">\r\n    The process of simplifying a Context-Free Grammar involves removing productions that are unnecessary while preserving the language generated by the grammar. This is typically done in three sequential steps.\r\n</p>\r\n\r\n<div class=\"subheading\">Step 1: Removing Useless Symbols</div>\r\n<p class=\"section-content\">\r\n    A symbol is useless if it is either non-generating (it cannot derive a string of terminals) or non-reachable (it cannot be reached from the start symbol). The process involves first removing all non-generating symbols and then removing all non-reachable symbols from the remaining grammar.\r\n</p>\r\n<p><strong>Example Grammar:</strong></p>\r\n<pre class=\"code-block\"><code>S → A B | C\r\nA → a | ε\r\nB → b | S\r\nC → d D\r\nD → e | A\r\n</code></pre>\r\n<p class=\"section-content\">\r\n    In this example, $C \\\\rightarrow d D$ is a useless production. If we remove it, $D$ becomes a non-reachable symbol. After removing all useless symbols, the grammar simplifies to:\r\n</p>\r\n<pre class=\"code-block\"><code>S → A B\r\nA → a | ε\r\nB → b | S\r\n</code></pre>\r\n\r\n<div class=\"subheading\">Step 2: Removing $\\\\epsilon$-Productions</div>\r\n<p class=\"section-content\">\r\n    An $\\\\epsilon$-production is a rule of the form $A \\\\rightarrow \\\\epsilon$, where $\\\\epsilon$ is the empty string. To remove such productions, you create new productions by removing the non-terminal that generates the empty string from the right-hand side of other productions.\r\n</p>\r\n<p><strong>Example:</strong>\r\n    Consider the grammar from the previous step:</p>\r\n<pre class=\"code-block\"><code>S → A B\r\nA → a | ε\r\nB → b | S\r\n</code></pre>\r\n<p class=\"section-content\">\r\n    The $\\\\epsilon$-production is $A \\\\rightarrow \\\\epsilon$. We must replace every occurrence of $A$ on the right-hand side with a new production where $A$ is removed. In this case, the only production with $A$ on the right is $S \\\\rightarrow A B$, so we add a new production $S \\\\rightarrow B$. The resulting grammar becomes:\r\n</p>\r\n<pre class=\"code-block\"><code>S → AB | B\r\nA → a\r\nB → b | S\r\n</code></pre>\r\n\r\n<div class=\"subheading\">Step 3: Removing Unit Productions</div>\r\n<p class=\"section-content\">\r\n    A unit production is a rule of the form $A \\\\rightarrow B$, where both $A$ and $B$ are non-terminals. To remove them, you replace the unit production with all the non-unit productions that the second non-terminal can derive.\r\n</p>\r\n<p><strong>Example:</strong>\r\n    Using the grammar from the previous step:</p>\r\n<pre class=\"code-block\"><code>S → AB | B\r\nA → a\r\nB → b | S\r\n</code></pre>\r\n<p class=\"section-content\">\r\n    The production $S \\\\rightarrow B$ is a unit production. We replace it with the productions derived from $B$, which are $B \\\\rightarrow b$ and $B \\\\rightarrow S$. The new production is $S \\\\rightarrow b$. We also replace $S \\\\rightarrow B$ with $S \\\\rightarrow S$, which is a useless unit production and can be removed. The final grammar is:\r\n</p>\r\n<pre class=\"code-block\"><code>S → AB | b\r\nA → a\r\nB → b | AB | B\r\n</code></pre>\r\n\r\n<div class=\"heading\">Normal Forms</div>\r\n<p class=\"section-content\">\r\n    Normal forms are standardized structures for CFGs that are useful for parsing and other theoretical analyses.\r\n</p>\r\n<ul class=\"section-content\">\r\n    <li class=\"list-item\">\r\n        <strong>Chomsky Normal Form (CNF):</strong>\r\n        <ul>\r\n            <li><strong>Production Rules:</strong> Must be of the form $A \\\\rightarrow BC$ or $A \\\\rightarrow a$.</li>\r\n            <li><strong>Conversion Steps:</strong>\r\n                <ol>\r\n                    <li>Remove $\\\\epsilon$-productions and unit productions.</li>\r\n                    <li>Replace any terminals on the right-hand side of a production with a new non-terminal that generates it (e.g., $A \\\\rightarrow aB$ becomes $A \\\\rightarrow X_a B$ and $X_a \\\\rightarrow a$).</li>\r\n                    <li>Break down productions with more than two non-terminals on the right-hand side. For a production like $A \\\\rightarrow B C D$, create new rules like $A \\\\rightarrow B Z_1$ and $Z_1 \\\\rightarrow C D$.</li>\r\n                </ol>\r\n            </li>\r\n        </ul>\r\n    </li>\r\n</ul>\r\n\r\n<div class=\"heading\">The Pumping Lemma for Context-Free Languages</div>\r\n<p class=\"section-content\">\r\n    The Pumping Lemma for Context-Free Languages is a proof technique used to demonstrate that a language is <strong>not</strong> context-free. It states that for any CFL, a \"pumping length\" $p$ exists. Any string $s$ in the language with a length greater than or equal to $p$ can be divided into five parts ($s = uvwxy$) that can be \"pushed\" to create new strings that are also in the language.\r\n</p>\r\n<p>The proof strategy is to use contradiction:</p>\r\n<ol class=\"section-content\">\r\n    <li>Assume the language $L$ is a CFL.</li>\r\n    <li>Choose a long string $s$ in $L$ that is a \"hard case\" (e.g., $s = a^p b^p c^p$).</li>\r\n    <li>Show that no matter how $s$ is divided into five parts, pumping it (e.g., repeating $v$ and $x$) will result in a string that is <strong>not</strong> in $L$.</li>\r\n    <li>Conclude that the initial assumption was false and therefore the language is not a CFL.</li>\r\n</ol>\r\n</body>\r\n</html>\r\n', 'hard');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('25', 'CSA57', 'Unit 1: Introduction to Computers', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Unit 1: Introduction to Computers</title>\r\n</head>\r\n<body>\r\n\r\n    <div>\r\n        <h1>Unit 1: Introduction to Computers</h1>\r\n        \r\n        <div>\r\n            <h2>Overview of Computers</h2>\r\n            <p>\r\n                A computer is an electronic device that processes data according to a set of instructions. It is designed to perform a variety of tasks, serving as a fundamental tool for data processing, communication, and automation.\r\n            </p>\r\n            \r\n            <div>\r\n                <div>\r\n                    <h3>The Evolution of Computing</h3>\r\n                    <p>The history of computing is a journey of mechanical and electronic innovation. Early devices like the <b>Abacus</b>, a manual tool for arithmetic, laid the groundwork for mechanical calculators. The <b>Pascaline</b> and **Leibniz\'s machine** introduced gear-based mechanisms for complex calculations. A major conceptual leap occurred with **Charles Babbage\'s Difference Engine** and **Analytical Engine**, which introduced the foundational concepts of a programmable machine. This was followed by Herman Hollerith\'s use of <b>punch cards</b> to automate data tabulation for the U.S. Census.</p>\r\n                    <p>The dawn of the electronic age brought about the first general-purpose electronic digital computer, the <b>ENIAC</b> (Electronic Numerical Integrator and Computer). Unlike earlier mechanical systems, the ENIAC used vacuum tubes for computation, drastically increasing processing speed and marking the beginning of the computer as we know it today.</p>\r\n                </div>\r\n                <div>\r\n                    <h3>Fundamental Characteristics</h3>\r\n                    <p>The power and reliability of modern computers are defined by several key characteristics:</p>\r\n                    <ul>\r\n                        <li><b>Speed:</b> A computer\'s processing speed is measured by the number of instructions it can execute per unit of time, typically in millions or billions per second (e.g., GHz).</li>\r\n                        <li><b>Data Storage:</b> Computers possess the ability to store vast amounts of data in a structured manner, with capacity measured in bytes (kilobytes, megabytes, gigabytes, terabytes, etc.).</li>\r\n                        <li><b>Accuracy:</b> Computers perform calculations with a very high degree of precision, ensuring consistent and error-free results, provided the input data is correct.</li>\r\n                        <li><b>Reliability:</b> A computer\'s components are designed for high reliability, meaning they are less prone to hardware failure than earlier systems.</li>\r\n                        <li><b>Versatility:</b> A single computer can be programmed to perform a wide variety of tasks, from complex scientific simulations to simple word processing.</li>\r\n                        <li><b>Diligence:</b> A computer can perform repetitive tasks tirelessly and with unwavering accuracy, unlike a human.</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div>\r\n            <h2>Classification of Computers</h2>\r\n            <p>\r\n                Computers are categorized based on their functional architecture, intended applications, and physical size and processing power.\r\n            </p>\r\n            <div>\r\n                <div>\r\n                    <h3>Based on Operating Principles</h3>\r\n                    <ul>\r\n                        <li><b>Analog Computers:</b> These machines operate on continuous physical quantities, such as voltage, pressure, or temperature. They are best suited for tasks involving measurement and real-time process control, like in a flight simulator or a chemical plant.</li>\r\n                        <li><b>Digital Computers:</b> These operate on discrete data represented by binary digits (0s and 1s). This discrete nature provides a higher degree of precision and reliability. The majority of modern computers are digital.</li>\r\n                        <li><b>Hybrid Computers:</b> These systems combine the features of both analog and digital computers. For example, a hospital\'s ICU monitor may use an analog component to measure a patient\'s heartbeat and a digital component to display the numerical data.</li>\r\n                    </ul>\r\n                </div>\r\n                <div>\r\n                    <h3>Based on Applications</h3>\r\n                    <ul>\r\n                        <li><b>General Purpose:</b> These computers are flexible and can be programmed for a wide range of tasks, such as business applications, scientific calculations, and entertainment. Personal computers (PCs) and servers are primary examples.</li>\r\n                        <li><b>Special Purpose:</b> These are designed to perform a specific, single task efficiently. They often have dedicated hardware and are common in embedded systems, such as those controlling a microwave or an aircraft\'s navigation system.</li>\r\n                    </ul>\r\n                </div>\r\n                <div>\r\n                    <h3>Based on Size and Power (Capability)</h3>\r\n                    <ul>\r\n                        <li><b>Microcomputers:</b> Also known as personal computers, these systems are based on a single microprocessor chip. They include desktops, laptops, and smartphones.</li>\r\n                        <li><b>Minicomputers:</b> These are mid-sized, multi-user systems capable of supporting dozens to hundreds of users simultaneously. They were prominent in the 1970s and 1980s for enterprise use.</li>\r\n                        <li><b>Mainframe Computers:</b> Very large and fast computers used for large-scale data processing and complex transaction handling in major corporations and government agencies.</li>\r\n                        <li><b>Supercomputers:</b> The most powerful and fastest computers, designed to perform complex computations at immense speeds. They are used for highly demanding tasks like climate modeling, nuclear research, and molecular biology.</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n</body>\r\n</html>\r\n', 'hard');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('26', 'CSA57', 'Unit 2: Structure and Working of Computers', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Structure and Working of Computers</title>\r\n</head>\r\n<body>\r\n\r\n    <div>\r\n        <h1>Unit 2: Structure and Working of Computers</h1>\r\n        \r\n        <div>\r\n            <h2>Functional Blocks</h2>\r\n            <p>\r\n                The basic organization of a computer includes an Input Unit, a Central Processing Unit (CPU), an Output Unit, and a Memory Unit.\r\n            </p>\r\n            <h3>The Central Processing Unit (CPU)</h3>\r\n            <p>\r\n                The CPU is the processor of the computer. It comprises three main components: the Arithmetic & Logic Unit (ALU), the Control Unit, and Registers.\r\n            </p>\r\n            <ul>\r\n                <li>\r\n                    <b>The ALU:</b> Responsible for performing both arithmetic operations (such as addition, subtraction, multiplication, and division) and logical operations (like AND, OR).\r\n                </li>\r\n                <li>\r\n                    <b>The Control Unit:</b> Interprets the instructions within a program, executes the actions, and then saves the results to memory.\r\n                </li>\r\n                <li>\r\n                    <b>Registers:</b> These are short-term storage areas located within the CPU. Key registers include:\r\n                    <ul>\r\n                        <li><b>The Program Counter:</b> Manages the memory address of the next instruction to be executed.</li>\r\n                        <li><b>The Instruction Register:</b> Holds the instruction currently being executed.</li>\r\n                        <li><b>The Memory Address Register:</b> Handles addresses transferred to the memory unit.</li>\r\n                    </ul>\r\n                </li>\r\n            </ul>\r\n            <p>The CPU, Memory, and Input/Output units are interconnected by a System Bus. This System Bus is composed of the Control Bus, Address Bus, and Data Bus.</p>\r\n        </div>\r\n\r\n        <div>\r\n            <h2>Memory</h2>\r\n            <p>Computer memory is broadly categorized into primary storage and secondary storage.</p>\r\n            \r\n            <h3>Primary Memory (Main Memory)</h3>\r\n            <p>This type of memory is volatile, meaning it is temporary, and while it is fast, it has a low storage capacity.</p>\r\n            <ul>\r\n                <li><b>RAM (Random Access Memory):</b> A form of primary memory that is volatile and temporary. Types of RAM include SRAM and DRAM.</li>\r\n                <li><b>ROM (Read Only Memory):</b> A non-volatile (permanent) memory with a high storage capacity but slower speed compared to RAM. Examples include PROM and EPROM.</li>\r\n            </ul>\r\n\r\n            <h3>Secondary Memory</h3>\r\n            <p>This is non-volatile, permanent storage designed for large volumes of data, such as the Operating System and user programs. Examples of secondary memory include Hard Disks, CD-ROMs, and Solid State Drives (SSDs).</p>\r\n        </div>\r\n\r\n        <div>\r\n            <h2>Input and Output Devices</h2>\r\n\r\n            <h3>Input Devices</h3>\r\n            <p>These devices are used to feed data into the computer:</p>\r\n            <ul>\r\n                <li><b>Keyboard:</b> Used for manual data entry.</li>\r\n                <li><b>Mouse:</b> A hand-held pointing device that controls screen elements.</li>\r\n                <li><b>Scanner:</b> Converts typed text, graphics, and photographs into digital data.</li>\r\n                <li><b>Joystick:</b> An input device for gaming or control systems.</li>\r\n            </ul>\r\n\r\n            <h3>Output Devices</h3>\r\n            <p>These devices display or produce processed information from the computer:</p>\r\n            <ul>\r\n                <li><b>VDU (Visual Display Unit):</b> A display screen that uses a Cathode Ray Tube (CRT) to generate images.</li>\r\n                <li><b>Printers:</b> Produce output on paper.</li>\r\n                <li><b>Plotter:</b> An output device capable of producing high-quality drawings.</li>\r\n            </ul>\r\n        </div>\r\n        \r\n        <div>\r\n            <h2>The Factory Metaphor</h2>\r\n            <p>Think of a computer\'s structure like a factory: the CPU is the control room, directing operations. The ALU is the calculation department, doing all the math and logic. The Control Unit is the manager, ensuring tasks are performed correctly and results are stored. Registers are like small, fast-access desks for immediate tasks. Primary Memory (RAM) is the factory\'s active workspace, holding current projects temporarily, while Secondary Memory (Hard Drive) is the long-term warehouse, storing everything permanently. Input devices are the loading docks where raw materials (data) enter, and Output devices are the shipping docks where finished products (information) leave.</p>\r\n        </div>\r\n\r\n    </div>\r\n\r\n</body>\r\n</html>\r\n', 'easy');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('27', 'CSA57', 'Unit 2: Structure and Working of Computers', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Structure and Working of Computers</title>\r\n</head>\r\n<body>\r\n\r\n    <div>\r\n        <h1>Unit 2: Structure and Working of Computers</h1>\r\n        \r\n        <div>\r\n            <h2>Functional Blocks</h2>\r\n            <p>\r\n                The basic organization of a computer includes an Input Unit, a Central Processing Unit (CPU), an Output Unit, and a Memory Unit.\r\n            </p>\r\n            <h3>The Central Processing Unit (CPU)</h3>\r\n            <p>\r\n                The CPU is the processor of the computer. It comprises three main components: the Arithmetic & Logic Unit (ALU), the Control Unit, and Registers.\r\n            </p>\r\n            <ul>\r\n                <li>\r\n                    <b>The ALU:</b> Responsible for performing both arithmetic operations (such as addition, subtraction, multiplication, and division) and logical operations (like AND, OR).\r\n                </li>\r\n                <li>\r\n                    <b>The Control Unit:</b> Interprets the instructions within a program, executes the actions, and then saves the results to memory.\r\n                </li>\r\n                <li>\r\n                    <b>Registers:</b> These are short-term storage areas located within the CPU. Key registers include:\r\n                    <ul>\r\n                        <li><b>The Program Counter:</b> Manages the memory address of the next instruction to be executed.</li>\r\n                        <li><b>The Instruction Register:</b> Holds the instruction currently being executed.</li>\r\n                        <li><b>The Memory Address Register:</b> Handles addresses transferred to the memory unit.</li>\r\n                    </ul>\r\n                </li>\r\n            </ul>\r\n            <p>The CPU, Memory, and Input/Output units are interconnected by a System Bus. This System Bus is composed of the Control Bus, Address Bus, and Data Bus.</p>\r\n        </div>\r\n\r\n        <div>\r\n            <h2>Memory</h2>\r\n            <p>Computer memory is broadly categorized into primary storage and secondary storage.</p>\r\n            \r\n            <h3>Primary Memory (Main Memory)</h3>\r\n            <p>This type of memory is volatile, meaning it is temporary, and while it is fast, it has a low storage capacity.</p>\r\n            <ul>\r\n                <li><b>RAM (Random Access Memory):</b> A form of primary memory that is volatile and temporary. Types of RAM include SRAM and DRAM.</li>\r\n                <li><b>ROM (Read Only Memory):</b> A non-volatile (permanent) memory with a high storage capacity but slower speed compared to RAM. Examples include PROM and EPROM.</li>\r\n            </ul>\r\n\r\n            <h3>Secondary Memory</h3>\r\n            <p>This is non-volatile, permanent storage designed for large volumes of data, such as the Operating System and user programs. Examples of secondary memory include Hard Disks, CD-ROMs, and Solid State Drives (SSDs).</p>\r\n        </div>\r\n\r\n        <div>\r\n            <h2>Input and Output Devices</h2>\r\n\r\n            <h3>Input Devices</h3>\r\n            <p>These devices are used to feed data into the computer:</p>\r\n            <ul>\r\n                <li><b>Keyboard:</b> Used for manual data entry.</li>\r\n                <li><b>Mouse:</b> A hand-held pointing device that controls screen elements.</li>\r\n                <li><b>Scanner:</b> Converts typed text, graphics, and photographs into digital data.</li>\r\n                <li><b>Joystick:</b> An input device for gaming or control systems.</li>\r\n            </ul>\r\n\r\n            <h3>Output Devices</h3>\r\n            <p>These devices display or produce processed information from the computer:</p>\r\n            <ul>\r\n                <li><b>VDU (Visual Display Unit):</b> A display screen that uses a Cathode Ray Tube (CRT) to generate images.</li>\r\n                <li><b>Printers:</b> Produce output on paper.</li>\r\n                <li><b>Plotter:</b> An output device capable of producing high-quality drawings.</li>\r\n            </ul>\r\n        </div>\r\n        \r\n        <div>\r\n            <h2>The Factory Metaphor</h2>\r\n            <p>Think of a computer\'s structure like a factory: the CPU is the control room, directing operations. The ALU is the calculation department, doing all the math and logic. The Control Unit is the manager, ensuring tasks are performed correctly and results are stored. Registers are like small, fast-access desks for immediate tasks. Primary Memory (RAM) is the factory\'s active workspace, holding current projects temporarily, while Secondary Memory (Hard Drive) is the long-term warehouse, storing everything permanently. Input devices are the loading docks where raw materials (data) enter, and Output devices are the shipping docks where finished products (information) leave.</p>\r\n        </div>\r\n\r\n    </div>\r\n\r\n</body>\r\n</html>\r\n', 'hard');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('28', 'CSA07', 'Unit 1: The Physical Layer a', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Unit 1: The Physical Layer and Media</title>\r\n    <style>\r\n        body {\r\n            font-family: Arial, sans-serif;\r\n            margin: 0;\r\n            padding: 20px;\r\n            background-color: #f4f4f4;\r\n            line-height: 1.6;\r\n        }\r\n        h1 {\r\n            color: #2c3e50;\r\n            text-align: center;\r\n            font-size: 1.8em;\r\n        }\r\n        h2 {\r\n            color: #2980b9;\r\n            font-size: 1.4em;\r\n            margin-top: 20px;\r\n        }\r\n        p, ul {\r\n            font-size: 1em;\r\n            color: #34495e;\r\n        }\r\n        ul {\r\n            padding-left: 20px;\r\n        }\r\n        .section {\r\n            background-color: white;\r\n            padding: 15px;\r\n            margin-bottom: 15px;\r\n            border-radius: 8px;\r\n            box-shadow: 0 2px 5px rgba(0,0,0,0.1);\r\n        }\r\n        @media (max-width: 600px) {\r\n            body {\r\n                padding: 10px;\r\n            }\r\n            h1 {\r\n                font-size: 1.5em;\r\n            }\r\n            h2 {\r\n                font-size: 1.2em;\r\n            }\r\n            p, ul {\r\n                font-size: 0.9em;\r\n            }\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n    <h1>Unit 1: The Physical Layer and Media</h1>\r\n    \r\n    <div class=\"section\">\r\n        <h2>1. The Physical Layer and Data Communication</h2>\r\n        <p>The Physical Layer is the foundation of networking, handling the raw transfer of data bits through mechanical, electrical, and procedural interfaces.</p>\r\n        <ul>\r\n            <li><strong>Key Responsibilities</strong>: Transmits raw bit streams over physical media.</li>\r\n            <li><strong>Data Communication Characteristics</strong>:\r\n                <ul>\r\n                    <li><strong>Delivery</strong>: Ensures data reaches the correct destination.</li>\r\n                    <li><strong>Accuracy</strong>: Guarantees data is unaltered during transmission.</li>\r\n                    <li><strong>Timeliness</strong>: Delivers data within a specified time.</li>\r\n                    <li><strong>Jitter</strong>: Measures variation in packet arrival times.</li>\r\n                </ul>\r\n            </li>\r\n            <li><strong>Components</strong>: Includes sender, receiver, transmission media, and protocols.</li>\r\n        </ul>\r\n    </div>\r\n\r\n    <div class=\"section\">\r\n        <h2>2. Introduction to Networks and Communication Media</h2>\r\n        <p>Networks are classified by scale and purpose, and connections can be point-to-point or multipoint.</p>\r\n        <ul>\r\n            <li><strong>Network Categories</strong>:\r\n                <ul>\r\n                    <li><strong>PAN</strong>: Short-range personal device networks.</li>\r\n                    <li><strong>LAN</strong>: Connects devices in a small area (e.g., office).</li>\r\n                    <li><strong>CAN</strong>: Spans multiple buildings in a campus.</li>\r\n                    <li><strong>MAN</strong>: Covers a city.</li>\r\n                    <li><strong>WAN</strong>: Connects devices over large areas (e.g., countries).</li>\r\n                    <li><strong>SAN</strong>: High-speed network for storage devices.</li>\r\n                </ul>\r\n            </li>\r\n            <li><strong>Connection Types</strong>:\r\n                <ul>\r\n                    <li><strong>Point-to-Point</strong>: Direct link between two devices.</li>\r\n                    <li><strong>Multipoint</strong>: Shared link among multiple devices.</li>\r\n                </ul>\r\n            </li>\r\n        </ul>\r\n    </div>\r\n\r\n    <div class=\"section\">\r\n        <h2>3. Network Hardware, Software, and Standards</h2>\r\n        <p>Networking relies on specialized hardware, software, and standards to ensure compatibility.</p>\r\n        <ul>\r\n            <li><strong>Hardware Components</strong>:\r\n                <ul>\r\n                    <li><strong>NIC</strong>: Connects devices to the network.</li>\r\n                    <li><strong>Bridge</strong>: Links two LANs with the same protocol.</li>\r\n                    <li><strong>Switch</strong>: Connects multiple devices within a LAN.</li>\r\n                    <li><strong>Router</strong>: Forwards packets between networks.</li>\r\n                    <li><strong>Repeater</strong>: Extends network signal range.</li>\r\n                </ul>\r\n            </li>\r\n            <li><strong>Network Software</strong>: Manages communication via APIs (e.g., socket creation).</li>\r\n            <li><strong>Standards</strong>:\r\n                <ul>\r\n                    <li><strong>De-jure</strong>: Officially approved (e.g., ISO, IEEE).</li>\r\n                    <li><strong>De-facto</strong>: Widely used but unofficial.</li>\r\n                </ul>\r\n            </li>\r\n        </ul>\r\n    </div>\r\n\r\n    <div class=\"section\">\r\n        <h2>4. ISO/OSI Reference Model</h2>\r\n        <p>The OSI model standardizes network functions into seven layers, each with specific roles.</p>\r\n        <ul>\r\n            <li><strong>Layers</strong>:\r\n                <ul>\r\n                    <li><strong>Physical Layer</strong>: Manages raw bit streams and physical connections.</li>\r\n                    <li><strong>Data Link Layer</strong>: Handles node-to-node delivery and framing.</li>\r\n                    <li><strong>Network Layer</strong>: Manages routing and logical addressing.</li>\r\n                    <li><strong>Transport Layer</strong>: Ensures reliable process-to-process communication.</li>\r\n                    <li><strong>Session Layer</strong>: Manages sessions and dialog control.</li>\r\n                    <li><strong>Presentation Layer</strong>: Handles data formatting and encryption.</li>\r\n                    <li><strong>Application Layer</strong>: Provides services for applications.</li>\r\n                </ul>\r\n            </li>\r\n            <li><strong>Hardware vs. Software</strong>: Lower layers (1-4) use hardware/firmware; upper layers (5-7) are software-based.</li>\r\n        </ul>\r\n    </div>\r\n\r\n    <div class=\"section\">\r\n        <h2>5. Transmission Media and Network Topologies</h2>\r\n        <p>Transmission media and topologies define how data travels and how devices are interconnected.</p>\r\n        <ul>\r\n            <li><strong>Transmission Media</strong>:\r\n                <ul>\r\n                    <li><strong>Guided Media</strong>: Twisted Pair, Coaxial Cable, Fiber Optics.</li>\r\n                    <li><strong>Unguided Media</strong>: Microwave, Radio Waves, Infrared.</li>\r\n                </ul>\r\n            </li>\r\n            <li><strong>Network Topologies</strong>:\r\n                <ul>\r\n                    <li><strong>Bus</strong>: Single shared cable, prone to collisions.</li>\r\n                    <li><strong>Ring</strong>: Circular connection, uses token passing.</li>\r\n                    <li><strong>Star</strong>: Central hub, easy to troubleshoot but hub-dependent.</li>\r\n                    <li><strong>Mesh</strong>: Fully connected, secure but complex (links = N(N-1)/2).</li>\r\n                    <li><strong>Tree</strong>: Hierarchical structure with central hubs.</li>\r\n                    <li><strong>Hybrid</strong>: Combines multiple topologies.</li>\r\n                </ul>\r\n            </li>\r\n        </ul>\r\n    </div>\r\n</body>\r\n</html>', 'easy');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('29', 'CSA07', 'Unit 1: The Physical Layer a', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Unit 1: The Physical Layer and Media - Hard Mode for Toppers</title>\r\n    <style>\r\n        body {\r\n            font-family: Arial, sans-serif;\r\n            margin: 0;\r\n            padding: 20px;\r\n            background-color: #f4f4f4;\r\n            line-height: 1.6;\r\n        }\r\n        h1 {\r\n            color: #2c3e50;\r\n            text-align: center;\r\n            font-size: 1.8em;\r\n        }\r\n        h2 {\r\n            color: #2980b9;\r\n            font-size: 1.4em;\r\n            margin-top: 20px;\r\n        }\r\n        h3 {\r\n            color: #16a085;\r\n            font-size: 1.2em;\r\n            margin-top: 15px;\r\n        }\r\n        p, ul {\r\n            font-size: 1em;\r\n            color: #34495e;\r\n        }\r\n        ul {\r\n            padding-left: 20px;\r\n        }\r\n        @media (max-width: 600px) {\r\n            body {\r\n                padding: 10px;\r\n            }\r\n            h1 {\r\n                font-size: 1.5em;\r\n            }\r\n            h2 {\r\n                font-size: 1.2em;\r\n            }\r\n            h3 {\r\n                font-size: 1.1em;\r\n            }\r\n            p, ul {\r\n                font-size: 0.9em;\r\n            }\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n    <h1>Unit 1: The Physical Layer and Media </h1>\r\n    <p>This enhanced version provides in-depth explanations, advanced concepts, practical examples, and detailed trade-offs to ensure comprehensive mastery of the Physical Layer and related foundational networking concepts.</p>\r\n    \r\n    <h2>1. The Physical Layer and Data Communication</h2>\r\n    <p>The Physical Layer, the lowest layer of the OSI model, is responsible for the transmission and reception of raw bit streams over a physical medium. It defines electrical, mechanical, procedural, and functional specifications, ensuring reliable bit-level communication.</p>\r\n    <ul>\r\n        <li><strong>Core Responsibilities</strong>: \r\n            <ul>\r\n                <li>Bit transmission and reception, including signal encoding (e.g., Non-Return-to-Zero (NRZ), Manchester, 4B/5B).</li>\r\n                <li>Modulation for analog media (e.g., Amplitude Modulation (AM), Frequency Modulation (FM), Phase Modulation (PM)).</li>\r\n                <li>Timing and synchronization to align sender and receiver clocks.</li>\r\n                <li>Physical connectors (e.g., RJ45, SC/ST for fiber) and pin assignments.</li>\r\n                <li>Transmission power levels and impedance matching to minimize signal loss.</li>\r\n            </ul>\r\n        </li>\r\n        <li><strong>Data Communication Characteristics</strong>:\r\n            <ul>\r\n                <li><strong>Delivery</strong>: Ensures bits reach the intended device, using physical addressing or broadcast mechanisms.</li>\r\n                <li><strong>Accuracy</strong>: Minimizes bit errors through proper signal encoding; bit error rate (BER) is a key metric (e.g., 10^-12 for fiber).</li>\r\n                <li><strong>Timeliness</strong>: Critical for real-time applications (e.g., VoIP, video streaming). Latency includes propagation delay (distance/speed of light in medium) and transmission delay (data size/bandwidth).</li>\r\n                <li><strong>Jitter</strong>: Variation in packet arrival times, calculated as |D(i) - D(i-1)|, where D is delay. Jitter impacts multimedia; mitigated by jitter buffers.</li>\r\n            </ul>\r\n        </li>\r\n        <li><strong>Components of Data Exchange</strong>: \r\n            <ul>\r\n                <li>Sender: Converts data to signals (e.g., electrical voltages, light pulses).</li>\r\n                <li>Receiver: Interprets signals back to data.</li>\r\n                <li>Transmission Medium: Guided (copper, fiber) or unguided (wireless).</li>\r\n                <li>Protocols: Define rules like bit rate, signal levels (e.g., RS-232, USB).</li>\r\n                <li>Message: The raw data unit (bits).</li>\r\n            </ul>\r\n        </li>\r\n    </ul>\r\n    <h3>Advanced Concepts</h3>\r\n    <p><strong>Signal-to-Noise Ratio (SNR)</strong>: SNR = 10 log10(Psignal/Pnoise) dB. High SNR enables higher data rates per Shannon’s Capacity Theorem: C = B log2(1 + SNR), where C is capacity (bps) and B is bandwidth (Hz).</p>\r\n    <p><strong>Practical Example</strong>: In fiber optics, low attenuation (0.2 dB/km for single-mode) and high SNR allow 100 Gbps over 100 km without repeaters, unlike copper’s higher loss (10 dB/100m for Cat5e).</p>\r\n    <p><strong>Trade-offs</strong>: High-speed encoding (e.g., 64B/66B) reduces latency but requires more processing power. Synchronous transmission ensures precise timing but increases hardware complexity.</p>\r\n\r\n    <h2>2. Introduction to Networks and Communication Media</h2>\r\n    <p>Networks facilitate resource sharing, communication, and data transfer, classified by geographical scope and purpose. Connection types determine bandwidth allocation and contention.</p>\r\n    <ul>\r\n        <li><strong>Network Categories</strong>:\r\n            <ul>\r\n                <li><strong>Personal Area Network (PAN)</strong>: Short-range (10m), low-power (e.g., Bluetooth 5.0: 2 Mbps, Zigbee: 250 kbps). Used for IoT devices, wearables.</li>\r\n                <li><strong>Local Area Network (LAN)</strong>: Covers offices/schools (100-500m), supports Ethernet (10 Mbps to 100 Gbps). Example: IEEE 802.3ab (Gigabit Ethernet).</li>\r\n                <li><strong>Campus Area Network (CAN)</strong>: Interconnects LANs across a campus (1-5 km), often using fiber for high-speed backbones (10 Gbps).</li>\r\n                <li><strong>Metropolitan Area Network (MAN)</strong>: Spans cities (50 km), e.g., WiMAX (IEEE 802.16, up to 70 Mbps) or metro Ethernet.</li>\r\n                <li><strong>Wide Area Network (WAN)</strong>: Global scale, using leased lines, MPLS, or satellites. Protocols like BGP ensure routing. Example: Internet backbone (400 Gbps links).</li>\r\n                <li><strong>Storage Area Network (SAN)</strong>: High-speed (8-32 Gbps via Fibre Channel), low-latency (<1ms) for server-storage communication in data centers.</li>\r\n            </ul>\r\n        </li>\r\n        <li><strong>Connection Types</strong>:\r\n            <ul>\r\n                <li><strong>Point-to-Point</strong>: Dedicated link, no contention (e.g., PPP over T1 lines, 1.544 Mbps). High reliability but costly.</li>\r\n                <li><strong>Multipoint</strong>: Shared medium, contention managed by protocols like CSMA/CD (Ethernet) or CSMA/CA (Wi-Fi).</li>\r\n            </ul>\r\n        </li>\r\n    </ul>\r\n    <h3>Advanced Concepts</h3>\r\n    <p><strong>Trade-offs</strong>: PANs prioritize low power over speed; WANs prioritize reliability over latency. MANs balance cost and coverage for urban areas.</p>\r\n    <p><strong>Emerging Technologies</strong>: Low-Power WAN (LPWAN) like LoRa (0.3-50 kbps, 10 km range) for IoT. SD-WAN optimizes WAN traffic using software-defined routing.</p>\r\n    <p><strong>Practical Example</strong>: In a smart city, MANs integrate traffic sensors (LPWAN), municipal Wi-Fi (LAN), and inter-city links (WAN) for real-time data analytics.</p>\r\n\r\n    <h2>3. Network Hardware, Software, and Standards</h2>\r\n    <p>Networking relies on specialized hardware for physical connectivity, software for protocol execution, and standards for interoperability.</p>\r\n    <ul>\r\n        <li><strong>Hardware Components</strong>:\r\n            <ul>\r\n                <li><strong>Network Interface Card (NIC)</strong>: Provides MAC address (48-bit, globally unique), supports full-duplex (simultaneous send/receive). Example: 10GBASE-T NIC (10 Gbps).</li>\r\n                <li><strong>Bridge</strong>: Layer 2 device, forwards frames based on MAC addresses, uses Spanning Tree Protocol (STP, IEEE 802.1D) to prevent loops.</li>\r\n                <li><strong>Switch</strong>: Multi-port bridge, supports VLANs (IEEE 802.1Q) for traffic segmentation, ASIC-based forwarding for low latency (<1µs).</li>\r\n                <li><strong>Router</strong>: Layer 3, uses routing protocols (RIP, OSPF, BGP) and IP addressing. Features NAT, QoS for traffic prioritization.</li>\r\n                <li><strong>Repeater</strong>: Layer 1, regenerates signals to extend range (e.g., Ethernet hub, extends 100m limit of Cat5e).</li>\r\n            </ul>\r\n        </li>\r\n        <li><strong>Network Software</strong>: \r\n            <ul>\r\n                <li>Protocol stacks in OS kernel (e.g., TCP/IP in Linux/Windows).</li>\r\n                <li>APIs: Berkeley sockets (Unix) or Winsock (Windows) for socket programming (bind(), listen(), accept(), connect()).</li>\r\n                <li>Example: A server application uses socket() to create a TCP socket, bind() to assign a port, and listen() for client connections.</li>\r\n            </ul>\r\n        </li>\r\n        <li><strong>Standards</strong>:\r\n            <ul>\r\n                <li><strong>De-jure</strong>: IEEE 802.3 (Ethernet), ISO/IEC 7498 (OSI model), ITU-T standards (e.g., V.35 for serial links).</li>\r\n                <li><strong>De-facto</strong>: TCP/IP suite, dominant in internet; proprietary protocols like Cisco’s CDP (Cisco Discovery Protocol).</li>\r\n            </ul>\r\n        </li>\r\n    </ul>\r\n    <h3>Advanced Concepts</h3>\r\n    <p><strong>Switch vs. Router</strong>: Switches forward frames within a LAN (Layer 2, MAC-based); routers forward packets across networks (Layer 3, IP-based). Switches use CAM tables; routers use routing tables.</p>\r\n    <p><strong>Software-Defined Networking (SDN)</strong>: Separates control plane (routing decisions) from data plane (forwarding). OpenFlow protocol enables programmable switches.</p>\r\n    <p><strong>Practical Example</strong>: In a data center, a 48-port 10GbE switch handles intra-rack traffic, while a router with BGP connects to external ISPs.</p>\r\n    <p><strong>Trade-offs</strong>: Managed switches offer VLANs, QoS but are costlier than unmanaged. Routers add latency due to complex routing decisions.</p>\r\n\r\n    <h2>4. ISO/OSI Reference Model: The Foundational Framework</h2>\r\n    <p>The OSI model provides a standardized, layered approach to networking, enabling modularity and interoperability. Data flows through encapsulation (adding headers/trailers downward) and decapsulation (removing upward).</p>\r\n    <ul>\r\n        <li><strong>Seven Layers</strong>:\r\n            <ul>\r\n                <li><strong>Physical (Layer 1)</strong>: Transmits raw bits via hardware (e.g., RJ45, fiber transceivers). Defines bit rate, voltage levels, connectors.</li>\r\n                <li><strong>Data Link (Layer 2)</strong>: Manages frames, physical addressing (MAC), error detection (CRC-32), flow control (sliding window, stop-and-wait). Sublayers: LLC (logical link control), MAC (media access control).</li>\r\n                <li><strong>Network (Layer 3)</strong>: Handles packets, logical addressing (IPv4/IPv6), routing (distance vector like RIP, link-state like OSPF). Fragmentation/reassembly for large packets.</li>\r\n                <li><strong>Transport (Layer 4)</strong>: Manages segments, provides reliability (TCP) or low overhead (UDP). Features: connection setup, error recovery, congestion control (TCP’s AIMD: Additive Increase, Multiplicative Decrease).</li>\r\n                <li><strong>Session (Layer 5)</strong>: Establishes/manages sessions, supports dialog control (simplex, half-duplex, full-duplex), synchronization (e.g., recovery points in database transactions).</li>\r\n                <li><strong>Presentation (Layer 6)</strong>: Handles data translation (ASCII, EBCDIC), compression (gzip, JPEG), encryption (SSL/TLS, AES).</li>\r\n                <li><strong>Application (Layer 7)</strong>: Provides network services to applications (HTTP, FTP, SMTP). Example: Browser uses HTTP to fetch web pages.</li>\r\n            </ul>\r\n        </li>\r\n        <li><strong>Hardware vs. Software</strong>: \r\n            <ul>\r\n                <li>Layers 1-3: Hardware/firmware (NICs, switches, routers).</li>\r\n                <li>Layer 4: Hybrid (TCP in OS kernel, hardware offloading in NICs).</li>\r\n                <li>Layers 5-7: Software (OS, application logic).</li>\r\n            </ul>\r\n        </li>\r\n    </ul>\r\n    <h3>Advanced Concepts</h3>\r\n    <p><strong>Data Flow</strong>: Application data becomes a segment (Layer 4, TCP header), packet (Layer 3, IP header), frame (Layer 2, MAC header/trailer), and bits (Layer 1). Reverse process at receiver.</p>\r\n    <p><strong>TCP/IP vs. OSI</strong>: TCP/IP combines OSI’s Session/Presentation/Application into one Application layer, and Data Link/Physical into Link layer. More practical but less granular.</p>\r\n    <p><strong>Practical Example</strong>: HTTP request: Application (HTTP) → Transport (TCP, port 80) → Network (IP address) → Data Link (Ethernet frame) → Physical (bits over fiber).</p>\r\n    <p><strong>Trade-offs</strong>: OSI’s modularity aids design but adds overhead; TCP/IP is leaner but less structured.</p>\r\n\r\n    <h2>5. Transmission Media and Network Topologies</h2>\r\n    <p>Transmission media and topologies determine how data travels and how devices are interconnected, impacting performance, cost, and reliability.</p>\r\n    <ul>\r\n        <li><strong>Transmission Media</strong>:\r\n            <ul>\r\n                <li><strong>Guided Media</strong>: \r\n                    <ul>\r\n                        <li><strong>Twisted Pair</strong>: UTP (Cat5e: 1 Gbps, 100m; Cat6a: 10 Gbps), STP (better EMI resistance). Susceptible to crosstalk, attenuation.</li>\r\n                        <li><strong>Coaxial Cable</strong>: RG-6 (1 Gbps, 500m in cable TV), RG-58 (10 Mbps in old Ethernet). Higher bandwidth than UTP but bulkier.</li>\r\n                        <li><strong>Fiber Optics</strong>: Single-mode (40 Gbps, 100 km, 0.2 dB/km loss), multimode (10 Gbps, 2 km, 1 dB/km). Immune to EMI, uses light (1310/1550 nm).</li>\r\n                    </ul>\r\n                </li>\r\n                <li><strong>Unguided Media</strong>: \r\n                    <ul>\r\n                        <li><strong>Microwave</strong>: Line-of-sight, 1-40 GHz, 1 Gbps up to 50 km. Affected by weather (rain fade).</li>\r\n                        <li><strong>Radio Waves</strong>: 3 kHz-300 GHz, omnidirectional. Wi-Fi (802.11ax: 9.6 Gbps), cellular (5G: 20 Gbps peak).</li>\r\n                        <li><strong>Infrared</strong>: 300 GHz-400 THz, short-range (1m, IrDA: 4 Mbps), used in remote controls, line-of-sight.</li>\r\n                    </ul>\r\n                </li>\r\n            </ul>\r\n        </li>\r\n        <li><strong>Network Topologies</strong>:\r\n            <ul>\r\n                <li><strong>Bus</strong>: Single cable, terminators prevent signal reflection. Uses CSMA/CD. Pros: Low cost; Cons: Collisions, single-point failure.</li>\r\n                <li><strong>Ring</strong>: Circular, token-based (IEEE 802.5). Bidirectional rings (FDDI) improve fault tolerance. Pros: No collisions; Cons: Node failure disrupts ring.</li>\r\n                <li><strong>Star</strong>: Central hub/switch. Pros: Easy to manage, fault isolation; Cons: Hub failure collapses network.</li>\r\n                <li><strong>Mesh</strong>: Full mesh: N(N-1)/2 links, partial mesh for cost savings. Pros: High redundancy; Cons: High cost, O(N^2) complexity.</li>\r\n                <li><strong>Tree</strong>: Hierarchical, used in enterprise networks. Pros: Scalable; Cons: Root failure impacts branches.</li>\r\n                <li><strong>Hybrid</strong>: Combines star-ring or star-bus. Example: Campus backbone (ring) with star LANs.</li>\r\n            </ul>\r\n        </li>\r\n    </ul>\r\n    <h3>Advanced Concepts</h3>\r\n    <p><strong>Media Selection</strong>: Fiber for long-distance, high-bandwidth; twisted pair for cost-effective LANs; wireless for mobility. Attenuation formula: Loss = 10 log10(Pout/Pin) dB.</p>\r\n    <p><strong>Topology Design</strong>: Data centers use leaf-spine (hybrid tree/mesh) for low latency (<10µs). Military networks use full mesh for reliability despite high cost.</p>\r\n    <p><strong>Practical Example</strong>: A university campus uses a tree topology: Fiber backbone (root) connects star-topology LANs in each building, with Wi-Fi for mobility.</p>\r\n    <p><strong>Trade-offs</strong>: Star is cost-effective but hub-dependent; mesh is reliable but wiring-intensive. Hybrid balances scalability and fault tolerance.</p>\r\n</body>\r\n</html>', 'hard');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('30', 'CSA04', 'Unit 1: Foundational Concepts in Operating Systems', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Unit 1: Foundational Concepts in Operating Systems - Hard Mode</title>\r\n    <style>\r\n        body {\r\n            margin: 20px;\r\n            background-color: #f4f4f4;\r\n            line-height: 1.5;\r\n        }\r\n        h1 {\r\n            font-size: 1.8em;\r\n            font-weight: bold;\r\n            text-align: center;\r\n            color: #2c3e50;\r\n        }\r\n        h2 {\r\n            font-size: 1.4em;\r\n            font-weight: bold;\r\n            color: #2980b9;\r\n            margin-top: 20px;\r\n        }\r\n        h3 {\r\n            font-size: 1.2em;\r\n            font-weight: bold;\r\n            color: #16a085;\r\n            margin-top: 15px;\r\n        }\r\n        p {\r\n            font-size: 1em;\r\n            color: #34495e;\r\n        }\r\n        ul {\r\n            list-style-type: none;\r\n            padding-left: 20px;\r\n        }\r\n        ul li {\r\n            font-size: 1em;\r\n            color: #34495e;\r\n            margin-bottom: 5px;\r\n        }\r\n        ul li::before {\r\n            content: \"• \";\r\n            color: #2980b9;\r\n            font-weight: bold;\r\n        }\r\n        ul ul {\r\n            padding-left: 30px;\r\n        }\r\n        ul ul li::before {\r\n            content: \"◦ \";\r\n            color: #16a085;\r\n        }\r\n        strong {\r\n            font-weight: bold;\r\n            color: #2c3e50;\r\n        }\r\n        @media (max-width: 600px) {\r\n            h1 {\r\n                font-size: 1.5em;\r\n            }\r\n            h2 {\r\n                font-size: 1.2em;\r\n            }\r\n            h3 {\r\n                font-size: 1.1em;\r\n            }\r\n            p, ul li {\r\n                font-size: 0.9em;\r\n            }\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n<h1>Unit 1: Foundational Concepts in Operating Systems</h1>\r\n<p>This enhanced version includes deeper explanations, advanced concepts, mathematical models, practical examples, trade-offs, and real-world applications to master OS foundations thoroughly.</p>\r\n\r\n<h2>Topic 1: The Genesis and Evolution of Operating Systems</h2>\r\n<p>OS evolution addresses computational bottlenecks, optimizing resources like <strong>CPU</strong> (utilization formula: <strong>U = (busy time) / (total time)</strong>), memory, and I/O throughput. It transitions from centralized to distributed paradigms, enabling scalability in modern systems.</p>\r\n<ul>\r\n    <li><strong>Serial Processing (1940s-1950s)</strong>\r\n        <ul>\r\n            <li>No OS; direct hardware manipulation via switches, punch cards, or plugboards.</li>\r\n            <li><strong>Inefficiencies</strong>: High setup time (e.g., 5-10 minutes per job), CPU idle during I/O (e.g., tape read: 100ms latency).</li>\r\n            <li><strong>Metrics</strong>: Throughput ~1-2 jobs/hour; CPU utilization &lt;10%.</li>\r\n            <li><strong>Trade-offs</strong>: Simple hardware but labor-intensive; error-prone manual debugging.</li>\r\n            <li><strong>Example</strong>: ENIAC (1945) required rewiring for each computation, used for ballistic calculations.</li>\r\n            <li><strong>Advanced</strong>: Early debugging via oscilloscopes; no error-handling mechanisms.</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>Simple Batch Systems (Late 1950s-Early 1960s)</strong>\r\n        <ul>\r\n            <li>Jobs batched on tape; automatic sequencing via monitor (early OS kernel).</li>\r\n            <li><strong>Mechanism</strong>: Operator loads batch; resident monitor handles job control language (JCL).</li>\r\n            <li><strong>Improvement</strong>: Reduced setup overhead; utilization ~40% (formula: U = 1 - (I/O time / total time)).</li>\r\n            <li><strong>Limitations</strong>: Sequential execution; CPU idle on slow I/O (e.g., card reader: 600 cards/min).</li>\r\n            <li><strong>Advanced</strong>: Spooling (Simultaneous Peripheral Operations On-Line) buffers I/O to disk, reducing wait time by ~50%.</li>\r\n            <li><strong>Example</strong>: IBM 1401 (1959) for commercial batch processing like accounting.</li>\r\n            <li><strong>Real-World</strong>: Payroll systems processed 1000s of records overnight.</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>Multiprogrammed Batch Systems (Mid-1960s)</strong>\r\n        <ul>\r\n            <li>Multiple jobs in memory; CPU switches on I/O blocks (context switch overhead ~10-50µs).</li>\r\n            <li><strong>Memory Management</strong>: Fixed partitions (e.g., 4 partitions of 16KB each); internal fragmentation (wasted space = partition size - job size).</li>\r\n            <li><strong>Performance</strong>: Utilization ~80% with 4 jobs; throughput T = N / (avg job time + switch overhead), N=jobs.</li>\r\n            <li><strong>Trade-offs</strong>: Increased complexity in scheduling vs. better resource use; memory protection needed to prevent interference.</li>\r\n            <li><strong>Advanced</strong>: Dynamic partitioning reduced fragmentation but introduced external fragmentation (compaction overhead ~ms).</li>\r\n            <li><strong>Example</strong>: IBM OS/360 (1964) supported multiprogramming for diverse workloads.</li>\r\n            <li><strong>Real-World</strong>: Used in airline reservation systems (SABRE, ~100 transactions/s).</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>Time-Sharing Systems (Late 1960s-1970s)</strong>\r\n        <ul>\r\n            <li>CPU time-sliced (quantum q ~10-100ms); preemptive scheduling for interactivity.</li>\r\n            <li><strong>Algorithm</strong>: Round-Robin (turnaround time = (N-1)*q + service time for N processes).</li>\r\n            <li><strong>Response Time</strong>: RT = q * (1 + CPU burst / q); aims for &lt;1s for human interaction.</li>\r\n            <li><strong>Advanced</strong>: Priority scheduling with aging to prevent starvation (priority increment = wait time / factor); virtual memory introduced.</li>\r\n            <li><strong>Trade-offs</strong>: Overhead from frequent switches (1-5% CPU) vs. multi-user support.</li>\r\n            <li><strong>Example</strong>: MULTICS (1969) with virtual memory; CTSS (1961) first time-sharing system.</li>\r\n            <li><strong>Real-World</strong>: UNIX (1970s) enabled interactive development for programmers.</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>Mainframe and Multiprocessor Systems (1970s-1990s)</strong>\r\n        <ul>\r\n            <li>Mainframes: High-reliability with redundant CPUs (e.g., IBM z15 with 190 cores).</li>\r\n            <li>Multiprocessor: SMP (Symmetric Multi-Processing); speedup S = 1 / (f + (1-f)/P), Amdahl\'s Law (f=serial fraction, P=processors).</li>\r\n            <li><strong>Advanced</strong>: Cache coherence (MESI protocol, latency ~10ns); NUMA (Non-Uniform Memory Access) for scalability.</li>\r\n            <li><strong>Trade-offs</strong>: Scalability limited by bus contention (~1GB/s bottleneck); high cost for enterprise reliability.</li>\r\n            <li><strong>Example</strong>: IBM z/OS on zSeries for transaction processing (e.g., banking, &gt;1M TPS).</li>\r\n            <li><strong>Real-World</strong>: Financial systems handling millions of daily transactions.</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>Distributed and Clustered Systems (1980s-Present)</strong>\r\n        <ul>\r\n            <li>Distributed: Tasks across networks; middleware like CORBA for transparency.</li>\r\n            <li>Clustered: Shared storage (e.g., SAN); failover for high availability (MTTF = MTBF / (MTBF + MTTR)).</li>\r\n            <li><strong>Advanced</strong>: Consensus algorithms (Paxos/Raft, latency ~ms); load balancing (round-robin DNS, ~10µs).</li>\r\n            <li><strong>Trade-offs</strong>: Network latency (~1ms) vs. scalability; consistency models (eventual vs. strong).</li>\r\n            <li><strong>Example</strong>: Google Spanner (distributed DB, global consistency); Kubernetes clusters for container orchestration.</li>\r\n            <li><strong>Real-World</strong>: Cloud platforms like AWS EC2 for scalable web services.</li>\r\n        </ul>\r\n    </li>\r\n</ul>\r\n<h3>Core Theme</h3>\r\n<p>Evolution optimizes utilization (from &lt;10% to &gt;90%), adapts to hardware advances (multi-core, networks), and enables cloud paradigms (e.g., AWS EC2 virtualization, ~99.99% uptime).</p>\r\n\r\n<h2>Topic 2: Core Structures, Components, and Services of the OS</h2>\r\n<p>OS as resource allocator uses modular components for efficiency, with services exposed via system calls (e.g., POSIX API for portability across UNIX-like systems).</p>\r\n<ul>\r\n    <li><strong>Process Management</strong>\r\n        <ul>\r\n            <li><strong>Lifecycle</strong>: New → Ready → Running → Waiting → Terminated; PCB stores state (PID, registers, priority).</li>\r\n            <li><strong>Scheduling</strong>: SJF (optimal turnaround, avg wait = sum(bursts)/N); MLFQ adapts priorities dynamically.</li>\r\n            <li><strong>Synchronization</strong>: Semaphores (P/V operations, O(1)); deadlock prevention via Banker\'s algorithm (O(N^2) complexity).</li>\r\n            <li><strong>Advanced</strong>: RCU (Read-Copy-Update) for lock-free concurrency (Linux kernel, ~ns latency); monitors for mutual exclusion.</li>\r\n            <li><strong>Trade-offs</strong>: Preemptive scheduling improves responsiveness but increases context switch overhead (~1µs).</li>\r\n            <li><strong>Example</strong>: Linux CFS uses red-black trees for O(log N) scheduling.</li>\r\n            <li><strong>Real-World</strong>: Docker containers rely on Linux cgroups for process isolation.</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>Main Memory Management</strong>\r\n        <ul>\r\n            <li><strong>Allocation</strong>: Buddy system (2^k blocks, O(log N)); fragmentation (external: holes, internal: ~10% waste).</li>\r\n            <li><strong>Virtual Memory</strong>: Paging (4KB pages); demand paging with LRU replacement (hit ratio h = 1 - page faults / references).</li>\r\n            <li><strong>Advanced</strong>: TLB (hit time ~1ns, miss ~100ns); NUMA-aware allocation for multi-socket systems.</li>\r\n            <li><strong>Trade-offs</strong>: Virtual memory isolates processes but TLB misses add latency (~0.1% performance hit).</li>\r\n            <li><strong>Example</strong>: Windows working set model minimizes thrashing via adaptive page allocation.</li>\r\n            <li><strong>Real-World</strong>: VMWare ESXi uses ballooning for memory overcommitment in VMs.</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>File Management</strong>\r\n        <ul>\r\n            <li><strong>Structures</strong>: Inodes (Unix, 128 bytes); allocation methods (contiguous: fast but fragmented; indexed: scalable).</li>\r\n            <li><strong>Operations</strong>: Journaling (ext4, ~10% write overhead); caching (read-ahead, ~50% faster reads).</li>\r\n            <li><strong>Advanced</strong>: ACLs for fine-grained access; RAID-5 (parity, 4 I/Os per write).</li>\r\n            <li><strong>Trade-offs</strong>: Journaling ensures consistency but reduces write performance.</li>\r\n            <li><strong>Example</strong>: NTFS supports compression (2:1 ratio), encryption, and quotas.</li>\r\n            <li><strong>Real-World</strong>: Dropbox uses file systems for sync with versioning.</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>I/O Management</strong>\r\n        <ul>\r\n            <li><strong>Buffering</strong>: Double buffering (reduces wait by ~50%); spooling for printers (queue latency ~ms).</li>\r\n            <li><strong>Drivers</strong>: Interrupt-driven (latency ~10µs) vs. polling (overhead = checks / interrupts).</li>\r\n            <li><strong>Advanced</strong>: I/O scheduling (C-SCAN, fairness ~90%); asynchronous I/O (AIO, ~1M IOPS).</li>\r\n            <li><strong>Trade-offs</strong>: Interrupts reduce CPU waste but context switches add overhead.</li>\r\n            <li><strong>Example</strong>: Linux io_uring for high-performance I/O (e.g., databases).</li>\r\n            <li><strong>Real-World</strong>: NVMe SSDs use AIO for low-latency storage access.</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>Secondary Storage Management</strong>\r\n        <ul>\r\n            <li><strong>Disk Scheduling</strong>: SSTF (seek time ~5ms); elevator algorithm (SCAN, ~10ms seek).</li>\r\n            <li><strong>Free Space</strong>: Bitmap (1 bit/block, O(N)); linked list (O(1) updates).</li>\r\n            <li><strong>Advanced</strong>: SSD TRIM (extends lifespan, TBW ~100TB); ZFS snapshots for versioning.</li>\r\n            <li><strong>Trade-offs</strong>: SSDs reduce latency (~0.1ms) but wear out faster than HDDs.</li>\r\n            <li><strong>Example</strong>: Windows chkdsk for error correction and bad sector remapping.</li>\r\n            <li><strong>Real-World</strong>: AWS EBS uses SSDs with snapshots for backups.</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>Networking/Communication Management</strong>\r\n        <ul>\r\n            <li><strong>Protocols</strong>: TCP congestion control (Reno: AIMD, window size W = W/2 on loss); sockets for IPC.</li>\r\n            <li><strong>Shared Memory</strong>: vs. message passing (pipes, queues); RDMA (~1µs latency).</li>\r\n            <li><strong>Advanced</strong>: VLANs for isolation; QoS (DiffServ, ~5% bandwidth overhead).</li>\r\n            <li><strong>Trade-offs</strong>: RDMA reduces latency but requires InfiniBand hardware.</li>\r\n            <li><strong>Example</strong>: Linux netfilter for firewalls and NAT in cloud VMs.</li>\r\n            <li><strong>Real-World</strong>: Google Cloud uses SDN for low-latency networking.</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>Protection and Security</strong>\r\n        <ul>\r\n            <li><strong>Access Control</strong>: RBAC; SELinux mandatory access control (policy size ~MB).</li>\r\n            <li><strong>Encryption</strong>: dm-crypt (AES-256, ~5% CPU overhead); auditing (syslog).</li>\r\n            <li><strong>Advanced</strong>: ASLR against exploits; TEE (SGX for secure enclaves).</li>\r\n            <li><strong>Trade-offs</strong>: Security adds overhead but prevents breaches (e.g., Spectre mitigation).</li>\r\n            <li><strong>Example</strong>: Windows BitLocker for full-disk encryption.</li>\r\n            <li><strong>Real-World</strong>: Secure boot in UEFI prevents unauthorized OS loading.</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>Error Detection and Accounting</strong>\r\n        <ul>\r\n            <li><strong>Handling</strong>: ECC memory (Hamming code, 2-bit error detection); watchdog timers (~ms reset).</li>\r\n            <li><strong>Accounting</strong>: Quotas (disk, CPU); logging (kernel oops, ~MB/day).</li>\r\n            <li><strong>Advanced</strong>: Crash dumps (minidumps, ~GB); kdump for Linux crash analysis.</li>\r\n            <li><strong>Trade-offs</strong>: Logging aids debugging but consumes storage.</li>\r\n            <li><strong>Example</strong>: Windows Event Log for error tracking.</li>\r\n            <li><strong>Real-World</strong>: Splunk uses OS logs for enterprise monitoring.</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>Operating System Services</strong>\r\n        <ul>\r\n            <li><strong>User Interface</strong>: CLI (bash, ~100 commands); GUI (Wayland, ~1ms latency).</li>\r\n            <li><strong>Program Execution</strong>: Loader resolves symbols; dynamic linking (~10% memory savings).</li>\r\n            <li><strong>I/O Operations</strong>: Vectored I/O (scatter-gather, ~50% syscall reduction).</li>\r\n            <li><strong>File System Manipulation</strong>: Mount namespaces for container isolation.</li>\r\n            <li><strong>Communications</strong>: RPC over gRPC (~1ms latency).</li>\r\n            <li><strong>Example</strong>: systemd in Linux manages service execution.</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>System Calls</strong>\r\n        <ul>\r\n            <li><strong>Interface</strong>: Trap to kernel mode; parameters via registers/stack.</li>\r\n            <li><strong>Categories</strong>: Process (fork, waitpid); File (open, lseek); Device (ioctl).</li>\r\n            <li><strong>Overhead</strong>: ~0.1-1µs per call; strace for tracing.</li>\r\n            <li><strong>Advanced</strong>: COW in fork() for memory efficiency (saves ~MB/process).</li>\r\n            <li><strong>Example</strong>: POSIX fork() creates child process with COW.</li>\r\n            <li><strong>Real-World</strong>: Apache web server uses fork() for multi-process handling.</li>\r\n        </ul>\r\n    </li>\r\n</ul>\r\n<h3>Core Role</h3>\r\n<p>Components optimize resources (e.g., scheduling minimizes wait time W = sum(bursts)/N); services abstract hardware for portability across diverse platforms.</p>\r\n\r\n<h2>Topic 3: System Design, Implementation, and Hardware Interaction</h2>\r\n<p>OS design balances conflicting goals via modular, layered architectures, leveraging hardware features for performance.</p>\r\n<ul>\r\n    <li><strong>Design Goals</strong>\r\n        <ul>\r\n            <li><strong>User Goals</strong>: Usability (e.g., Android gestures, ~100ms response); Reliability (99.999% uptime); Performance (RTOS jitter ~1ms).</li>\r\n            <li><strong>System Goals</strong>: Modularity (microkernel vs. monolithic); Flexibility (runtime module loading).</li>\r\n            <li><strong>Policy vs. Mechanism</strong>: Scheduler mechanism fixed, policy (FIFO vs. RR) configurable.</li>\r\n            <li><strong>Trade-offs</strong>: User convenience increases complexity; efficiency may sacrifice flexibility.</li>\r\n            <li><strong>Advanced</strong>: Containers (Docker) use namespaces for lightweight virtualization.</li>\r\n            <li><strong>Example</strong>: Linux cgroups for resource isolation in cloud environments.</li>\r\n            <li><strong>Real-World</strong>: Kubernetes uses cgroups for container resource management.</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>Implementation</strong>\r\n        <ul>\r\n            <li><strong>Languages</strong>: Assembly for bootloaders (x86 real mode, ~1KB); C for kernel (pointers); Rust for safety (Linux drivers).</li>\r\n            <li><strong>Layered Architecture</strong>: Microkernel (Minix: ~12K LOC, user-space drivers) vs. Monolithic (Linux: ~30M LOC, faster).</li>\r\n            <li><strong>Build Process</strong>: Cross-compilation; debugging with gdb/kgdb for kernel crashes.</li>\r\n            <li><strong>Advanced</strong>: seL4 microkernel (formally verified, zero vulnerabilities).</li>\r\n            <li><strong>Trade-offs</strong>: Microkernel security vs. monolithic performance (~10% faster).</li>\r\n            <li><strong>Example</strong>: FreeBSD\'s modular kernel with kldload for drivers.</li>\r\n            <li><strong>Real-World</strong>: Android uses Linux kernel with Bionic libc for mobile optimization.</li>\r\n        </ul>\r\n    </li>\r\n    <li><strong>Hardware Interaction</strong>\r\n        <ul>\r\n            <li><strong>Integration</strong>: Manages interrupts (IRQ vectors, ~100ns); timers (HPET, 1ns precision).</li>\r\n            <li><strong>I/O Channels</strong>: Dedicated controllers (SATA AHCI, ~10GB/s); co-processors for offload.</li>\r\n            <li><strong>DMA</strong>: Bypasses CPU (PCIe ~10GB/s); scatter-gather for efficiency.</li>\r\n            <li><strong>Co-dependency</strong>: VT-x/AMD-V for VMs; ACPI for power management (C-states, ~µs transitions).</li>\r\n            <li><strong>Advanced</strong>: IOMMU for secure DMA; NUMA-aware scheduling (latency ~ns/core).</li>\r\n            <li><strong>Trade-offs</strong>: Hardware offload reduces CPU load but driver complexity (~10K LOC).</li>\r\n            <li><strong>Example</strong>: Linux VFIO for GPU passthrough in VMs.</li>\r\n            <li><strong>Real-World</strong>: AWS Nitro uses hardware offloading for VM performance.</li>\r\n        </ul>\r\n    </li>\r\n</ul>\r\n<h3>Core Principle</h3>\r\n<p>Design separates concerns for maintainability; implementation optimizes for hardware, achieving high performance (e.g., context switch &lt;1µs on modern CPUs).</p>\r\n</body>\r\n</html>', 'easy');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('31', 'CSA04', 'Unit 1: Foundational Concepts in Operating Systems', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Unit 1: Foundational Concepts in Operating Systems - Hard Mode</title>\r\n</head>\r\n<body>\r\n<pre>\r\nUnit 1: Foundational Concepts in Operating Systems\r\nThis enhanced version includes deeper explanations, advanced concepts, mathematical models, practical examples, trade-offs, and real-world applications to master OS foundations thoroughly.\r\n\r\nTopic 1: The Genesis and Evolution of Operating Systems\r\n\r\nOS evolution addresses computational bottlenecks, optimizing resources like CPU (utilization formula: U = (busy time) / (total time)), memory, and I/O throughput. It transitions from centralized to distributed paradigms, enabling scalability in modern systems.\r\n\r\n1. Serial Processing (1940s-1950s)\r\n   - No OS; direct hardware manipulation via switches, punch cards, or plugboards.\r\n   - Inefficiencies: High setup time (e.g., 5-10 minutes per job), CPU idle during I/O (e.g., tape read: 100ms latency).\r\n   - Metrics: Throughput ~1-2 jobs/hour; CPU utilization &lt;10%.\r\n   - Trade-offs: Simple hardware but labor-intensive; error-prone manual debugging.\r\n   - Example: ENIAC (1945) required rewiring for each computation, used for ballistic calculations.\r\n\r\n2. Simple Batch Systems (Late 1950s-Early 1960s)\r\n   - Jobs batched on tape; automatic sequencing via monitor (early OS kernel).\r\n   - Mechanism: Operator loads batch; resident monitor handles job control language (JCL).\r\n   - Improvement: Reduced setup overhead; utilization ~40% (formula: U = 1 - (I/O time / total time)).\r\n   - Limitations: Sequential execution; CPU idle on slow I/O (e.g., card reader: 600 cards/min).\r\n   - Advanced: Spooling (Simultaneous Peripheral Operations On-Line) buffers I/O to disk.\r\n   - Example: IBM 1401 (1959) for commercial batch processing like accounting.\r\n\r\n3. Multiprogrammed Batch Systems (Mid-1960s)\r\n   - Multiple jobs in memory; CPU switches on I/O blocks (context switch overhead ~10-50µs).\r\n   - Memory Management: Fixed partitions (e.g., 4 partitions of 16KB each); internal fragmentation (wasted space = partition size - job size).\r\n   - Performance: Utilization ~80% with 4 jobs; throughput T = N / (avg job time + switch overhead), N=jobs.\r\n   - Trade-offs: Increased complexity in scheduling vs. better resource use; memory protection needed to prevent interference.\r\n   - Example: IBM OS/360 (1964) supported multiprogramming for diverse workloads.\r\n\r\n4. Time-Sharing Systems (Late 1960s-1970s)\r\n   - CPU time-sliced (quantum q ~10-100ms); preemptive scheduling for interactivity.\r\n   - Algorithm: Round-Robin (turnaround time = (N-1)*q + service time for N processes).\r\n   - Response Time: RT = q * (1 + CPU burst / q); aims for &lt;1s for human interaction.\r\n   - Advanced: Priority scheduling with aging to prevent starvation (priority increment = wait time / factor).\r\n   - Trade-offs: Overhead from frequent switches (1-5% CPU) vs. multi-user support.\r\n   - Example: MULTICS (1969) with virtual memory; CTSS (1961) first time-sharing system.\r\n\r\n5. Mainframe and Multiprocessor Systems (1970s-1990s)\r\n   - Mainframes: High-reliability with redundant CPUs (e.g., fault-tolerant designs).\r\n   - Multiprocessor: SMP (Symmetric Multi-Processing); speedup S = 1 / (f + (1-f)/P), Amdahl\'s Law (f=serial fraction, P=processors).\r\n   - Advanced: Cache coherence (MESI protocol) for shared memory.\r\n   - Trade-offs: Scalability limited by bus contention; high cost for enterprise reliability.\r\n   - Example: IBM z/OS on zSeries mainframes for transaction processing (e.g., banking, &gt;1M TPS).\r\n\r\n6. Distributed and Clustered Systems (1980s-Present)\r\n   - Distributed: Tasks across networks; middleware like CORBA for transparency.\r\n   - Clustered: Shared storage (e.g., SAN); failover for high availability (MTTF = MTBF / (MTBF + MTTR)).\r\n   - Advanced: Consensus algorithms (Paxos/Raft) for fault tolerance; load balancing (round-robin DNS).\r\n   - Trade-offs: Network latency (~1ms) vs. scalability; consistency models (eventual vs. strong).\r\n   - Example: Google Spanner (distributed DB); Kubernetes clusters for container orchestration.\r\n\r\nCore Theme: Evolution optimizes utilization (from &lt;10% to &gt;90%), adapts to hardware advances (multi-core, networks), and enables cloud paradigms (e.g., AWS EC2 virtualization).\r\n\r\nTopic 2: Core Structures, Components, and Services of the OS\r\n\r\nOS as resource allocator uses modular components for efficiency, with services exposed via system calls (e.g., POSIX API for portability).\r\n\r\n1. Primary System Components\r\n   - Process Management\r\n     - Lifecycle: New → Ready → Running → Waiting → Terminated; PCB (Process Control Block) stores state.\r\n     - Scheduling: Algorithms like SJF (optimal turnaround, but starvation risk); MLFQ (multi-level feedback queue) adapts priorities.\r\n     - Synchronization: Semaphores (P/V operations); avoid deadlocks via Banker\'s algorithm.\r\n     - Example: Linux scheduler (CFS: Completely Fair Scheduler) uses red-black trees for O(log N) operations.\r\n   - Main Memory Management\r\n     - Allocation: Buddy system (2^k blocks); fragmentation (external: holes, internal: unused in partitions).\r\n     - Virtual Memory: Paging (page size 4KB); demand paging with LRU replacement (hit ratio h = 1 - page faults / references).\r\n     - Advanced: TLB (Translation Lookaside Buffer) for fast address translation (hit time ~1ns).\r\n     - Example: Windows uses working set model to minimize thrashing.\r\n   - File Management\r\n     - Structures: Inodes (Unix); allocation methods (contiguous, linked, indexed).\r\n     - Operations: Atomicity via journaling (e.g., ext4); caching for performance (read-ahead).\r\n     - Advanced: ACLs for fine-grained access; RAID levels for redundancy (e.g., RAID-5 parity).\r\n     - Example: NTFS supports compression, encryption, and quotas.\r\n   - I/O Management\r\n     - Buffering: Double buffering reduces wait time; spooling for printers.\r\n     - Drivers: Interrupt-driven vs. polling (polling overhead = checks / interrupts).\r\n     - Advanced: I/O scheduling (C-SCAN for fairness); asynchronous I/O (AIO).\r\n     - Example: Linux io_uring for high-performance I/O (reduces syscalls).\r\n   - Secondary Storage Management\r\n     - Disk Scheduling: SSTF (shortest seek time first, seek time ~5ms/arm); elevator algorithm.\r\n     - Free Space: Bitmap (1 bit/block) vs. linked list; defragmentation compacts space.\r\n     - Advanced: SSD TRIM for wear-leveling; ZFS snapshots for versioning.\r\n     - Example: Windows chkdsk for error correction.\r\n   - Networking/Communication Management\r\n     - Protocols: TCP congestion control (Reno: AIMD); sockets for IPC.\r\n     - Shared Memory: vs. message passing (pipes, queues); RDMA for low-latency.\r\n     - Advanced: Virtual networks (VLANs); QoS (DiffServ marking).\r\n     - Example: Linux netfilter for firewalls.\r\n   - Protection and Security\r\n     - Access Control: RBAC (Role-Based); SELinux policies.\r\n     - Encryption: Kernel-level (dm-crypt); auditing (syslog).\r\n     - Advanced: ASLR (Address Space Layout Randomization) against exploits.\r\n     - Example: Windows BitLocker for full-disk encryption.\r\n   - Error Detection and Accounting\r\n     - Handling: ECC memory (Hamming code detects 2-bit errors); watchdog timers.\r\n     - Accounting: Quotas (disk, CPU); logging (kernel oops in Linux).\r\n     - Advanced: Crash dumps (minidumps) for postmortem analysis.\r\n\r\n2. Operating System Services\r\n   - User Interface: CLI (bash scripting) vs. GUI (Wayland compositor for efficiency).\r\n   - Program Execution: Loader resolves symbols; dynamic linking reduces memory.\r\n   - I/O Operations: Vectored I/O (scatter-gather) for efficiency.\r\n   - File System Manipulation: Mount namespaces in Linux for isolation.\r\n   - Communications: RPC (Remote Procedure Call) over gRPC.\r\n\r\n3. System Calls\r\n   - Interface: Trap to kernel mode; parameters via registers/stack.\r\n   - Categories: Process (fork, waitpid); File (open, lseek); Device (ioctl).\r\n   - Overhead: ~0.1-1µs per call; strace for tracing.\r\n   - Example: POSIX fork() creates child process, sharing resources via COW (Copy-On-Write).\r\n\r\nCore Role: Components optimize resources (e.g., scheduling minimizes wait time W = sum(bursts)/N); services abstract hardware for portability.\r\n\r\nTopic 3: System Design, Implementation, and Hardware Interaction\r\n\r\nOS design balances conflicting goals via modular, layered architectures, leveraging hardware features for performance.\r\n\r\n1. Design Goals\r\n   - User Goals: Usability (e.g., Android gestures); Reliability (99.999% uptime); Performance (low jitter for RTOS).\r\n   - System Goals: Modularity (microkernel vs. monolithic); Flexibility (modules loadable at runtime).\r\n   - Policy vs. Mechanism: e.g., Scheduler mechanism fixed, policy (FIFO vs. RR) configurable.\r\n   - Trade-offs: User convenience increases complexity; efficiency may sacrifice flexibility.\r\n\r\n2. Implementation\r\n   - Languages: Assembly for bootloaders (e.g., x86 real mode); C for kernel (low-level pointers); Rust for safety (Linux experiments).\r\n   - Layered Architecture: Microkernel (Minix: user-space drivers) vs. Monolithic (Linux: all in kernel for speed).\r\n   - Build Process: Cross-compilation; debugging with gdb/kgdb.\r\n   - Advanced: Kernels like seL4 (formally verified for security).\r\n   - Example: FreeBSD\'s modular kernel with loadable modules (kldload).\r\n\r\n3. Hardware Interaction\r\n   - Integration: OS manages interrupts (IRQ vectors); timers (HPET for precision).\r\n   - I/O Channels: Dedicated controllers (e.g., SATA AHCI); offload via co-processors.\r\n   - DMA: Bypasses CPU (transfer rate ~10GB/s for PCIe); scatter-gather lists.\r\n   - Co-dependency: Hardware virtualization (VT-x/AMD-V) enables VMs; OS uses ACPI for power management.\r\n   - Advanced: IOMMU for secure DMA; NUMA awareness in schedulers.\r\n   - Example: Linux VFIO for GPU passthrough in VMs.\r\n   - Trade-offs: Hardware offload reduces CPU load but increases complexity (e.g., driver bugs).\r\n\r\nCore Principle: Design separates concerns for maintainability; implementation optimizes for hardware, achieving high performance (e.g., context switch &lt;1µs on modern CPUs).\r\n</pre>\r\n</body>\r\n</html>', 'hard');
INSERT INTO `topics` (`topic_id`, `course_code`, `topic_name`, `content`, `difficulty`) VALUES ('32', 'CSA04', 'Unit 2: Process and Thread Management', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <title>Unit 2: Process and Thread Management</title>\r\n    <style>\r\n        body { font-family: Arial, sans-serif; line-height: 1.6; margin: 20px; }\r\n        h1 { color: #2C3E50; border-bottom: 2px solid #3498DB; padding-bottom: 10px; }\r\n        h2 { color: #2980B9; margin-top: 30px; }\r\n        h3 { color: #34495E; margin-top: 15px; }\r\n        table { width: 100%; border-collapse: collapse; margin-top: 20px; }\r\n        th, td { border: 1px solid #ddd; padding: 10px; text-align: left; }\r\n        th { background-color: #ECF0F1; }\r\n        .topic-summary { font-style: italic; margin-bottom: 10px; }\r\n    </style>\r\n</head>\r\n<body>\r\n\r\n    <h1>Unit 2: Process and Thread Management</h1>\r\n    <p class=\"topic-summary\">This unit encompasses three main topics: Processes and Threads, Process Scheduling, and Process Synchronization.</p>\r\n\r\n    <hr>\r\n    <h2>Topic 4: Processes and Threads and Their Concurrency</h2>\r\n    <p>The concepts of processes and threads form the foundation of modern multitasking operating systems.</p>\r\n\r\n    <h3>1. Process Concepts</h3>\r\n    <p>A process is defined as a program in execution. It represents a self-contained unit that includes its own memory space, resources, and execution state.</p>\r\n    <h4>Process Life Cycle States:</h4>\r\n    <ul>\r\n        <li><strong>New:</strong> The process is being created.</li>\r\n        <li><strong>Ready:</strong> The process is waiting to be executed.</li>\r\n        <li><strong>Running:</strong> The process is currently executing on the CPU.</li>\r\n        <li><strong>Waiting:</strong> The process is waiting for an event to occur, such as an I/O operation completion.</li>\r\n        <li><strong>Terminated:</strong> The process has finished execution.</li>\r\n    </ul>\r\n\r\n    <h3>2. Threads</h3>\r\n    <p>A thread is often referred to as a \"lightweight process\". Multiple threads can exist within a single process and share that process\'s resources (like code, data, and files), whereas a traditional process has its own full memory space.</p>\r\n    <h4>Design Advantages of Using Threads:</h4>\r\n    <ul>\r\n        <li><strong>Responsiveness:</strong> If one thread blocks (e.g., waiting for I/O), other threads within the same process can continue running.</li>\r\n        <li><strong>Resource Sharing:</strong> Threads share process resources, which eliminates the overhead required to create a new process and duplicate its resources.</li>\r\n        <li><strong>Economy:</strong> Creating a new thread is far less resource-intensive than creating an entire new process.</li>\r\n    </ul>\r\n\r\n    <h3>3. Inter-Process Communication (IPC)</h3>\r\n    <p>IPC allows cooperating processes to exchange information:</p>\r\n    <ul>\r\n        <li><strong>Shared Memory:</strong> Cooperating processes create a region of memory that they both share. This method enables high-speed data transfer by avoiding the need for redundant data copies.</li>\r\n        <li><strong>Message Passing:</strong> Processes use a communication link to send and receive messages. This is especially useful for smaller amounts of data or when processes are running on different computers.</li>\r\n    </ul>\r\n\r\n    <h3>4. Context Switching</h3>\r\n    <p>Context switching is the essential action of saving and restoring a process\'s state so the CPU can switch efficiently to another task.</p>\r\n\r\n    <hr>\r\n    <h2>Topic 5: Process Scheduling</h2>\r\n    <p>Process scheduling is a critical function aimed at maximizing CPU utilization and providing a responsive user environment.</p>\r\n\r\n    <h3>1. Scheduling Criteria</h3>\r\n    <p>The effectiveness of a scheduling algorithm is evaluated based on several criteria:</p>\r\n    <ol>\r\n        <li><strong>CPU Utilization:</strong> Keeping the CPU as busy as possible.</li>\r\n        <li><strong>Throughput:</strong> The number of processes completed per unit of time.</li>\r\n        <li><strong>Turnaround Time:</strong> The total time a process spends in the system, from creation to completion.</li>\r\n        <li><strong>Waiting Time:</strong> The total time a process spends waiting in the ready queue.</li>\r\n        <li><strong>Response Time:</strong> The time from a request\'s submission to the first response, crucial for interactive applications.</li>\r\n    </ol>\r\n\r\n    <h3>2. Scheduling Algorithms</h3>\r\n    <table>\r\n        <thead>\r\n            <tr>\r\n                <th>Algorithm</th>\r\n                <th>Description</th>\r\n                <th>Key Characteristic & Trade-off</th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n            <tr>\r\n                <td><strong>First Come First Served (FCFS)</strong></td>\r\n                <td>Processes jobs in the order they arrive.</td>\r\n                <td>Simple to implement, but can lead to the <em>convoy effect</em>, resulting in a long average waiting time.</td>\r\n            </tr>\r\n            <tr>\r\n                <td><strong>Shortest Job First (SJF)</strong></td>\r\n                <td>Schedules the job with the shortest execution time first.</td>\r\n                <td>Optimal for minimizing average waiting time. Impractical because the process burst time is usually unknown.</td>\r\n            </tr>\r\n            <tr>\r\n                <td><strong>Priority Scheduling</strong></td>\r\n                <td>Assigns a priority to each process and schedules the highest priority one first.</td>\r\n                <td>Effective, but carries the risk of <em>starvation</em>, where a low-priority process may never run.</td>\r\n            </tr>\r\n            <tr>\r\n                <td><strong>Round Robin (RR)</strong></td>\r\n                <td>Assigns a small time unit (time slice) to each process. Preempted and put at the end of the queue when the slice expires.</td>\r\n                <td>Designed for time-sharing systems, aiming to minimize response time for interactive tasks.</td>\r\n            </tr>\r\n        </tbody>\r\n    </table>\r\n\r\n    <h3>3. Process Scheduling Problem Analysis (Examples)</h3>\r\n    <table>\r\n        <thead>\r\n            <tr>\r\n                <th>Algorithm</th>\r\n                <th>Average Turnaround Time</th>\r\n                <th>Average Waiting Time</th>\r\n                <th>Average Response Time</th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n            <tr>\r\n                <td>FCFS</td>\r\n                <td>16.75 ms</td>\r\n                <td>10.5 ms</td>\r\n                <td>10.5 ms</td>\r\n            </tr>\r\n            <tr>\r\n                <td>Non-Preemptive SJF</td>\r\n                <td>8.00 ms</td>\r\n                <td>2.5 ms</td>\r\n                <td>2.5 ms</td>\r\n            </tr>\r\n            <tr>\r\n                <td>Preemptive SJF</td>\r\n                <td>9.00 ms</td>\r\n                <td>2.75 ms</td>\r\n                <td>0.00 ms</td>\r\n            </tr>\r\n            <tr>\r\n                <td>Non-Preemptive Priority</td>\r\n                <td>16.75 ms</td>\r\n                <td>11.00 ms</td>\r\n                <td>11.00 ms</td>\r\n            </tr>\r\n            <tr>\r\n                <td>Round Robin (2 ms)</td>\r\n                <td>15.00 ms</td>\r\n                <td>8.75 ms</td>\r\n                <td>0.00 ms</td>\r\n            </tr>\r\n        </tbody>\r\n    </table>\r\n\r\n    <hr>\r\n    <h2>Topic 6: Process Synchronization</h2>\r\n    <p>Process synchronization manages the cooperation and interaction between processes, especially when accessing shared data.</p>\r\n\r\n    <h3>1. Critical Section Problem</h3>\r\n    <p>The <strong>Critical Section</strong> is the part of a program where shared resources are accessed. To solve the critical section problem, three requirements must be met:</p>\r\n    <ul>\r\n        <li><strong>Mutual Exclusion:</strong> Only one process can execute in its critical section at any time.</li>\r\n        <li><strong>Progress:</strong> A selection process for entry cannot be postponed indefinitely if no process is in its critical section.</li>\r\n        <li><strong>Bounded Waiting:</strong> There must be a limit on the number of times other processes are allowed to enter their critical sections after a process has requested entry.</li>\r\n    </ul>\r\n\r\n    <h3>2. Synchronization Mechanisms</h3>\r\n    <p>The mechanisms used to achieve synchronization include:</p>\r\n    <ul>\r\n        <li><strong>Synchronization Hardware:</strong> Provides atomic operations (indivisible operations) like <em>Test and Set Lock</em>.</li>\r\n        <li><strong>Semaphores:</strong> Integer variables manipulated by two atomic operations: <code>wait</code> (or P) and <code>signal</code> (or V).</li>\r\n        <li><strong>Monitors:</strong> A higher-level synchronization construct.</li>\r\n    </ul>\r\n\r\n    <h3>3. Classical Problems of Synchronization</h3>\r\n    <p>These problems are commonly used to test the effectiveness of synchronization mechanisms:</p>\r\n    <ul>\r\n        <li>Bounded-Buffer Problem.</li>\r\n        <li>Readers-Writers Problem.</li>\r\n        <li>Dining Philosophers Problem.</li>\r\n    </ul>\r\n\r\n</body>\r\n</html>', 'easy');
