INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('21', 'CSA17', 'When are Utility-Based Agents particularly useful?', 'When the environment is fully observable', 'When there are conflicting goals', 'When the agent has no memory', 'When actions are deterministic', 'B');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('22', 'CSA17', 'What is the first step for a Problem-Solving Agent?', 'Search for a solution', 'Execute the solution', 'Problem Formulation', 'Goal Formulation', 'D');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('23', 'CSA17', 'Which of the following is listed as a \'Toy Problem\' in AI search techniques?', 'Robot Navigation', 'Traveling Salesperson Problem (TSP)', 'VLSI Layout', '8-Puzzle', 'D');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('24', 'CSA17', 'The Traveling Salesperson Problem (TSP) is an example of what kind of AI problem?', 'Toy Problem', 'Constraint Satisfaction Problem', 'Real-World Problem', 'Adversarial Search Problem', 'C');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('25', 'CSA17', 'In a search tree, what does `g(n)` represent?', 'The estimated cost to the goal', 'The total cost of the path', 'The depth of the node', 'The cost from the initial state to the current node', 'D');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('26', 'CSA17', 'What does \'Completeness\' mean when measuring the performance of a search algorithm?', 'It finds the best solution', 'It always finds a solution if one exists', 'It completes quickly', 'It uses minimal memory', 'B');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('27', 'CSA17', 'Which uninformed search strategy expands the shallowest unexpanded node?', 'Depth-First Search (DFS)', 'Uniform-Cost Search (UCS)', 'Breadth-First Search (BFS)', 'Iterative Deepening DFS', 'C');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('28', 'CSA17', 'Under what condition is Breadth-First Search (BFS) optimal?', 'Always', 'Never', 'If path cost is a non-decreasing function of depth', 'If the branching factor is 1', 'C');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('29', 'CSA17', 'What is the time complexity of Breadth-First Search (BFS), where \'b\' is the branching factor and \'d\' is the depth?', 'O(d)', 'O(b)', 'O(bd)', 'O(b^d)', 'D');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('30', 'CSA17', 'Uniform-Cost Search (UCS) expands the node with the:', 'Highest depth', 'Lowest path cost', 'Most children', 'Fewest actions', 'B');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('31', 'CSA17', 'How does Uniform-Cost Search (UCS) manage its nodes compared to a typical BFS?', 'It uses a stack instead of a queue', 'It uses a priority queue instead of a regular queue', 'It uses a hash table', 'It doesn\'t use a queue', 'B');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('32', 'CSA17', 'Which uninformed search strategy expands the deepest unexpanded node?', 'Breadth-First Search (BFS)', 'Uniform-Cost Search (UCS)', 'Depth-First Search (DFS)', 'A* Search', 'C');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('33', 'CSA17', 'Depth-First Search (DFS) typically uses which mechanism when it reaches a dead end?', 'Restarting from the root', 'Backtracking', 'Pruning', 'Expanding the shallowest node', 'B');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('34', 'CSA17', 'Is Depth-First Search (DFS) a complete algorithm?', 'Yes, always', 'No, it can get stuck in infinite loops', 'Only if the search space is finite', 'Only if the branching factor is small', 'B');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('35', 'CSA17', 'What is the space complexity of Depth-First Search (DFS), where \'b\' is branching factor and \'m\' is max depth?', 'O(b^m)', 'O(m)', 'O(bm) - very memory efficient', 'O(b+m)', 'C');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('36', 'CSA17', 'What is a Heuristic Function (h(n))?', 'The actual cost from node n to the goal', 'A measure of node depth', 'An estimate of the cost from node n to the goal', 'The cost from the start node to n', 'C');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('37', 'CSA17', 'Which informed search strategy expands the node that appears to be closest to the goal by minimizing h(n)?', 'A* Search', 'Uniform-Cost Search', 'Greedy Best-First Search', 'Breadth-First Search', 'C');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('38', 'CSA17', 'Is Greedy Best-First Search optimal?', 'Yes, always', 'No', 'Only if the heuristic is admissible', 'Only for very shallow trees', 'B');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('39', 'CSA17', 'The A* search algorithm expands the node that minimizes which function?', 'h(n)', 'g(n)', 'f(n) = g(n) + h(n)', 'f(n) = g(n) - h(n)', 'C');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('40', 'CSA17', 'For A* search to be optimal, its heuristic function h(n) must possess which property?', 'Consistency', 'Optimality', 'Completeness', 'Admissibility', 'D');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('41', 'CSA17', 'What defines an admissible heuristic in A* search?', 'It always finds the true cost to reach the goal', 'It never overestimates the true cost to reach the goal', 'It always underestimates the true cost to reach the goal', 'It is always zero', 'B');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('42', 'CSA17', 'Which local search algorithm continually moves in the direction of increasing value but can get stuck at local maxima?', 'Simulated Annealing', 'Genetic Algorithms', 'Hill-Climbing Search', 'A* Search', 'C');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('43', 'CSA17', 'Simulated Annealing is similar to hill-climbing but allows for \'bad\' moves to escape local maxima, with the probability of such moves:', 'Increasing over time', 'Remaining constant', 'Decreasing over time', 'Only occurring at the start', 'C');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('44', 'CSA17', 'Genetic Algorithms are a search approach inspired by:', 'Physics laws', 'Biological evolution', 'Social dynamics', 'Economic theories', 'B');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('45', 'CSA17', 'Which of the following are components used by Genetic Algorithms to generate new states?', 'Backtracking, recursion, iteration', 'Selection, crossover, and mutation', 'Minimax, alpha-beta, pruning', 'Goal formulation, problem formulation, execution', 'B');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('46', 'CSA17', 'In a Constraint Satisfaction Problem (CSP), a problem is solved when:', 'All variables have unique values', 'Each variable has a value that satisfies all constraints on the variable', 'The solution path is optimal', 'The search space is fully explored', 'B');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('47', 'CSA17', 'Map Coloring is an example of what type of AI problem?', 'Toy Problem', 'Constraint Satisfaction Problem (CSP)', 'Real-World Problem', 'Adversarial Search Problem', 'B');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('48', 'CSA17', 'Which algorithm is a recursive method for choosing the next move in a two-player game, assuming the opponent plays optimally?', 'A* Search', 'Minimax Algorithm', 'Hill-Climbing Search', 'Breadth-First Search', 'B');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('49', 'CSA17', 'What is Alpha-Beta Pruning?', 'A different game-playing algorithm', 'An optimization technique for the Minimax algorithm', 'A method for evaluating heuristic functions', 'A way to represent game states', 'B');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('50', 'CSA17', 'In logical agents, what is a Knowledge Base (KB)?', 'A set of rules for actions', 'A mechanism for deriving new sentences', 'A set of sentences representing facts about the world', 'The agent\'s sensor data', 'C');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('51', 'CSA17', 'What is the primary role of an Inference Engine in logical agents?', 'To perceive the environment', 'To execute actions', 'To derive new sentences from old ones', 'To store facts', 'C');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('52', 'CSA17', 'The function used to add new facts to a Knowledge Base is called:', 'GET', 'TELL', 'ASK', 'REPORT', 'B');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('53', 'CSA17', 'What are \'Atomic Sentences\' in Propositional Logic?', 'Sentences connected by logical connectives', 'Single proposition symbols', 'Sentences with quantifiers', 'Sentences that are always true', 'B');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('54', 'CSA17', 'What does \'Entailment (KB |= α)\' mean in Propositional Logic?', 'KB is true if α is true', 'α is false if KB is false', 'Sentence α is true in all worlds where KB is true', 'α is a component of KB', 'C');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('55', 'CSA17', 'An inference algorithm is said to be \'Sound\' if it:', 'Always derives a solution', 'Is computationally efficient', 'Only derives entailed sentences', 'Can derive any entailed sentence', 'C');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('56', 'CSA17', 'If an inference algorithm can derive any entailed sentence, it is considered:', 'Sound', 'Optimal', 'Complete', 'Admissible', 'C');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('57', 'CSA17', 'In First-Order Logic (FOL), what do \'Predicates\' represent?', 'Objects', 'Relations', 'Functions', 'Quantifiers', 'B');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('58', 'CSA17', 'The Universal Quantifier (∀) in First-Order Logic means:', 'There exists...', 'For some...', 'For all...', 'It is false that...', 'C');
INSERT INTO `mcq_combined` (`question_id`, `course_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`) VALUES ('59', 'CSA17', 'What is the process of finding substitutions that make different logical expressions look identical in FOL?', 'Resolution', 'Chaining', 'Unification', 'Quantification', 'C');
