INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('2', 'CSA17', 'What are the four primary approaches to defining Artificial Intelligence?', 'four approaches, Artificial Intelligence', 'The four primary approaches are **Thinking Humanly** (cognitive modeling), **Thinking Rationally** (laws of thought), **Acting Humanly** (Turing test), and **Acting Rationally** (rational agent) [1].', 'easy', '4', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('3', 'CSA17', 'Which approach to AI involves the cognitive modeling of human thought processes?', 'cognitive modeling, human thought, AI approach', 'The cognitive modeling approach, which focuses on **Thinking Humanly**, involves modeling human thought processes [1].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('4', 'CSA17', 'Explain the \"laws of thought\" approach to AI.', 'laws of thought, AI approach', 'The \"**laws of thought**\" approach to AI is about **Thinking Rationally**, aiming to build systems that can reason logically [1].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('5', 'CSA17', 'What is the Turing test approach in the context of AI?', 'Turing test, AI approach', 'The **Turing test approach** focuses on **Acting Humanly**, aiming for AI systems to behave indistinguishably from a human [1].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('6', 'CSA17', 'Describe the rational agent approach to Artificial Intelligence.', 'rational agent, AI approach', 'The **rational agent approach** focuses on **Acting Rationally**, aiming for AI systems to act in a way that achieves the best outcome [1].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('7', 'CSA17', 'List at least three problem domains that constitute AI problems.', 'AI problems, domains', 'AI problems include **Knowledge Representation**, **Natural Language Processing (NLP)**, **Planning**, **Robotics**, and **Speech Processing** [1].', 'easy', '3', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('8', 'CSA17', 'Which AI problem domain deals with how an AI system can store and use information about the world?', 'store, use information, AI problem, Knowledge Representation', '**Knowledge Representation** is the AI problem domain that deals with how an AI system can store and use information about the world [1].', 'medium', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('9', 'CSA17', 'What does NLP stand for in the context of AI problems?', 'NLP, AI problems', '**NLP** stands for **Natural Language Processing** [1].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('10', 'CSA17', 'Name an AI problem domain focused on enabling machines to perform physical tasks in the real world.', 'physical tasks, real world, AI problem', '**Robotics** is an AI problem domain focused on enabling machines to perform physical tasks in the real world [1].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('11', 'CSA17', 'What AI problem involves interpreting human speech?', 'interpreting human speech, AI problem', '**Speech Processing** is the AI problem that involves interpreting human speech [1].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('12', 'CSA17', 'Identify at least five foundational fields from which AI draws its concepts.', 'foundational fields, AI concepts', 'AI draws concepts from **Philosophy**, **Mathematics**, **Economics**, **Neuroscience**, **Psychology**, **Computer Engineering**, **Control Theory & Cybernetics**, and **Linguistics** [2].', 'medium', '5', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('13', 'CSA17', 'Which foundational field contributes to AI\'s understanding of decision-making under uncertainty?', 'decision-making, uncertainty, foundational field, AI', '**Economics** is a foundational field that contributes to AI\'s understanding of decision-making [2].', 'medium', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('14', 'CSA17', 'What role does Neuroscience play in the foundations of AI?', 'Neuroscience, foundations of AI', '**Neuroscience** contributes to the foundations of AI by providing insights into how the human brain works, which inspires AI models [2].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('15', 'CSA17', 'Name two fields related to the study of language that are foundational to AI.', 'language, foundational, AI', '**Psychology** and **Linguistics** are two fields related to the study of language that are foundational to AI [2].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('16', 'CSA17', 'How does Computer Engineering contribute to AI?', 'Computer Engineering, AI contribution', '**Computer Engineering** provides the hardware and architectural basis for implementing AI systems [2].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('17', 'CSA17', 'What period is referred to as \"The gestation of AI\"?', 'gestation of AI, period', 'The period from **1943-1955** is referred to as \"**The gestation of AI**\" [2].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('18', 'CSA17', 'When is the \"birth of AI\" generally considered to have occurred?', 'birth of AI, year', 'The \"**birth of AI**\" is considered to have occurred in **1956** [2].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('19', 'CSA17', 'Which historical period of AI was characterized by \"early enthusiasm and great expectations\"?', 'early enthusiasm, great expectations, AI history', 'The period from **1952-1969** was characterized by \"**early enthusiasm and great expectations**\" [2].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('20', 'CSA17', 'What significant shift in AI happened between 1966-1973?', '1966-1973, AI shift', 'Between **1966-1973**, AI experienced \"**A dose of reality**\", indicating a period of re-evaluation [2].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('21', 'CSA17', 'What type of AI systems gained prominence between 1969-1979?', '1969-1979, AI systems', '**Knowledge-based systems** gained prominence between 1969-1979 [2].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('22', 'CSA17', 'Since 1980, what major development has occurred in the field of AI concerning its application?', '1980-Present, AI industry', 'Since **1980**, AI has become an **industry** [2].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('23', 'CSA17', 'What major AI concept saw a return to prominence starting in 1986?', '1986-Present, AI concept return', 'The **return of neural networks** began in 1986 [2].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('24', 'CSA17', 'When did AI begin to adopt the scientific method more rigorously?', 'scientific method, AI, 1987', 'AI adopted the **scientific method** starting in **1987** [3].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('25', 'CSA17', 'What emerged in AI starting from 1995?', '1995-Present, emergence, AI', 'The emergence of **intelligent agents** began in 1995 [3].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('26', 'CSA17', 'What significant resource became widely available in AI from 2001 onwards?', '2001-Present, resource availability, AI', 'The availability of **very large datasets** became prominent in AI from 2001 onwards [3].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('27', 'CSA17', 'How does an intelligent agent interact with its environment?', 'intelligent agent, interact, environment', 'An agent perceives its environment through **sensors** and acts upon that environment through **actuators** [3].', 'easy', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('28', 'CSA17', 'Define the term \"Agent Function\".', 'Agent Function, definition', 'An **Agent Function** maps percept sequences to actions [3].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('29', 'CSA17', 'What is an \"Agent Program\"?', 'Agent Program, definition', 'An **Agent Program** is the implementation of the agent function [3].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('30', 'CSA17', 'What is the concept of rationality for an intelligent agent?', 'rationality, intelligent agent', 'A **rational agent** is one that acts to achieve the **best outcome** or, when there is uncertainty, the **best expected outcome** [3, 4].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('31', 'CSA17', 'What does the acronym PEAS stand for in the context of describing task environments for AI agents?', 'PEAS framework, task environment, acronym', '**PEAS** stands for **Performance Measure, Environment, Actuators, Sensors** [4].', 'easy', '4', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('32', 'CSA17', 'List at least four properties used to describe task environments.', 'properties, task environments', 'Properties of task environments include **Fully observable vs. Partially observable**, **Single-agent vs. Multi-agent**, **Deterministic vs. Stochastic**, **Episodic vs. Sequential**, **Static vs. Dynamic**, **Discrete vs. Continuous**, and **Known vs. Unknown** [4].', 'medium', '4', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('33', 'CSA17', 'Differentiate between a \"Fully observable\" and \"Partially observable\" environment.', 'Fully observable, Partially observable, environment', 'A **fully observable** environment means the agent\'s sensors can detect all aspects of the state relevant to the choice of action, while a **partially observable** environment means some relevant parts are hidden [4].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('34', 'CSA17', 'Explain the difference between a \"Deterministic\" and \"Stochastic\" task environment.', 'Deterministic, Stochastic, environment', 'In a **deterministic** environment, the next state is completely determined by the current state and the action executed, whereas in a **stochastic** environment, there is uncertainty about the outcome [4].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('35', 'CSA17', 'What is meant by an \"Episodic\" task environment?', 'Episodic, environment', 'In an **episodic** task environment, the agent\'s experience is divided into \"episodes,\" where each episode consists of the agent perceiving and then performing a single action. The choice of action depends only on the current episode [4].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('36', 'CSA17', 'How do Simple Reflex Agents make decisions?', 'Simple Reflex Agents, decisions', '**Simple Reflex Agents** select actions based on the **current percept**, ignoring the rest of the percept history [5].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('37', 'CSA17', 'What is the primary difference in decision-making between a Simple Reflex Agent and a Model-Based Reflex Agent?', 'Simple Reflex, Model-Based Reflex, difference, decision', '**Model-Based Reflex Agents** maintain an **internal state** to track aspects of the world they can\'t see, which Simple Reflex Agents do not, allowing them to base decisions on more than just the current percept [5].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('38', 'CSA17', 'Describe the flow of a Simple Reflex Agent\'s decision process.', 'Simple Reflex Agent, flow, decision process', 'The flow of a Simple Reflex Agent is: **Sensors -> \"What the world is like now?\" -> Condition-Action Rules -> \"What action I should do now?\" -> Actuators** [5].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('39', 'CSA17', 'What additional component do Model-Based Reflex Agents utilize that Simple Reflex Agents do not?', 'Model-Based Reflex Agents, component', 'Model-Based Reflex Agents maintain an **internal \'State\'** to track aspects of the world they can\'t see [5].', 'medium', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('40', 'CSA17', 'How do Goal-Based Agents determine their actions?', 'Goal-Based Agents, actions', '**Goal-Based Agents** act to **achieve specific goals**, considering these goals to determine what action will lead to a desirable state [6].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('41', 'CSA17', 'When are Utility-Based Agents particularly useful?', 'Utility-Based Agents, useful', '**Utility-Based Agents** are useful when there are **conflicting goals**, as they try to maximize their own expected \"happiness\" or utility [6].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('42', 'CSA17', 'What function is central to a Utility-Based Agent\'s decision-making process?', 'Utility-Based Agent, function, decision', 'A \"**Utility**\" function is central, measuring how \"happy\" the agent would be in a given state, allowing it to make trade-offs [7].', 'medium', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('43', 'CSA17', 'What is a Problem-Solving Agent and what kind of agent is it?', 'Problem-Solving Agent, definition, type', 'A **Problem-Solving Agent** is a type of **goal-based agent** that uses search to find a sequence of actions that will lead to a goal state [7].', 'easy', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('44', 'CSA17', 'List the four steps involved in the process of a Problem-Solving Agent.', 'Problem-Solving Agent, steps', 'The four steps are **Goal Formulation**, **Problem Formulation**, **Search for a solution**, and **Execute the solution** [7].', 'easy', '4', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('45', 'CSA17', 'Name two \"toy problems\" often used in AI search.', 'toy problems, AI search', 'Examples of toy problems include **8-Puzzle**, **8-Queens**, **Water Jug Problem**, and **Cryptarithmetic** [7].', 'easy', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('46', 'CSA17', 'Identify two real-world problems that can be addressed using AI search techniques.', 'real-world problems, AI search', 'Real-world problems include **Traveling Salesperson Problem (TSP)**, **VLSI Layout**, **Robot Navigation**, and **Assembly Sequencing** [8].', 'easy', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('47', 'CSA17', 'What is a \"State\" in the context of a search tree?', 'State, search tree, definition', 'A \"**State**\" is a **configuration of the problem** within a search tree [8].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('48', 'CSA17', 'Define \"Path Cost (g(n))\" in a search tree.', 'Path Cost, g(n), search tree, definition', '**Path Cost (g(n))** is the **cost from the initial state to the current node** [8].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('49', 'CSA17', 'What does \"Depth\" represent in a search tree?', 'Depth, search tree, definition', '**Depth** represents the **number of steps from the root** in a search tree [8].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('50', 'CSA17', 'What are the four key measures for evaluating the performance of search algorithms?', 'performance, search algorithms, measures', 'The four key measures are **Completeness**, **Optimality**, **Time Complexity**, and **Space Complexity** [9].', 'easy', '4', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('51', 'CSA17', 'What does \"Completeness\" mean for a search algorithm?', 'Completeness, search algorithm, definition', '**Completeness** refers to whether a search algorithm always finds a solution if one exists [9].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('52', 'CSA17', 'Explain \"Optimality\" in the context of search algorithm performance.', 'Optimality, search algorithm, definition', '**Optimality** means whether a search algorithm finds the best (least-cost) solution [9].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('53', 'CSA17', 'How does Breadth-First Search (BFS) decide which node to expand next?', 'Breadth-First Search, BFS, expand node', 'BFS expands the **shallowest unexpanded node** [9].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('54', 'CSA17', 'Is Breadth-First Search (BFS) a complete and optimal search strategy?', 'BFS, complete, optimal', 'Yes, **BFS is complete** [9], and it is **optimal** if the path cost is a non-decreasing function of depth [9].', 'easy', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('55', 'CSA17', 'What is the time and space complexity of Breadth-First Search (BFS)?', 'BFS, time complexity, space complexity', 'The **time and space complexity of BFS is O(bd)**, where b is the branching factor and d is the depth [10].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('56', 'CSA17', 'What is the primary difference in how Uniform-Cost Search (UCS) selects nodes compared to BFS?', 'Uniform-Cost Search, UCS, BFS, difference, select nodes', '**UCS expands the node with the lowest path cost (g(n))** [10], while BFS expands the shallowest node. UCS essentially uses a priority queue, unlike BFS\'s regular queue [10].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('57', 'CSA17', 'How does Depth-First Search (DFS) explore the search tree?', 'Depth-First Search, DFS, explore tree', 'DFS expands the **deepest unexpanded node** and uses **backtracking** when it reaches a dead end [10].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('58', 'CSA17', 'Is Depth-First Search (DFS) complete and optimal? Why or why not?', 'DFS, complete, optimal', 'No, **DFS is not complete** because it can get stuck in infinite loops [10], and it is **not optimal** [10].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('59', 'CSA17', 'What is a key advantage of Depth-First Search (DFS) regarding memory usage?', 'DFS, memory usage, advantage', '**DFS is very memory efficient**, with a space complexity of O(bm), where m is the max depth [10].', 'medium', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('60', 'CSA17', 'What is the main characteristic that distinguishes informed search strategies from uninformed search strategies?', 'informed search, uninformed search, characteristic', '**Informed search strategies use problem-specific knowledge (heuristics)** to find solutions more efficiently, while uninformed strategies use only the information available in the problem definition [11].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('61', 'CSA17', 'Define a Heuristic Function (h(n)).', 'Heuristic Function, h(n), definition', 'A **Heuristic Function (h(n))** is an **estimate of the cost from node n to the goal** [11].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('62', 'CSA17', 'How does Greedy Best-First Search determine which node to expand?', 'Greedy Best-First Search, expand node', '**Greedy Best-First Search** expands the node that appears to be **closest to the goal (minimizes h(n))** [11].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('63', 'CSA17', 'Is Greedy Best-First Search a complete and optimal algorithm?', 'Greedy Best-First Search, complete, optimal', 'No, **Greedy Best-First Search is neither complete nor optimal** [11].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('64', 'CSA17', 'What is the evaluation function used by the A* Search algorithm?', 'A* Search, evaluation function', '**A* Search** expands the node that minimizes **f(n) = g(n) + h(n)** [11].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('65', 'CSA17', 'Under what condition is the A* search algorithm guaranteed to be optimal?', 'A* search, optimal, condition', '**A* search is optimal if its heuristic function h(n) is admissible**, meaning it never overestimates the true cost to reach the goal [12].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('66', 'CSA17', 'What is a key characteristic of local search algorithms regarding their memory efficiency?', 'local search, memory efficient', '**Local search algorithms are very memory efficient** because they operate on a single current state [12].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('67', 'CSA17', 'Describe the basic operation of Hill-Climbing Search and its main drawback.', 'Hill-Climbing Search, operation, drawback', '**Hill-Climbing Search** continually moves in the direction of increasing value (\"uphill\"), but its main drawback is that it **can get stuck at local maxima** [12].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('68', 'CSA17', 'How does Simulated Annealing improve upon Hill-Climbing Search?', 'Simulated Annealing, Hill-Climbing, improvement', '**Simulated Annealing** improves upon Hill-Climbing by allowing for some \"**bad**\" moves to escape local maxima, with the probability of such moves decreasing over time [13].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('69', 'CSA17', 'What biological concept inspired Genetic Algorithms?', 'Genetic Algorithms, inspired by, biological concept', '**Genetic Algorithms** are inspired by **biological evolution** [13].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('70', 'CSA17', 'What three primary operators do Genetic Algorithms use to generate new states?', 'Genetic Algorithms, operators, new states', '**Genetic Algorithms** use **selection, crossover, and mutation** to generate new, better states [13].', 'easy', '3', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('71', 'CSA17', 'What defines a solved Constraint Satisfaction Problem (CSP)?', 'Constraint Satisfaction Problem, CSP, solved', 'A problem is solved in CSP when **each variable has a value that satisfies all the constraints on the variable** [13].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('72', 'CSA17', 'Give an example of a Constraint Satisfaction Problem related to map design.', 'CSP example, map design', '**Map Coloring** is a CSP where the goal is to assign colors to regions on a map such that no two adjacent regions have the same color [14].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('73', 'CSA17', 'Describe the Cryptarithmetic problem as an example of a CSP.', 'Cryptarithmetic, CSP example', '**Cryptarithmetic** is a CSP where the task is to assign unique digits to letters to solve an arithmetic puzzle, like SEND + MORE = MONEY [14].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('74', 'CSA17', 'What is the objective of the 4-Queens Problem?', '4-Queens Problem, objective', 'The objective of the **4-Queens Problem** is to place 4 queens on a 4x4 chessboard so that no queen can attack another [14].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('75', 'CSA17', 'What is the fundamental characteristic of Adversarial Search?', 'Adversarial Search, characteristic', '**Adversarial Search** involves searching in games where an **opponent is trying to win** [14].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('76', 'CSA17', 'How does the Minimax Algorithm make decisions in a two-player game?', 'Minimax Algorithm, decisions, two-player game', 'The **Minimax Algorithm** explores the game tree to find the move that **maximizes the player\'s score**, assuming the opponent will play optimally to minimize it [15].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('77', 'CSA17', 'What is the purpose of Alpha-Beta Pruning?', 'Alpha-Beta Pruning, purpose', '**Alpha-Beta Pruning** is an optimization technique for the minimax algorithm that safely \"**prunes**\" (ignores) large parts of the search tree that cannot influence the final decision [15].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('78', 'CSA17', 'What is a Logical Agent?', 'Logical Agent, definition', '**Logical Agents** are agents that can **represent knowledge and reason about it logically** [15].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('79', 'CSA17', 'Define Knowledge Base (KB).', 'Knowledge Base, KB, definition', 'A **Knowledge Base (KB)** is a **set of sentences representing facts about the world** [15].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('80', 'CSA17', 'What is the function of an Inference Engine in a logical agent?', 'Inference Engine, function, logical agent', 'An **Inference Engine** is a mechanism for **deriving new sentences from old ones** in a logical agent [15].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('81', 'CSA17', 'Name the two key functions associated with a Knowledge Base.', 'Knowledge Base, functions', 'The two key functions are **TELL** (to add new facts to the KB) and **ASK** (to query what is known) [16].', 'easy', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('82', 'CSA17', 'What are Atomic Sentences in Propositional Logic?', 'Atomic Sentences, Propositional Logic', '**Atomic Sentences** are **single proposition symbols** (e.g., P, Q) in Propositional Logic [16].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('83', 'CSA17', 'How are Complex Sentences formed in Propositional Logic?', 'Complex Sentences, Propositional Logic, formed', '**Complex Sentences** are constructed from simpler sentences using **logical connectives** (¬, ∧, ∨, ⇒, ⇔) [16].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('84', 'CSA17', 'Define \"Entailment (KB |= α)\" in propositional logic.', 'Entailment, KB |= α, propositional logic', 'Sentence α is **entailed by KB** if α is true in all worlds where KB is true [16].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('85', 'CSA17', 'When is an inference algorithm considered \"Sound\"?', 'Soundness, inference algorithm', 'An inference algorithm is **sound** if it only derives entailed sentences [16].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('86', 'CSA17', 'What does \"Completeness\" refer to for an inference algorithm in logic?', 'Completeness, inference algorithm, logic', 'An inference algorithm is **complete** if it can derive any entailed sentence [17].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('87', 'CSA17', 'How is First-Order Logic (FOL) more expressive than Propositional Logic?', 'First-Order Logic, FOL, expressive, Propositional Logic', '**First-Order Logic** is more expressive because it allows for **objects, relations, and quantifiers**, unlike Propositional Logic which deals only with true/false propositions [17].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('88', 'CSA17', 'What do \"Constants\" represent in First-Order Logic? Provide an example.', 'Constants, First-Order Logic, represent, example', '**Constants** stand for **objects** (e.g., John, Table) in First-Order Logic [17].', 'easy', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('89', 'CSA17', 'Explain the role of \"Predicates\" in FOL and give an example.', 'Predicates, FOL, role, example', '**Predicates** stand for **relations** (e.g., Brother(Richard, John)) in First-Order Logic [17].', 'easy', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('90', 'CSA17', 'What is the purpose of a \"Function\" in First-Order Logic?', 'Function, First-Order Logic, purpose', 'A **function** in First-Order Logic is a relation where there is only one value for a given input (e.g., Legs(cat)) [17].', 'medium', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('91', 'CSA17', 'What does the Universal Quantifier (∀) signify in FOL? Give an example.', 'Universal Quantifier, ∀, FOL, signify, example', 'The **Universal Quantifier (∀)** signifies \"**For all...**\" (e.g., ∀x, King(x) ⇒ Person(x)) in First-Order Logic [18].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('92', 'CSA17', 'How is the Existential Quantifier (∃) used in First-Order Logic? Provide an example.', 'Existential Quantifier, ∃, FOL, used, example', 'The **Existential Quantifier (∃)** signifies \"**There exists...**\" (e.g., ∃x, Crown(x) ∧ OnHead(x, John)) in First-Order Logic [18].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('93', 'CSA17', 'What is \"Unification\" in First-Order Logic inference?', 'Unification, First-Order Logic, inference', '**Unification** is the process of finding **substitutions that make different logical expressions look identical**, and it\'s a key component of all first-order inference algorithms [18].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('94', 'CSA17', 'Describe the approach of Forward Chaining in FOL inference.', 'Forward Chaining, FOL inference, approach', '**Forward Chaining** is a **data-driven approach** that starts with known facts in the KB and applies inference rules to derive new facts until the goal is reached [18].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('95', 'CSA17', 'How does Backward Chaining work in First-Order Logic?', 'Backward Chaining, First-Order Logic, how it works', '**Backward Chaining** is a **goal-driven approach** that starts with the goal and works backward to find facts that support it [19].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('96', 'CSA17', 'What is \"Resolution\" and how is it often used in First-Order Logic?', 'Resolution, First-Order Logic, used', '**Resolution** is a single, complete inference rule for FOL that can be used to prove theorems, often employed in **proof by refutation** [19].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('97', 'CSA17', 'Define a \"Learning Agent\".', 'Learning Agent, definition', 'A **Learning Agent** is an agent that can **improve its performance through observation and experience** [19].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('98', 'CSA17', 'List the four main components of a learning agent model.', 'learning agent, components', 'A learning agent model has a **Performance Element**, a **Critic**, a **Learning Element**, and a **Problem Generator** [19].', 'easy', '4', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('99', 'CSA17', 'What is the characteristic of data used in Supervised Learning?', 'Supervised Learning, data characteristic', 'In **Supervised Learning**, the agent learns from a set of **labeled training examples** [20].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('100', 'CSA17', 'How does an agent learn in Unsupervised Learning?', 'Unsupervised Learning, agent learn', 'In **Unsupervised Learning**, the agent learns **patterns from unlabeled data** [20].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('101', 'CSA17', 'Describe the learning mechanism in Reinforcement Learning.', 'Reinforcement Learning, learning mechanism', 'In **Reinforcement Learning**, the agent learns by receiving **rewards or punishments for its actions** [20].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('102', 'CSA17', 'What is Inductive Learning?', 'Inductive Learning, definition', '**Inductive Learning** is learning a general function or rule from a set of specific examples [20].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('103', 'CSA17', 'How are Decision Trees structured?', 'Decision Trees, structure', '**Decision Trees** are tree-structured models where each internal node represents a test on an attribute, each branch represents an outcome of the test, and each leaf node represents a class label [20].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('104', 'CSA17', 'State Bayes\' Rule for relating conditional probabilities.', 'Bayes\' Rule, formula', 'Bayes\' Rule is: **P(H∣E)=P(E)P(E∣H)⋅P(H)** [21].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('105', 'CSA17', 'In Bayes\' Rule, what do P(H) and P(E|H) represent?', 'Bayes\' Rule, P(H), P(E|H)', 'In Bayes\' Rule, **P(H) is the prior probability** and **P(E|H) is the likelihood** [21].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('106', 'CSA17', 'What is the goal of learning with complete data using Maximum Likelihood?', 'Learning, Complete Data, Maximum Likelihood', 'When data is complete, the goal of learning with **Maximum Likelihood** is to find the model parameters that **maximize the likelihood of the observed data** [21].', 'medium', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('107', 'CSA17', 'What is the structure of a neuron in a neural network?', 'neuron, neural network, structure', 'A **neuron** receives inputs, computes a weighted sum, and applies an activation function to produce an output [22].', 'medium', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('108', 'CSA17', 'What are Perceptrons?', 'Perceptrons, definition', '**Perceptrons (Single-Layer)** are the simplest type of neural network, used for classifying linearly separable data [22].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('109', 'CSA17', 'What is the advantage of Multi-Layer Networks over Perceptrons?', 'Multi-Layer Networks, Perceptrons, advantage', '**Multi-Layer Networks** can represent more complex functions than Perceptrons due to having one or more hidden layers [22].', 'medium', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('110', 'CSA17', 'What distinguishes Recurrent Neural Networks (RNNs) from other types of networks?', 'Recurrent Neural Networks, RNNs, distinguishing feature', '**Recurrent Neural Networks (RNNs)** have **connections pointing backward**, allowing them to have \"memory\" and handle sequential data [23].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('111', 'CSA17', 'What type of machine learning task are Kernel Machines (Support Vector Machines - SVMs) used for?', 'Kernel Machines, SVMs, machine learning task', '**Kernel Machines (Support Vector Machines - SVMs)** are powerful supervised learning algorithms used for **classification and regression** [23].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('112', 'CSA17', 'What is the main goal of an SVM?', 'SVM, goal', 'The main goal of an **SVM** is to find a **hyperplane** in an N-dimensional space that distinctly classifies the data points, specifically the one with the maximum margin between different classes [23].', 'medium', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('113', 'CSA17', 'How does a Reinforcement Learning agent learn?', 'Reinforcement Learning, agent learns', 'A **Reinforcement Learning** agent learns from the **consequences of its actions**, rather than from being explicitly taught [24].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('114', 'CSA17', 'What is the primary concern of Reinforcement Learning?', 'Reinforcement Learning, primary concern', '**Reinforcement Learning** is concerned with how an agent ought to take actions in an environment to **maximize some notion of cumulative reward** [24].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('115', 'CSA17', 'What is a search engine?', 'search engine, definition', 'A **search engine** is a web-based tool that enables users to locate information on the World Wide Web [24].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('116', 'CSA17', 'Name two examples of search engines.', 'search engines, examples', 'Examples of search engines include **Google, Yahoo!, and Bing** [24].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('117', 'CSA17', 'What are the two main types of search engines mentioned in the sources?', 'search engines, types', 'The two main types are **Crawler-based engines** (using \"spiders\") and **Human-powered directories**, as well as hybrid engines [24, 25].', 'easy', '2', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('118', 'CSA17', 'How does Boolean Searching work?', 'Boolean Searching, how it works', '**Boolean Searching** works by using **operators like AND, OR, NOT** to combine keywords [25].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('119', 'CSA17', 'What is Phrase Searching?', 'Phrase Searching, definition', '**Phrase Searching** is searching for an **exact phrase**, often by enclosing it in quotes (e.g., \"black blue\") [25].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('120', 'CSA17', 'How can wildcard/truncation searching be performed?', 'Wildcard, Truncation Searching, how to', '**Wildcard/Truncation Searching** uses **symbols (like * or ?)** to represent unknown characters or word endings [25].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('121', 'CSA17', 'Why are website domain and layout important for SEO?', 'website domain, layout, SEO', 'The **structure and URL of a website are important for SEO** [25].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('122', 'CSA17', 'What is Keyword Optimization in SEO?', 'Keyword Optimization, SEO, definition', '**Keyword Optimization** is the process of researching, analyzing, and selecting the best keywords to target to attract qualified traffic from search engines [26].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('123', 'CSA17', 'What is Keyword Prominence?', 'Keyword Prominence, definition', '**Keyword Prominence** refers to how early keywords appear on a page [26].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('124', 'CSA17', 'What is Keyword Frequency/Density?', 'Keyword Frequency, Keyword Density, definition', '**Keyword Frequency/Density** refers to how often a keyword appears on a page [26].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('125', 'CSA17', 'What are <meta> tags used for in SEO?', 'meta tags, SEO, purpose', '**Meta Tag Optimization** involves using `<meta>` tags to provide information about a page to search engines (e.g., meta description, meta keywords) [26].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('126', 'CSA17', 'Why is the <title> tag critical for SEO?', 'title tag, SEO, critical', 'The `<title>` tag is a **critical place to include important keywords** for SEO [26].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('127', 'CSA17', 'What signal do anchor tags provide to search engines?', 'Anchor Tag, SEO, signal', 'The text used in a hyperlink (<a> tag) is a **strong signal to search engines about the topic of the linked page** [27].', 'medium', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('128', 'CSA17', 'Why is XHTML Validation important for search engines?', 'XHTML Validation, search engines, importance', '**XHTML Validation** ensures a website\'s code is clean and follows web standards, which **helps search engines crawl it properly** [27].', 'medium', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('129', 'CSA17', 'How is AI expected to impact Health Care in the future?', 'AI, Health Care, future impact', 'AI is expected to assist in **complex surgeries and diagnostics** in Health Care [27].', 'easy', '1', '2025-09-13 21:37:55');
INSERT INTO `theory_questions` (`question_id`, `course_id`, `question_text`, `keywords`, `complete_answer`, `difficulty_level`, `marks`, `created_at`) VALUES ('130', 'CSA17', 'What technologies are used by Autonomous Vehicles for navigation?', 'Autonomous Vehicles, navigation technologies', 'Autonomous Vehicles use **sensors like cameras, radar, and lidar** for navigation [27].', 'easy', '1', '2025-09-13 21:37:55');
